    #[test]
    fn assistant_turn_shows_full_text_not_clipped_at_60() {
        // #302: a long thinking line must appear in full (no 60-char clip,
        // no debug quoting) so horizontal scroll can reveal it.
        let long = "x".repeat(120);
        let line = format!(
            "{{\"type\":\"assistant\",\"message\":{{\"content\":[{{\"type\":\"text\",\"text\":\"{long}\"}}]}}}}"
        );
        let mut turn = 0;
        let item = parse_json_event(&line, &mut turn).expect("assistant item");
        let text: String = item.text.spans.iter().map(|s| s.text.as_str()).collect();
        assert!(
            text.contains(&long),
            "full text should be present: {text:?}"
        );
        assert!(!text.contains('"'), "should not be debug-quoted: {text:?}");
    }

    #[test]
    fn assistant_turn_shows_thinking_when_no_text_or_tools() {
        // #302 "empty turns": a reasoning-only turn (thinking block, no text,
        // no tool_use) must surface the thinking text, not render as bare
        // "Turn N".
        let line = "{\"type\":\"assistant\",\"message\":{\"content\":[\
            {\"type\":\"thinking\",\"thinking\":\"weighing the two options here\"}]}}";
        let mut turn = 0;
        let item = parse_json_event(line, &mut turn).expect("assistant item");
        let text: String = item.text.spans.iter().map(|s| s.text.as_str()).collect();
        assert!(
            text.contains("weighing the two options"),
            "thinking missing: {text:?}"
        );
    }

    #[test]
    fn assistant_turn_shows_both_text_and_tools() {
        // #302: a turn that both thinks and calls a tool must show the text
        // AND the tool list — previously the text was dropped (bare summary).
        let line = "{\"type\":\"assistant\",\"message\":{\"content\":[\
            {\"type\":\"text\",\"text\":\"planning the edit\"},\
            {\"type\":\"tool_use\",\"name\":\"Edit\"}]}}";
        let mut turn = 0;
        let item = parse_json_event(line, &mut turn).expect("assistant item");
        let text: String = item.text.spans.iter().map(|s| s.text.as_str()).collect();
        assert!(text.contains("planning the edit"), "text missing: {text:?}");
        assert!(text.contains("tool_use="), "tools missing: {text:?}");
        assert!(text.contains("Edit"), "tool name missing: {text:?}");
    }

    // ── Board helpers ──────────────────────────────────────────────────────
    // make_test_app + siblings now live in `app::fixtures` (#1042); imported
    // above via `use super::fixtures::*;`.

    fn make_app_default() -> CoordApp {
        make_test_app(BoardData::default())
    }

    /// §3 (#782): numeric view-switch keys (1-7) were removed from the real
    /// key-dispatch path — views are discovered via the activity bar only.
    /// TuiDriver tests that need to land on a specific view before exercising
    /// something else must click its activity-bar icon instead of pressing a
    /// digit. Panics with the rendered screen when the icon glyph can't be
    /// found, so a layout/label regression fails loudly at the right call site.
    fn click_activity_icon<A: quadraui::AppLogic>(
        driver: &mut quadraui::tui::testing::TuiDriver<A>,
        icon: &str,
    ) {
        let (x, y) = driver.find(icon).unwrap_or_else(|| {
            panic!(
                "#782: activity-bar icon {icon:?} not found:\n{}",
                driver.screen()
            )
        });
        driver.click(x, y);
    }

    // ── issues_by_repo ──────────────────────────────────────────────────────

    #[test]
    fn issues_by_repo_empty_data() {
        let app = make_app_default();
        let grouped = app.issues_by_repo();
        assert!(grouped.is_empty());
    }

    #[test]
    fn issues_by_repo_groups_by_repo() {
        let assignments = vec![
            make_assignment_typed("running", 10, "repo-a", Some("work")),
            make_assignment_typed("done", 10, "repo-a", Some("review")),
            make_assignment_typed("done", 20, "repo-b", Some("work")),
        ];
        let app = make_app_with_assignments(assignments);
        let grouped = app.issues_by_repo();
        assert_eq!(grouped.len(), 2);
        // repo-a has running issue → sorted first.
        let (repo_a_name, repo_a_issues) = &grouped[0];
        assert_eq!(repo_a_name, "repo-a");
        assert_eq!(repo_a_issues.len(), 1); // issue #10
        assert_eq!(repo_a_issues[0].issue_number, 10);
        assert_eq!(repo_a_issues[0].assignments.len(), 2);
        assert_eq!(repo_a_issues[0].status_summary, "running");

        let (repo_b_name, repo_b_issues) = &grouped[1];
        assert_eq!(repo_b_name, "repo-b");
        assert_eq!(repo_b_issues.len(), 1); // issue #20
        assert_eq!(repo_b_issues[0].status_summary, "done");
    }

