    /// #1174: the interactive action must send `coord acceptance author
    /// <repo> <tracking_issue> --issue <N> --for-path <p> --interactive`
    /// into a REAL PTY — not just build the right string in the abstract.
    /// Spawns a genuine shell (mirrors the established pattern at
    /// `mouse_main_scroll_terminal_wheel_falls_back_to_local_scrollback`
    /// and the `coord terminal attach` fleet-terminal tests) and polls its
    /// echoed output for the exact command line, since the shell reflects
    /// typed keystrokes back before executing them.
    #[test]
    #[cfg(unix)]
    fn author_acceptance_tests_interactive_action_sends_command_with_for_path() {
        use std::time::{Duration, Instant};

        let tid = format!("{:?}", std::thread::current().id()).replace(['(', ')'], "");
        let tmp = std::env::temp_dir()
            .join(format!("coord-tui-test-acceptance-author-interactive-{}", tid));
        let _ = std::fs::remove_dir_all(&tmp);
        let contract_dir = tmp.join("tests").join("acceptance").join("ms-9");
        std::fs::create_dir_all(&contract_dir).unwrap();
        std::fs::write(contract_dir.join("contract.md"), "# Gate A contract\n").unwrap();

        let mut app = make_pipeline_app_for_acceptance_menu_test(0, tmp.to_str().unwrap());
        app.data
            .pipeline_acceptance_routes
            .insert("api".to_string(), vec!["coord/**".to_string()]);

        let target = ContextMenuTarget::PipelineRow {
            issue_number: Some(42),
            repo_name: Some("api".to_string()),
            lifecycle: PipelineRowLifecycle::New,
        };
        let handled = app.dispatch_context_menu_action("author-acceptance-tests-interactive", &target);
        assert!(handled, "author-acceptance-tests-interactive must be a recognised action");

        // #1223: the session now lands in the row's OWN per-issue
        // `detail_terminal_sessions` slot (keyed by `(repo_slug,
        // issue_num)`), not the global standalone `terminal_session` — the
        // correctness fix for the "clobbers a different issue's PTY" hazard.
        let sess = app
            .detail_terminal_sessions
            .get_mut(&("acme/api".to_string(), 42))
            .expect("a real terminal session must be spawned in the issue's own Terminal tab");

        let start = Instant::now();
        let mut text = String::new();
        while start.elapsed() < Duration::from_secs(5) {
            sess.poll();
            text = sess.full_text();
            if text.contains("acceptance author") {
                break;
            }
            std::thread::sleep(Duration::from_millis(20));
        }
        assert!(
            text.contains("acceptance author api 751 --issue 42 --for-path 'coord/**' --interactive"),
            "expected the full interactive author command in the PTY's echoed \
             output, got:\n{text}",
        );

        sess.write_input(b"exit\r");
        let _ = std::fs::remove_dir_all(&tmp);
    }

    /// #1223 gap 2 (the "sharpest" bug, a correctness hazard not just
    /// cosmetic): launching an interactive test-author session for issue A,
    /// then for a DIFFERENT issue B, must NOT reuse/clobber the same PTY.
    /// Before the fix, both launches wrote into the single global
    /// `terminal_session` field, so the operator could end up typing into
    /// (or reading output from) the wrong issue's session. This asserts
    /// both sessions land in their OWN slot in the per-issue
    /// `detail_terminal_sessions` map (keyed by `(repo_slug, issue_num)`),
    /// exactly like every other interactive flavour (Work/Review/Fix/Test/
    /// Merge), and that the deprecated global slot is never touched.
    #[test]
    #[cfg(unix)]
    fn author_acceptance_tests_interactive_sessions_for_two_issues_do_not_clobber_each_other() {
        let mut pipeline_repo_paths = std::collections::HashMap::new();
        pipeline_repo_paths.insert("api".to_string(), "/nonexistent/api-repo".to_string());
        let data = BoardData {
            pipeline_default_gates: vec!["review".to_string(), "merge".to_string()],
            pipeline_tracked_labels: vec!["coord".to_string()],
            pipeline_repos: vec![("api".to_string(), "acme/api".to_string())],
            pipeline_repo_paths,
            open_issues: vec![
                OpenIssue {
                    repo_name: "api".to_string(),
                    number: 42,
                    title: "Milestone member issue A".to_string(),
                    body: String::new(),
                    state: "open".to_string(),
                    labels: vec!["coord".to_string()],
                    milestone_number: Some(9),
                    milestone_title: Some("v1.0".to_string()),
                    body_truncated: false,
                    body_len: None,
                    // #1941: fields added to the generated wire DTO; not exercised by this test.
                    synced_at: None,
                },
                OpenIssue {
                    repo_name: "api".to_string(),
                    number: 43,
                    title: "Milestone member issue B".to_string(),
                    body: String::new(),
                    state: "open".to_string(),
                    labels: vec!["coord".to_string()],
                    milestone_number: Some(9),
                    milestone_title: Some("v1.0".to_string()),
                    body_truncated: false,
                    body_len: None,
                    // #1941: fields added to the generated wire DTO; not exercised by this test.
                    synced_at: None,
                },
            ],
            milestone_work_orders: vec![MilestoneWorkOrder {
                repo_name: "api".to_string(),
                tracking_issue: 751,
                milestone_title: "v1.0".to_string(),
                nodes: vec![
                    MilestoneWorkOrderNode {
                        issue_number: 42,
                        rank: 0,
                        ready: true,
                        next_up: true,
                        blocked_on: vec![],
                    },
                    MilestoneWorkOrderNode {
                        issue_number: 43,
                        rank: 1,
                        ready: true,
                        next_up: false,
                        blocked_on: vec![],
                    },
                ],
            }],
            ..BoardData::default()
        };
        let mut app = make_test_app(data);
        app.pipeline_issues = vec![
            PipelineIssue {
                number: 42,
                title: "Milestone member issue A".to_string(),
                body: String::new(),
                repo_slug: "acme/api".to_string(),
                coord_repo: Some("api".to_string()),
                matched_labels: vec!["coord".to_string()],
                all_labels: vec!["coord".to_string()],
                is_closed: false,
                body_truncated: false,
                body_len: None,
            },
            PipelineIssue {
                number: 43,
                title: "Milestone member issue B".to_string(),
                body: String::new(),
                repo_slug: "acme/api".to_string(),
                coord_repo: Some("api".to_string()),
                matched_labels: vec!["coord".to_string()],
                all_labels: vec!["coord".to_string()],
                is_closed: false,
                body_truncated: false,
                body_len: None,
            },
        ];
        app.rebuild_pipeline_sidebar(None);
        app.active_view = SidebarView::Pipeline;

        // Launch for issue A (#42).
        app.pipeline_sel = Some(0);
        assert!(app.launch_acceptance_author_interactive_for_selected_pipeline_row());
        assert!(
            app.detail_terminal_sessions.contains_key(&("acme/api".to_string(), 42)),
            "issue A's session must land in its OWN detail_terminal_sessions slot"
        );

        // Launch for issue B (#43) — must NOT disturb issue A's slot.
        app.pipeline_sel = Some(1);
        assert!(app.launch_acceptance_author_interactive_for_selected_pipeline_row());
        assert!(
            app.detail_terminal_sessions.contains_key(&("acme/api".to_string(), 43)),
            "issue B's session must land in its OWN detail_terminal_sessions slot"
        );
        assert!(
            app.detail_terminal_sessions.contains_key(&("acme/api".to_string(), 42)),
            "issue A's session must still be alive/present after issue B's launch — \
             the #1223 clobber hazard would have removed or overwritten it"
        );
        assert_eq!(
            app.detail_terminal_sessions.len(),
            2,
            "both issues must have DISTINCT sessions, not one shared/reused PTY"
        );
        assert!(
            app.terminal_session.is_none(),
            "the deprecated global standalone terminal_session must never be used \
             by the per-issue test-author launcher"
        );
    }

    /// #1174 TuiDriver black-box: open the context menu for a work-order-
    /// member Pipeline row via the Menu-key shortcut (`.`, the same
    /// keyboard path `context_menu_target_for_selection`'s doc describes —
    /// equivalent to a right-click on the selected row, without depending
    /// on the row's exact pixel geometry), `find` the "Author acceptance
    /// tests (interactive)" entry — never a hardcoded coordinate — click
    /// it, and assert the visible dispatch feedback renders. The exact
    /// command content (including `--for-path`) is asserted directly
    /// against the real PTY in the companion direct-app test above; the
    /// TuiDriver shell adapter doesn't expose the wrapped `CoordApp` for a
    /// typed field check (see the identical split used by
    /// `sessions_panel_stop_running_session_shows_feedback_toast`).
    #[test]
    fn tuidriver_author_acceptance_tests_interactive_menu_item_dispatches() {
        use quadraui::tui::testing::driver_with_shell;

        let tid = format!("{:?}", std::thread::current().id()).replace(['(', ')'], "");
        let tmp = std::env::temp_dir()
            .join(format!("coord-tui-test-tuidriver-acceptance-author-interactive-{}", tid));
        let _ = std::fs::remove_dir_all(&tmp);
        let contract_dir = tmp.join("tests").join("acceptance").join("ms-9");
        std::fs::create_dir_all(&contract_dir).unwrap();
        std::fs::write(contract_dir.join("contract.md"), "# Gate A contract\n").unwrap();

        let app = make_pipeline_app_for_acceptance_menu_test(0, tmp.to_str().unwrap());
        let mut driver = driver_with_shell(app, CoordApp::shell_config(), 140, 40);

        // Open the context menu for the currently-selected Pipeline row via
        // the keyboard shortcut (`.`) — equivalent to a right-click on the
        // row without needing to locate its exact pixel position first.
        driver.press(Key::Char('.'));
        assert!(
            driver.screen_contains("Start (interactive)"),
            "context menu must offer the Start (interactive) submenu for a \
             work-order member row with an existing contract.md:\n{}",
            driver.screen(),
        );

        // #1223: "Author acceptance tests (interactive)" now nests inside
        // "Start (interactive)" (gap 1 — discoverable in the same place as
        // Work/Review/Fix/Testing/Merge) instead of sitting as a flat
        // top-level item, so it isn't on screen until the pull-right
        // submenu is opened. Click the parent first (same half-cell nudge
        // `find` requires below), THEN find/click the nested action.
        let (px, py) = driver.find("Start (interactive)").unwrap_or_else(|| {
            panic!("could not find 'Start (interactive)' on screen:\n{}", driver.screen())
        });
        driver.click(px, py - 0.1);
        assert!(
            driver.screen_contains("Author acceptance tests (interactive)"),
            "Start (interactive) submenu must offer the interactive author \
             action for a work-order member row with an existing contract.md:\n{}",
            driver.screen(),
        );

        let (x, y) = driver
            .find("Author acceptance tests (interactive)")
            .unwrap_or_else(|| {
                panic!(
                    "#1174: could not find 'Author acceptance tests (interactive)' \
                     on screen:\n{}",
                    driver.screen()
                )
            });
        // `find` returns the CENTRE of the matched screen row (row + 0.5).
        // The `.`/right-click context-menu anchor is itself a half-integer
        // coordinate (`list_b.y + lh * 1.5`), so every item's hit-test rect
        // is `[row + 0.5, row + 1.5)` one item-height below where it visibly
        // renders — clicking at the exact row-centre `find` returns lands on
        // the *next* item's rect (its upper bound is exclusive). Nudge
        // upward by less than one row so the click still lands inside the
        // same visible cell but inside the item's own `[y, y+1)` hit
        // region — a systemic half-cell quirk of the fractional-anchor menu
        // layout, not a per-item pixel guess.
        driver.click(x, y - 0.1);

        let screen = driver.screen();
        assert!(
            screen.contains("Launched interactive test-author for"),
            "clicking the interactive author action must render visible \
             dispatch feedback:\n{}",
            screen,
        );

        let _ = std::fs::remove_dir_all(&tmp);
    }

