    // ── #193: stale downstream stages ─────────────────────────────────────────

    /// Helper: an assignment of `kind` (work/review/etc.) for issue 42 on `api`
    /// at the given dispatched_at, terminal status `done` unless overridden.
    fn _stage_assignment(id: &str, kind: &str, dispatched_at: f64, status: &str) -> Assignment {
        Assignment {
            id: id.to_string(),
            repo: "api".to_string(),
            issue_number: 42,
            issue_title: "Add cool thing".to_string(),
            machine: "m1".to_string(),
            status: status.to_string(),
            branch: None,
            model: None,
            dispatched_at: Some(dispatched_at),
            finished_at: Some(dispatched_at + 60.0),
            exit_code: if status == "failed" { Some(1) } else { Some(0) },
            assignment_type: Some(kind.to_string()),
            test_state: None,
            // #473: a *done* review in these stage-status fixtures means
            // "approved" (green) — the stage colour now keys on the verdict,
            // not just status=done, so the fixture must carry it.
            review_verdict: if kind == "review" && status == "done" {
                Some("approve".to_string())
            } else {
                None
            },
            review_of_assignment_id: None,
            cost_usd: None,
            smoke_tests: None,
            review_findings: None,
            review_findings_truncated: false,
            review_findings_len: None,
            test_plan: None,
            test_plan_branch_head: None,
            input_tokens: 0,
            output_tokens: 0,
            cache_creation_tokens: 0,
            cache_read_tokens: 0,
            is_interactive: false,
            failure_reason: None,
            review_iteration: 0,
            acceptance_state: None,
            acceptance_reason: None,
            acceptance_sha: None,
            acceptance_total: None,
            acceptance_passed: None,
            test_reason: None,
            review_state: None,
            pr_url: None,
            audit_goals_json: None,
            audit_bottom_line: None,
            audit_run_number: None,
            for_issue_number: None,
            driven_by: None,
            dispatched_by_assignment_id: None,
            // #1941: fields added to the generated wire DTO; not exercised by this test.
            repo_github: None,
            files_allowed: None,
            files_forbidden: None,
            smoke_test: None,
            smoke_test_reason: None,
            review_target: None,
            required_gates: None,
            plan: None,
            unreachable_count: None,
            review_posted_at: None,
            uat_state: None,
            uat_reason: None,
            claude_session_id: None,
            provider_name: None,
            review_head_sha: None,
            completion_summary: None,
            review_verdict_original: None,
            review_verdict_override_reason: None,
            review_patch_id: None,
            test_head_sha: None,
            test_patch_id: None,
            test_base_sha: None,
            review_scoped: None,
            review_scope_base_sha: None,
            test_toolchain: None,
            verdict_source: None,
            verdict_source_reason: None,
            stop_reason: None,
            num_turns: None,
        }
    }

    #[test]
    fn stage_status_stale_when_upstream_redispatched_after_done() {
        // The user's #214 case: Work was re-dispatched after a request-changes
        // review. Previously Review showed Done (green); should now show Stale.
        let mut app = make_pipeline_app();
        app.data
            .assignments
            .push(_stage_assignment("w1", "work", 100.0, "done"));
        app.data
            .assignments
            .push(_stage_assignment("r1", "review", 200.0, "done"));
        // Work re-dispatched (later than the review).
        app.data
            .assignments
            .push(_stage_assignment("w2", "work", 300.0, "done"));
        let issue = &app.pipeline_issues[0];
        assert_eq!(app.stage_status_for(issue, "work"), StageStatus::Done);
        assert_eq!(app.stage_status_for(issue, "review"), StageStatus::Stale);
    }

    #[test]
    fn stage_status_stale_when_upstream_redispatched_after_failed() {
        // A Failed review against an older Work is still Stale once Work re-runs:
        // the failure was about a diff that no longer exists.
        let mut app = make_pipeline_app();
        app.data
            .assignments
            .push(_stage_assignment("w1", "work", 100.0, "done"));
        app.data
            .assignments
            .push(_stage_assignment("r1", "review", 200.0, "failed"));
        app.data
            .assignments
            .push(_stage_assignment("w2", "work", 300.0, "done"));
        let issue = &app.pipeline_issues[0];
        assert_eq!(app.stage_status_for(issue, "review"), StageStatus::Stale);
    }

    #[test]
    fn stage_status_done_when_no_upstream_redispatch() {
        // Same setup minus the re-dispatch → Review stays Done (still trustworthy).
        let mut app = make_pipeline_app();
        app.data
            .assignments
            .push(_stage_assignment("w1", "work", 100.0, "done"));
        app.data
            .assignments
            .push(_stage_assignment("r1", "review", 200.0, "done"));
        let issue = &app.pipeline_issues[0];
        assert_eq!(app.stage_status_for(issue, "review"), StageStatus::Done);
    }

    #[test]
    fn stage_status_first_stage_never_stale() {
        // Work is the first dispatchable stage; there's no upstream to invalidate
        // it. Even with multiple dispatched_at values, latest wins as Done.
        let mut app = make_pipeline_app();
        app.data
            .assignments
            .push(_stage_assignment("w1", "work", 100.0, "done"));
        app.data
            .assignments
            .push(_stage_assignment("w2", "work", 300.0, "done"));
        let issue = &app.pipeline_issues[0];
        assert_eq!(app.stage_status_for(issue, "work"), StageStatus::Done);
    }

    #[test]
    fn stage_status_active_beats_staleness_when_upstream_running() {
        // If a stage has a Running assignment, that wins over any verdict —
        // staleness only matters for terminal states.
        let mut app = make_pipeline_app();
        app.data
            .assignments
            .push(_stage_assignment("w1", "work", 100.0, "done"));
        app.data
            .assignments
            .push(_stage_assignment("r1", "review", 200.0, "running"));
        app.data
            .assignments
            .push(_stage_assignment("w2", "work", 300.0, "done"));
        let issue = &app.pipeline_issues[0];
        assert_eq!(app.stage_status_for(issue, "review"), StageStatus::Active);
    }

    #[test]
    fn upstream_max_dispatched_at_returns_none_for_first_stage() {
        let mut app = make_pipeline_app();
        app.data
            .assignments
            .push(_stage_assignment("w1", "work", 100.0, "done"));
        let issue = &app.pipeline_issues[0];
        assert_eq!(app.upstream_max_dispatched_at(issue, "work"), None);
    }

    #[test]
    fn upstream_max_dispatched_at_aggregates_across_all_prior_stages() {
        // #1429: Pipeline is work → review → merge (merge restored as a
        // read-only observation stage). Querying upstream of "review" should
        // see the latest dispatch across ALL prior work assignments, and
        // upstream of "merge" should see the latest across work + review.
        let mut app = make_pipeline_app();
        app.data
            .assignments
            .push(_stage_assignment("w1", "work", 100.0, "done"));
        app.data
            .assignments
            .push(_stage_assignment("w2", "work", 250.0, "done"));
        let issue = &app.pipeline_issues[0];
        // Max across {work} prior to review = 250 (the second work dispatch).
        assert_eq!(app.upstream_max_dispatched_at(issue, "review"), Some(250.0));
        // "merge" is now a per-issue stage again — upstream lookup sees the
        // same {work} max since no review assignment exists in this fixture.
        assert_eq!(
            app.upstream_max_dispatched_at(issue, "merge"),
            Some(250.0),
            "#1429: merge is back in the stage list, upstream aggregates work+review"
        );
    }

    #[test]
    fn pipeline_widget_attaches_retry_to_stale_stage_when_prior_settled() {
        // Stale + upstream Done → [Retry] button so the user can re-run.
        let mut app = make_pipeline_app();
        app.data
            .assignments
            .push(_stage_assignment("w1", "work", 100.0, "done"));
        app.data
            .assignments
            .push(_stage_assignment("r1", "review", 200.0, "done"));
        app.data
            .assignments
            .push(_stage_assignment("w2", "work", 300.0, "done"));
        app.pipeline_sel = Some(0);
        let view = app.build_pipeline_widget().expect("widget");
        // Stage layout: work, review, merge.
        let review = &view.stages[1];
        assert_eq!(review.status, StageStatus::Stale);
        assert_eq!(review.action.as_deref(), Some("Retry"));
    }

    #[test]
    fn pipeline_widget_no_retry_on_stale_when_upstream_still_active() {
        // Stale + upstream Running → no button (waiting for upstream to settle
        // before user can act).
        let mut app = make_pipeline_app();
        app.data
            .assignments
            .push(_stage_assignment("w1", "work", 100.0, "done"));
        app.data
            .assignments
            .push(_stage_assignment("r1", "review", 200.0, "done"));
        app.data
            .assignments
            .push(_stage_assignment("w2", "work", 300.0, "running"));
        app.pipeline_sel = Some(0);
        let view = app.build_pipeline_widget().expect("widget");
        let review = &view.stages[1];
        assert_eq!(review.status, StageStatus::Stale);
        assert_eq!(review.action, None);
    }

    // ── #1084: oracle-loop pre-req pipeline (Gate A / Acceptance-Authoring) ──

    /// Build an app with a milestone's epic/tracking issue (#751, "epic"
    /// labelled) and two ordinary work-order member issues (#42, #43) —
    /// mirrors `make_pipeline_app_for_acceptance_menu_test` but also gives
    /// the tracking issue its own `PipelineIssue` row (needed to exercise
    /// the epic-row Gate A block) and a second member issue (needed to
    /// exercise the `for_issue_number` sibling-disambiguation fallback).
    fn make_pipeline_app_for_prereq_test() -> CoordApp {
        let data = BoardData {
            pipeline_default_gates: vec![
                "test".to_string(),
                "review".to_string(),
                "merge".to_string(),
            ],
            pipeline_tracked_labels: vec!["coord".to_string()],
            pipeline_repos: vec![("api".to_string(), "acme/api".to_string())],
            milestone_work_orders: vec![MilestoneWorkOrder {
                repo_name: "api".to_string(),
                tracking_issue: 751,
                milestone_title: "v1.0".to_string(),
                nodes: vec![
                    MilestoneWorkOrderNode {
                        issue_number: 42,
                        rank: 0,
                        ready: true,
                        next_up: true,
                        blocked_on: vec![],
                    },
                    MilestoneWorkOrderNode {
                        issue_number: 43,
                        rank: 1,
                        ready: true,
                        next_up: false,
                        blocked_on: vec![],
                    },
                ],
            }],
            ..BoardData::default()
        };
        let mut app = make_test_app(data);
        app.pipeline_issues = vec![
            PipelineIssue {
                number: 751,
                title: "Milestone v1.0 tracking issue".to_string(),
                body: String::new(),
                repo_slug: "acme/api".to_string(),
                coord_repo: Some("api".to_string()),
                matched_labels: vec!["coord".to_string()],
                all_labels: vec!["coord".to_string(), "epic".to_string(), "status:ready".to_string()],
                is_closed: false,
                body_truncated: false,
                body_len: None,
            },
            PipelineIssue {
                number: 42,
                title: "Milestone member issue".to_string(),
                body: String::new(),
                repo_slug: "acme/api".to_string(),
                coord_repo: Some("api".to_string()),
                matched_labels: vec!["coord".to_string()],
                all_labels: vec!["coord".to_string(), "status:ready".to_string()],
                is_closed: false,
                body_truncated: false,
                body_len: None,
            },
            PipelineIssue {
                number: 43,
                title: "Sibling member issue".to_string(),
                body: String::new(),
                repo_slug: "acme/api".to_string(),
                coord_repo: Some("api".to_string()),
                matched_labels: vec!["coord".to_string()],
                all_labels: vec!["coord".to_string(), "status:ready".to_string()],
                is_closed: false,
                body_truncated: false,
                body_len: None,
            },
        ];
        app.rebuild_pipeline_sidebar(None);
        app
    }

    /// #2397: build a `merge_plan` entry keyed by an explicit branch — the
    /// #777 `planned_entry` factory further below auto-derives its branch
    /// from `issue_number`, which doesn't fit the prereq track's tests
    /// (whose branch is the mock-author/test-author assignment's own
    /// branch, independent of the tracking issue number).
    fn planned_merge_entry_for_test(
        assignment_id: &str,
        repo_github: &str,
        branch: &str,
        issue_number: u64,
        reason: &str,
        auto_drain: bool,
    ) -> PlannedMergeEntry {
        PlannedMergeEntry {
            assignment_id: assignment_id.to_string(),
            repo_name: "api".to_string(),
            repo_github: repo_github.to_string(),
            branch: branch.to_string(),
            target_branch: "main".to_string(),
            issue_number,
            issue_title: "t".to_string(),
            rank: 1,
            size: None,
            status: "BLOCKED".to_string(),
            reason: Some(reason.to_string()),
            enqueued_at: None,
            last_attempt: None,
            milestone: None,
            pr_number: Some(9),
            ci_summary: None,
            auto_drain,
        }
    }

