    #[test]
    fn status_bar_surfaces_live_interactive_sessions() {
        // #628: detached interactive sessions create no board `running` row, so
        // they were invisible and piled up. They must show as a persistent
        // status-bar badge whenever any are discovered.
        let mut app = make_test_app(BoardData::default());
        let left_text = |a: &CoordApp| {
            a.status_bar()
                .left_segments
                .iter()
                .map(|s| s.text.clone())
                .collect::<Vec<_>>()
                .join(" ")
        };

        // No sessions → no badge.
        assert!(
            !left_text(&app).contains("live session"),
            "no badge expected with zero sessions",
        );

        // Two live sessions → a badge with the count, regardless of board state.
        app.live_tmux_sessions = vec![
            LiveTmuxSession {
                assignment_id: "a".into(),
                issue_number: Some(1),
                repo_name: None,
                issue_title: None,
                machine: None,
                pane_dead: false,
            pending_sweep_count: 0,
            attached: false,
            },
            LiveTmuxSession {
                assignment_id: "b".into(),
                issue_number: Some(2),
                repo_name: None,
                issue_title: None,
                machine: None,
                pane_dead: false,
            pending_sweep_count: 0,
            attached: false,
            },
        ];
        assert!(
            left_text(&app).contains("2 live sessions"),
            "expected a '2 live sessions' badge, got: {}",
            left_text(&app),
        );

        // Singular form for one session.
        app.live_tmux_sessions.truncate(1);
        assert!(
            left_text(&app).contains("1 live session ")
                && !left_text(&app).contains("1 live sessions"),
            "expected singular '1 live session', got: {}",
            left_text(&app),
        );
    }

    #[test]
    fn status_bar_hints_advertise_plan_right_click_menu() {
        // #977 review: pressing `c` in the Plans panel silently opened the
        // capture prompt with no visible hint anywhere the operator could
        // find it, so the status bar grew a bare `c=capture plan` hint.
        // #1123 (contract §4f) supersedes that: every Plans row is now
        // right-clickable and `c` survives only as an accelerator *inside*
        // the labelled "New plan > Quick capture" menu item (contract
        // §4e), so the cryptic bare-letter hint is replaced with
        // `right-click=menu` (backed by `?=help`, whose cheatsheet still
        // lists every binding — #1124).
        let mut app = make_test_app(BoardData::default());
        app.active_view = SidebarView::Plans;
        let right_text = app
            .status_bar()
            .right_segments
            .iter()
            .map(|s| s.text.clone())
            .collect::<Vec<_>>()
            .join(" ");
        assert!(
            right_text.contains("right-click=menu"),
            "expected the Plans panel hint to advertise `right-click=menu`, got: {}",
            right_text,
        );
        assert!(
            right_text.contains("?=help"),
            "expected the Plans panel hint to advertise `?=help`, got: {}",
            right_text,
        );
    }

    #[test]
    fn live_session_count_for_machine_joins_sessions_to_assignments() {
        // #628 pt.2: the Machines tab counts live interactive sessions by
        // joining each session to its assignment's machine — independent of the
        // assignment's status, so a session whose work already merged (board row
        // → Done) is still counted while it stays live.
        let mut app = make_test_app(BoardData::default());
        let mut a1 = _stage_assignment("s1", "work", 100.0, "done"); // merged → Done
        a1.machine = "elitebook".to_string();
        let mut a2 = _stage_assignment("s2", "review", 100.0, "running");
        a2.machine = "dellserver".to_string();
        let mut a3 = _stage_assignment("s3", "fix", 100.0, "done");
        a3.machine = "dellserver".to_string();
        app.data.assignments = vec![a1, a2, a3];

        app.live_tmux_sessions = vec![
            LiveTmuxSession {
                assignment_id: "s1".into(),
                issue_number: None,
                repo_name: None,
                issue_title: None,
                machine: None,
                pane_dead: false,
            pending_sweep_count: 0,
            attached: false,
            },
            LiveTmuxSession {
                assignment_id: "s2".into(),
                issue_number: None,
                repo_name: None,
                issue_title: None,
                machine: None,
                pane_dead: false,
            pending_sweep_count: 0,
            attached: false,
            },
            LiveTmuxSession {
                assignment_id: "s3".into(),
                issue_number: None,
                repo_name: None,
                issue_title: None,
                machine: None,
                pane_dead: false,
            pending_sweep_count: 0,
            attached: false,
            },
            // A session with no matching assignment can't be attributed → ignored.
            LiveTmuxSession {
                assignment_id: "ghost".into(),
                issue_number: None,
                repo_name: None,
                issue_title: None,
                machine: None,
                pane_dead: false,
            pending_sweep_count: 0,
            attached: false,
            },
        ];

        assert_eq!(app.live_session_count_for_machine("elitebook"), 1);
        assert_eq!(app.live_session_count_for_machine("dellserver"), 2);
        assert_eq!(app.live_session_count_for_machine("precision"), 0);
    }

    // ── #1033: Sessions panel actions (attach / kill / stop) ───────────────
    // Retires the #628 fleet-wide live-sessions overlay in favor of these —
    // same verbs (reattach / kill / stop), now wired to the #1032 Sessions
    // tree's selected leaf instead of a modal overlay's flat list.

    /// TuiDriver black-box: `L` from any non-modal, non-PTY view switches the
    /// active view to the Sessions panel (retiring the old open/close toggle
    /// — see the events.rs #1033 comment). Asserted via the Sessions panel's
    /// unique empty-detail placeholder text, since `driver_with_shell`
    /// exposes no direct field access back into `CoordApp`.
    #[test]
    fn l_key_switches_to_sessions_panel() {
        use quadraui::tui::testing::driver_with_shell;

        let app = make_test_app(BoardData::default());
        let mut driver = driver_with_shell(app, CoordApp::shell_config(), 120, 40);
        // Board is the default view — its placeholder must not be showing yet.
        assert!(
            !driver.screen().contains("Select a session to see its details"),
            "must start on a view other than Sessions:\n{}",
            driver.screen(),
        );

        driver.press(Key::Char('L'));

        let screen = driver.screen();
        assert!(
            screen.contains("Select a session to see its details"),
            "L must switch the active view to Sessions:\n{screen}",
        );
    }

    /// TuiDriver black-box: seed one live session, select its tree leaf,
    /// press `K`, confirm the dialog, and assert the entry drops from the
    /// rendered tree — mirrors `kill_terminal_confirm_removes_node_from_tree`
    /// (#956) for the Sessions panel.
    #[test]
    fn sessions_panel_kill_confirm_removes_node_from_tree() {
        use quadraui::tui::testing::driver_with_shell;

        let mut app = make_test_app(BoardData {
            machines: vec![mk_machine("precision", "precision.tail", true, &[])],
            ..BoardData::default()
        });
        app.live_tmux_sessions = vec![LiveTmuxSession {
            assignment_id: "test-aid".into(),
            issue_number: Some(99),
            repo_name: Some("api".into()),
            issue_title: None,
            machine: Some("precision".into()),
            pane_dead: false,
            pending_sweep_count: 0,
            attached: false,
        }];

        let mut driver = driver_with_shell(app, CoordApp::shell_config(), 120, 40);
        click_activity_icon(&mut driver, "◉");

        let (x, y) = driver.find("#99").unwrap_or_else(|| {
            panic!("'#99' session row must be findable:\n{}", driver.screen())
        });
        driver.click(x, y);

        driver.press(Key::Char('K'));
        let screen = driver.screen();
        assert!(
            screen.contains("Kill Session") || screen.contains("Kill session"),
            "K on a selected session row must open the kill-confirm dialog:\n{screen}",
        );

        driver.press(Key::Char('y'));

        let screen = driver.screen();
        assert!(
            !screen.contains("#99"),
            "killed session must no longer render in the tree:\n{screen}",
        );
    }

