    #[test]
    fn selected_issue_live_session_id_matches_repo_and_issue() {
        // #486 Leg 4 UX: the reattach short-circuit must match the live session
        // PRECISELY by repo + issue number — a same-number session in a DIFFERENT
        // repo (vimcode #514 vs claude-coordinator #514) must NOT match (#480).
        let mut app = make_app_default();
        app.active_view = SidebarView::Pipeline; // Pipeline selection must win
        app.pipeline_issues.push(PipelineIssue {
            number: 514,
            title: "x".to_string(),
            body: String::new(),
            repo_slug: "acme/vimcode".to_string(),
            coord_repo: Some("vimcode".to_string()),
            matched_labels: vec!["coord".to_string()],
            all_labels: vec!["coord".to_string()],
            is_closed: false,
            body_truncated: false,
            body_len: None,
        });
        app.pipeline_sel = Some(0);

        // No live session → None.
        assert!(app.selected_issue_live_session_id().is_none());

        // A live session whose work assignment is still RUNNING → reattachable.
        app.data
            .assignments
            .push(make_assignment_typed("running", 514, "vimcode", Some("work")));
        app.live_tmux_sessions = vec![LiveTmuxSession {
            assignment_id: "id-514-running".to_string(),
            issue_number: Some(514),
            repo_name: Some("vimcode".to_string()),
            issue_title: None,
            machine: None,
            pane_dead: false,
            pending_sweep_count: 0,
            attached: false,
        }];
        assert_eq!(
            app.selected_issue_live_session_id().as_deref(),
            Some("id-514-running")
        );

        // Same number, WRONG repo → must not match (#480 cross-repo guard).
        app.live_tmux_sessions = vec![LiveTmuxSession {
            assignment_id: "id-514-running".to_string(),
            issue_number: Some(514),
            repo_name: Some("claude-coordinator".to_string()),
            issue_title: None,
            machine: None,
            pane_dead: false,
            pending_sweep_count: 0,
            attached: false,
        }];
        assert!(
            app.selected_issue_live_session_id().is_none(),
            "cross-repo same-number session must not match"
        );
    }

    #[test]
    fn selected_issue_live_session_id_prefers_running_over_lingering_done() {
        // #601 follow-up: several discovered sessions for one issue — a lingering
        // DONE smoke session listed BEFORE the live RUNNING review (local sessions
        // are discovered before remote ones). The reattach short-circuit must pick
        // the RUNNING one, not bail because the first match is finalized — that's
        // what left the menu offering "Reattach" while the launch fell through to
        // the "Select machine" picker.
        let mut app = make_app_default();
        app.active_view = SidebarView::Pipeline; // Pipeline selection must win
        app.pipeline_issues.push(PipelineIssue {
            number: 494,
            title: "x".to_string(),
            body: String::new(),
            repo_slug: "acme/vimcode".to_string(),
            coord_repo: Some("vimcode".to_string()),
            matched_labels: vec!["coord".to_string()],
            all_labels: vec!["coord".to_string()],
            is_closed: false,
            body_truncated: false,
            body_len: None,
        });
        app.pipeline_sel = Some(0);
        app.data
            .assignments
            .push(make_assignment_typed("done", 494, "vimcode", Some("smoke")));
        app.data
            .assignments
            .push(make_assignment_typed("running", 494, "vimcode", Some("review")));
        // DONE session first (local), RUNNING session second (remote).
        app.live_tmux_sessions = vec![
            LiveTmuxSession {
                assignment_id: "id-494-done".to_string(),
                issue_number: Some(494),
                repo_name: Some("vimcode".to_string()),
                issue_title: None,
                machine: None,
                pane_dead: false,
            pending_sweep_count: 0,
            attached: false,
            },
            LiveTmuxSession {
                assignment_id: "id-494-running".to_string(),
                issue_number: Some(494),
                repo_name: Some("vimcode".to_string()),
                issue_title: None,
                machine: None,
                pane_dead: false,
            pending_sweep_count: 0,
            attached: false,
            },
        ];
        assert_eq!(
            app.selected_issue_live_session_id().as_deref(),
            Some("id-494-running"),
            "must reattach to the RUNNING session, not bail on the first (done) match"
        );
    }

    #[test]
    fn finalized_session_running_gate_still_blocks_running_resolver() {
        // #514: `selected_issue_live_session_id` must still return None when
        // the board assignment is finalized (done) — the running-only resolver
        // is preserved so the type-gated Start launchers never reattach into a
        // stale/dead session.
        //
        // #727: however the menu now DOES offer "Reattach to live session" for
        // this zombie case (done assignment but live_tmux_sessions entry present),
        // because the In-progress:Live classifier already shows the row as Live —
        // the menu and the classifier must not disagree.  The reattach action
        // itself resolves the aid via the wider `selected_issue_any_session_id`,
        // and `coord reattach <aid>` fails gracefully if the session turns out to
        // be stale ("session not alive").
        let mut app = make_app_default();
        app.pipeline_issues.push(PipelineIssue {
            number: 514,
            title: "x".to_string(),
            body: String::new(),
            repo_slug: "acme/vimcode".to_string(),
            coord_repo: Some("vimcode".to_string()),
            matched_labels: vec!["coord".to_string()],
            all_labels: vec!["coord".to_string()],
            is_closed: false,
            body_truncated: false,
            body_len: None,
        });
        app.pipeline_sel = Some(0);
        app.active_view = SidebarView::Pipeline;
        // Work DONE (finalized) + a live-session entry pointing at it (zombie).
        app.data
            .assignments
            .push(make_assignment_typed("done", 514, "vimcode", Some("work")));
        app.live_tmux_sessions = vec![LiveTmuxSession {
            assignment_id: "id-514-done".to_string(),
            issue_number: Some(514),
            repo_name: Some("vimcode".to_string()),
            issue_title: None,
            machine: None,
            pane_dead: false,
            pending_sweep_count: 0,
            attached: false,
        }];

        // Running-only resolver returns None (assignment not running).
        assert!(
            app.selected_issue_live_session_id().is_none(),
            "running-only resolver must still return None for a finalized session"
        );
        // Wider resolver finds the zombie aid.
        assert_eq!(
            app.selected_issue_any_session_id().as_deref(),
            Some("id-514-done"),
            "#727: selected_issue_any_session_id must resolve a zombie session"
        );
        // #727: the menu offers BOTH Reattach (zombie) AND Start launchers.
        let items =
            app.context_menu_items_for_pipeline_row(Some(514), &PipelineRowLifecycle::InProgress, None);
        assert!(
            items.iter().any(|i| i.label == "Reattach to live session"),
            "#727: zombie session must offer Reattach in the right-click menu"
        );
        assert!(
            items.iter().any(|i| i.label == "Start (interactive)"),
            "#727: zombie menu must still include Start (interactive) — not hard-locked"
        );
        assert!(
            items.iter().any(|i| i.label == "Start (automated)"),
            "#727: zombie menu must still include Start (automated) — not hard-locked"
        );
    }

