    #[test]
    fn tuidriver_pipeline_new_milestones_collapsed_by_default() {
        // #857: on a freshly built app (no prior toggles), the Pipeline New
        // section must render its milestone headers collapsed — the issue
        // rows beneath them must not be on screen — while the milestone
        // headers themselves (with counts) remain visible.
        use quadraui::tui::testing::driver_with_shell;

        let mut app = make_pipeline_milestone_app();
        app.active_view = SidebarView::Pipeline;

        let driver = driver_with_shell(app, CoordApp::shell_config(), 120, 40);
        let screen = driver.screen();

        assert!(
            driver.screen_contains("v1.0"),
            "milestone header 'v1.0' must be visible (collapsed, not hidden):\n{screen}"
        );
        assert!(
            driver.screen_contains("v2.0"),
            "milestone header 'v2.0' must be visible (collapsed, not hidden):\n{screen}"
        );
        assert!(
            driver.screen_contains("No milestone"),
            "'No milestone' header must be visible (collapsed, not hidden):\n{screen}"
        );
        assert!(
            !driver.screen_contains("Milestone v1 issue"),
            "issue row under a collapsed milestone must NOT be on screen:\n{screen}"
        );
        assert!(
            !driver.screen_contains("Milestone v2 issue"),
            "issue row under a collapsed milestone must NOT be on screen:\n{screen}"
        );
        assert!(
            !driver.screen_contains("No milestone issue"),
            "issue row under a collapsed milestone must NOT be on screen:\n{screen}"
        );
    }

    #[test]
    fn tuidriver_pipeline_new_milestone_chevron_click_expands_and_persists() {
        // #857: clicking a collapsed milestone header's chevron must expand
        // it and reveal its issues (full event round-trip through
        // `handle` → `Reaction::Redraw` → `render_frame`), and the toggle
        // must persist across the next sidebar rebuild.
        //
        // Pipeline milestone headers only toggle on a *chevron* hit — a
        // plain click on the row body emits `RowSelected`, which the
        // Pipeline handler in events.rs uses only to blur the search filter
        // (see `pipeline_milestones_for_issues` callers in events.rs). The
        // chevron is painted 2 cells before the label
        // (`indent * 2 cells + 1-char chevron + 1 space`), so clicking 2
        // columns to the left of the text found by `find()` lands on it —
        // this mirrors quadraui's own chevron-vs-body hit-test contract
        // (`quadraui::compose::sidebar_system` `TreeViewHit::Chevron`).
        use quadraui::tui::testing::driver_with_shell;

        let mut app = make_pipeline_milestone_app();
        app.active_view = SidebarView::Pipeline;

        let mut driver = driver_with_shell(app, CoordApp::shell_config(), 120, 40);
        let screen_before = driver.screen();
        assert!(
            !driver.screen_contains("#10"),
            "sanity: must start collapsed:\n{screen_before}"
        );

        let (label_x, label_y) = driver
            .find("v1.0")
            .unwrap_or_else(|| panic!("'v1.0' milestone header not found:\n{screen_before}"));
        let chevron_x = (label_x - 2.0).max(0.0);
        driver.click(chevron_x, label_y);

        // Assert on the issue number rather than the full title text — the
        // narrow detail-pane column truncates long titles (`trunc(..., 20)`
        // in pipeline.rs), so "Milestone v1 issue" isn't reliably intact on
        // screen even once the row is visible.
        let screen_after = driver.screen();
        assert!(
            driver.screen_contains("#10"),
            "clicking the milestone chevron must expand it and reveal its issue:\n{screen_after}"
        );
    }

    #[test]
    fn pipeline_selection_restores_through_milestone_groups() {
        // Selection restore must work through the 3-level (repo → milestone → issue)
        // tree: after swapping pipeline_issues, the previously selected issue
        // (identified by repo_slug + number) must still be focused.
        let mut app = make_pipeline_milestone_app();
        // Default selection is issue at index 0 (#10, milestone v1.0).
        assert_eq!(app.pipeline_sel, Some(0));
        assert_eq!(app.pipeline_issues[0].number, 10);

        // Capture BEFORE the swap.
        let prev_sel = app.capture_pipeline_selection_id();
        assert_eq!(prev_sel, Some(("acme/api".to_string(), 10)));

        // Prepend a new issue (pushing #10 from index 0 to index 1).
        let mut new_issues = vec![PipelineIssue {
            number: 5,
            title: "New prepended".to_string(),
            body: String::new(),
            repo_slug: "acme/api".to_string(),
            coord_repo: Some("api".to_string()),
            matched_labels: vec!["coord".to_string()],
            all_labels: vec!["coord".to_string()],
            is_closed: false,
            body_truncated: false,
            body_len: None,
        }];
        // Also add the open_issue entry for #5 (no milestone) so lookup works.
        app.data.open_issues.push(OpenIssue {
            repo_name: "api".to_string(),
            number: 5,
            title: "New prepended".to_string(),
            body: String::new(),
            labels: vec!["coord".to_string()],
            state: "open".to_string(),
            milestone_number: None,
            milestone_title: None,
            body_truncated: false,
            body_len: None,
            // #1941: fields added to the generated wire DTO; not exercised by this test.
            synced_at: None,
        });
        new_issues.extend(app.pipeline_issues.clone());
        app.pipeline_issues = new_issues;
        app.rebuild_pipeline_sidebar(prev_sel);

        // Selection must still be on #10 (now at a different index).
        let selected_number = app
            .pipeline_sel
            .and_then(|i| app.pipeline_issues.get(i))
            .map(|i| i.number);
        assert_eq!(
            selected_number,
            Some(10),
            "selection must follow #10 through milestone groups even after index shift",
        );
    }

    // ── #349: Test-plan helpers ───────────────────────────────────────────────

    /// Parsing a well-formed test_plan JSON blob returns the expected steps.
    #[test]
    fn parse_test_plan_steps_happy_path() {
        let raw = r#"{"steps":[
            {"kind":"run","cmd":"cargo test"},
            {"kind":"pull","cmd":"coord pull-artifact abc","label":"binary"},
            {"kind":"verify","check":"no panic in stderr"}
        ],"blockers":[]}"#;
        let steps = parse_test_plan_steps(raw).expect("should parse");
        assert_eq!(steps.len(), 3);
        assert_eq!(steps[0].kind, "run");
        assert_eq!(steps[0].cmd.as_deref(), Some("cargo test"));
        assert_eq!(steps[1].kind, "pull");
        assert_eq!(steps[1].label.as_deref(), Some("binary"));
        assert_eq!(steps[2].kind, "verify");
        assert_eq!(steps[2].check.as_deref(), Some("no panic in stderr"));
        assert!(steps[2].cmd.is_none());
    }

    /// Malformed JSON returns None gracefully (no panic).
    #[test]
    fn parse_test_plan_steps_malformed_returns_none() {
        assert!(parse_test_plan_steps("not json at all").is_none());
        assert!(parse_test_plan_steps("{}").is_none()); // missing "steps"
        assert!(parse_test_plan_steps("null").is_none());
    }

    /// Empty steps array returns Some(vec![]).
    #[test]
    fn parse_test_plan_steps_empty_array() {
        let raw = r#"{"steps":[],"blockers":["need hardware"]}"#;
        let steps = parse_test_plan_steps(raw).expect("should parse");
        assert!(steps.is_empty());
    }

