    #[test]
    fn build_interactive_launch_cmd_quotes_repo_with_spaces() {
        // Defensive: a repo name that contains whitespace must be quoted
        // so the local shell sees it as a single argument.  Single
        // quotes also block shell-metachar interpretation.
        let cmd =
            build_interactive_launch_cmd(None, "m", "my repo", 42, InteractiveLaunchMode::Work, None);
        assert!(
            cmd.contains("'my repo' 42"),
            "repo with spaces must be single-quoted; got: {cmd:?}",
        );
    }

    #[test]
    fn build_interactive_launch_cmd_quotes_repo_with_shell_metachars() {
        // `$` / `;` / `&` / backticks must not be passed unquoted — they
        // would otherwise be interpreted by the local shell.
        let cmd = build_interactive_launch_cmd(
            None,
            "m",
            "evil;rm -rf /",
            1,
            InteractiveLaunchMode::Work,
            None,
        );
        assert!(
            cmd.contains("'evil;rm -rf /' 1"),
            "shell metachars must be quoted away; got: {cmd:?}",
        );
        // An embedded single quote is escaped via the standard '\'' trick.
        let cmd2 = build_interactive_launch_cmd(None, "m", "a'b", 2, InteractiveLaunchMode::Work, None);
        assert!(
            cmd2.contains(r"'a'\''b' 2"),
            "embedded single quotes must be escaped; got: {cmd2:?}",
        );
    }

    // ── #1174: `coord acceptance author --interactive` launch line ────────

    #[test]
    fn build_acceptance_author_interactive_launch_cmd_basic() {
        // No config path, no --for-path: `REPO TRACKING_ISSUE --issue N
        // --interactive`, single line, auto-submitted.
        let cmd = build_acceptance_author_interactive_launch_cmd(None, "api", 751, 42, None);
        assert_eq!(cmd, "coord acceptance author api 751 --issue 42 --interactive\r");
    }

    #[test]
    fn build_acceptance_author_interactive_launch_cmd_injects_config_and_for_path() {
        // #1151: --for-path must thread through the interactive flavour
        // exactly like the headless dispatch, or a routed repo's CLI-side
        // gate rejects the launch silently once it's typed into the PTY.
        //
        // #1174 fix-iteration-1: `--config` is registered on the leaf
        // `acceptance author` command (coord/commands/acceptance.py), not
        // on the root `coord` click.group, so it MUST come after the
        // subcommand tokens — putting it before them (as coord's root
        // group parses options) produced "Error: No such option
        // '--config'" in the live smoke test.
        let cmd = build_acceptance_author_interactive_launch_cmd(
            Some("/home/john/src/claude-coordinator/coordinator.yml"),
            "api",
            751,
            42,
            Some("coord/**"),
        );
        assert_eq!(
            cmd,
            "coord acceptance author --config /home/john/src/claude-coordinator/coordinator.yml \
             api 751 --issue 42 --for-path 'coord/**' --interactive\r",
        );
    }

    #[test]
    fn build_acceptance_author_interactive_launch_cmd_config_comes_after_subcommand() {
        // Regression for #1174: assert the token ordering directly (not
        // just full-string equality above) so a future refactor that
        // reintroduces `--config` before `acceptance author` fails loudly.
        let cmd = build_acceptance_author_interactive_launch_cmd(
            Some("/tmp/coordinator.yml"),
            "api",
            751,
            42,
            None,
        );
        let subcommand_pos = cmd.find("acceptance author").expect("subcommand present");
        let config_pos = cmd.find("--config").expect("--config present");
        assert!(
            config_pos > subcommand_pos,
            "--config must come after 'acceptance author', not before \
             (Click's root group rejects it there); got: {cmd:?}",
        );
    }

    #[test]
    fn build_acceptance_author_interactive_launch_cmd_ends_with_single_cr() {
        let cmd = build_acceptance_author_interactive_launch_cmd(None, "api", 751, 42, None);
        assert!(cmd.ends_with('\r'), "must end with \\r; got: {cmd:?}");
        assert_eq!(cmd.matches('\r').count(), 1, "exactly one \\r; got: {cmd:?}");
        assert!(!cmd.contains('\n'), "must not embed newlines: {cmd:?}");
    }

    #[test]
    fn build_acceptance_author_interactive_launch_cmd_quotes_repo_with_spaces() {
        let cmd = build_acceptance_author_interactive_launch_cmd(None, "my repo", 751, 42, None);
        assert!(
            cmd.contains("'my repo' 751"),
            "repo with spaces must be single-quoted; got: {cmd:?}",
        );
    }

    #[test]
    fn build_acceptance_author_interactive_launch_cmd_quotes_for_path_glob() {
        // A glob like `coord/**` has no shell metachars that need quoting,
        // but a route with a space must still come through single-quoted.
        let cmd = build_acceptance_author_interactive_launch_cmd(
            None,
            "api",
            751,
            42,
            Some("weird path/**"),
        );
        assert!(
            cmd.contains("--for-path 'weird path/**' --interactive"),
            "for_path with spaces must be single-quoted; got: {cmd:?}",
        );
    }

    #[test]
    fn shell_quote_arg_passes_safe_strings_through() {
        // Common repo names (alphanumeric + `-`/`_`/`.`/`/`) are passed
        // through verbatim — no unnecessary quoting noise.
        assert_eq!(shell_quote_arg("claude-coordinator"), "claude-coordinator");
        assert_eq!(shell_quote_arg("coord_tui"), "coord_tui");
        assert_eq!(shell_quote_arg("v1.2.3"), "v1.2.3");
        assert_eq!(shell_quote_arg("a/b"), "a/b");
    }

    #[test]
    fn shell_quote_arg_quotes_empty_string() {
        // Empty argument must round-trip as `''` so the positional
        // argument still gets passed (and `coord` reports a useful error
        // rather than silently dropping it).
        assert_eq!(shell_quote_arg(""), "''");
    }

    // ── #467 / #480: selected_issue_repo_and_key (Bug A — repo from selected row) ──

