    /// #795 TuiDriver black-box: Pipeline milestone cards show work-order badges.
    ///
    /// Seeds a `BoardData` with four issues under milestone "v1.0" and a
    /// `MilestoneWorkOrder` with rank/ready/next_up/blocked_on data.  Drives
    /// the full `event → handle → render` path through `TuiDriver` and
    /// asserts:
    /// - ready/next-up issues display the "↑W{rank}" badge text
    /// - blocked issues display the "⊘W{rank}←#{blocker}" badge text
    /// - a ready-but-claimed issue (deps met, but already claimed by an
    ///   active assignment elsewhere — #795 review) displays the plain
    ///   dim "W{rank}" badge, with NEITHER the next-up arrow NOR a dangling
    ///   blocked-arrow-with-no-blocker
    ///
    /// Uses `find()` to locate targets, never hardcoded coordinates.
    #[test]
    fn tuidriver_pipeline_milestone_cards_show_work_order_badges() {
        use quadraui::tui::testing::driver_with_shell;

        let data = make_work_order_board_data();
        let mut app = make_test_app(data);

        // Populate pipeline_issues for our four work-order issues.
        app.pipeline_issues = vec![
            PipelineIssue {
                number: 101,
                title: "Issue A1".to_string(),
                body: String::new(),
                repo_slug: "acme/api".to_string(),
                coord_repo: Some("api".to_string()),
                matched_labels: vec!["coord".to_string()],
                all_labels: vec!["coord".to_string()],
                is_closed: false,
                body_truncated: false,
                body_len: None,
            },
            PipelineIssue {
                number: 102,
                title: "Issue A2".to_string(),
                body: String::new(),
                repo_slug: "acme/api".to_string(),
                coord_repo: Some("api".to_string()),
                matched_labels: vec!["coord".to_string()],
                all_labels: vec!["coord".to_string()],
                is_closed: false,
                body_truncated: false,
                body_len: None,
            },
            PipelineIssue {
                number: 103,
                title: "Issue B1".to_string(),
                body: String::new(),
                repo_slug: "acme/api".to_string(),
                coord_repo: Some("api".to_string()),
                matched_labels: vec!["coord".to_string()],
                all_labels: vec!["coord".to_string()],
                is_closed: false,
                body_truncated: false,
                body_len: None,
            },
            PipelineIssue {
                number: 104,
                title: "Issue C1".to_string(),
                body: String::new(),
                repo_slug: "acme/api".to_string(),
                coord_repo: Some("api".to_string()),
                matched_labels: vec!["coord".to_string()],
                all_labels: vec!["coord".to_string()],
                is_closed: false,
                body_truncated: false,
                body_len: None,
            },
        ];

        // Pre-expand the milestone section so issue cards are visible without
        // a click.  Key format: (lifecycle, repo_key, milestone_key) where
        // milestone_key is the number as a string (see `pipeline_milestones_for_issues`).
        app.pipeline_milestone_expanded.insert(
            ("new".to_string(), "api".to_string(), "1".to_string()),
            true,
        );
        // Also ensure the repo section is expanded (defaults to true but be explicit).
        app.pipeline_lifecycle_expanded.insert(
            ("new".to_string(), "api".to_string()),
            true,
        );

        app.active_view = SidebarView::Pipeline;
        app.rebuild_board_sidebar();
        app.rebuild_pipeline_sidebar(None);

        let driver = driver_with_shell(app, CoordApp::shell_config(), 140, 50);
        let screen = driver.screen();

        // #101 is ready + next_up, rank 0 → span text "↑W1" (1-indexed)
        assert!(
            screen.contains("↑W1"),
            "#101 must show '↑W1' (ready + next_up, rank 0→1):\n{screen}",
        );
        // #102 is ready + next_up, rank 1 → "↑W2"
        assert!(
            screen.contains("↑W2"),
            "#102 must show '↑W2' (ready + next_up, rank 1→2):\n{screen}",
        );
        // #103 is blocked (rank 2, first blocker #101) → "⊘W3←#101"
        assert!(
            screen.contains("⊘W3←#101"),
            "#103 must show '⊘W3←#101' (blocked rank 2→3, first dep #101):\n{screen}",
        );
        // #104 is ready but claimed (rank 3, next_up=false, blocked_on=[])
        // → plain dim "W4", no next-up arrow and no dangling blocked-arrow
        // (the #795 review bug: this case used to fall through to the
        // blocked branch with an empty blocker, rendering "⊘W4←").
        assert!(
            screen.contains(" W4"),
            "#104 must show ' W4' (ready-but-claimed, rank 3→4):\n{screen}",
        );
        assert!(
            !screen.contains("↑W4"),
            "#104 (claimed) must NOT show the next-up arrow:\n{screen}",
        );
        assert!(
            !screen.contains("⊘W4"),
            "#104 (claimed) must NOT show a dangling blocked-arrow:\n{screen}",
        );
    }

    /// #1197 TuiDriver black-box: an epic's children nest under its Pipeline
    /// row instead of rendering as flat siblings.
    ///
    /// Seeds a `BoardData` with an epic (#100, "Epic tracker") carrying two
    /// `data.epic_children` entries (#101 open/"Child A", #102 closed/"Child
    /// B") in the same "v1.0" milestone bucket as an unrelated plain issue
    /// (#105, "Just a bug"). `pipeline_issues` also lists #101 directly (as
    /// it would be if it independently carried a tracked label) to prove the
    /// #1197 dedup: before this fix, #101 would render a second time as a
    /// flat sibling under the same milestone header.
    ///
    /// #1281 note: the epic classifies as In-progress (any Done child
    /// promotes it) so the nested render path is the In-progress
    /// filtered child list. #101 (Ready, no live session) nests under the
    /// filtered one; #102 (Done) is intentionally **absent** from the
    /// In-progress nested list — its "M/M done" contribution stays
    /// in the epic's own progress badge (asserted below), which reads off
    /// the unfiltered nesting. A distinct #1281 fixture below covers the
    /// hidden-child regression directly.
    ///
    /// Asserts, via `find`/`screen()` (never hardcoded coordinates):
    /// - #101 renders nested (strictly more indented — greater column)
    ///   directly beneath the epic row
    /// - #101 appears exactly once (the dedup — no flat-sibling duplicate)
    /// - #102 (Done) does NOT render — filtered out of the In-progress
    ///   instance by #1281 and suppressed from a flat top-level row by
    ///   `pipeline_globally_nested_children` (child of a tracked epic)
    /// - the unrelated plain issue #105 renders unchanged: same indent
    ///   (column) as the epic, not nested under anything
    /// - the epic's own "1/2 done" progress badge still renders on its row
    ///   — the summary reports against the WHOLE child set, unchanged by
    ///   #1281
    #[test]
    fn tuidriver_pipeline_epic_children_nest_under_epic_row() {
        use quadraui::tui::testing::driver_with_shell;

        let app = make_epic_nesting_app();
        let driver = driver_with_shell(app, CoordApp::shell_config(), 140, 50);
        let screen = driver.screen();

        let epic_pos = driver.find("#100").expect(&format!("epic #100 row must render:\n{screen}"));
        let child_a_pos = driver
            .find("#101")
            .expect(&format!("child #101 row must render nested:\n{screen}"));
        let sibling_pos = driver
            .find("#105")
            .expect(&format!("unrelated issue #105 must render unchanged:\n{screen}"));

        assert!(
            child_a_pos.0 > epic_pos.0,
            "#101 must be MORE indented (greater column) than its epic #100: epic={epic_pos:?} child={child_a_pos:?}\n{screen}",
        );
        assert!(
            child_a_pos.1 > epic_pos.1,
            "#101 must render BELOW the epic row: epic={epic_pos:?} a={child_a_pos:?}\n{screen}",
        );
        // #1281: the Done child #102 is filtered out of the In-progress →
        // In-progress nested child list and remains suppressed from
        // flat sibling rendering, so it must not render anywhere on the
        // Pipeline screen while its epic is still open.
        assert!(
            !driver.screen_contains("#102"),
            "#102 (Done child of an in-progress epic) must NOT render nested under In-progress (#1281):\n{screen}",
        );
        assert_eq!(
            sibling_pos.0, epic_pos.0,
            "a plain (non-epic) issue must render at the SAME indent as the epic — unchanged by #1197: epic={epic_pos:?} sibling={sibling_pos:?}\n{screen}",
        );

        // Dedup: #101 must appear exactly once — nested under #100, not
        // ALSO as a flat sibling in the same milestone bucket.
        assert_eq!(
            screen.matches("#101").count(),
            1,
            "#101 must render exactly once (nested, not duplicated as a flat sibling):\n{screen}",
        );

        // Child state badge — Ready (#101, open, no running assignment) —
        // reused from `milestone_dag::build_dag_nodes`.  Scoped to the row's
        // own line since "ready" could otherwise coincidentally match
        // unrelated chrome elsewhere on a 140x50 screen.
        let lines: Vec<&str> = screen.lines().collect();
        let child_a_line = lines
            .get(child_a_pos.1 as usize)
            .unwrap_or_else(|| panic!("no line at #101's row:\n{screen}"));
        assert!(
            child_a_line.contains("ready"),
            "#101's row must show a 'ready' badge: {child_a_line:?}\n{screen}",
        );
        // The epic's own `1/2 done` progress-badge coverage lives on
        // `tuidriver_pipeline_epic_row_shows_progress_summary` (same
        // fixture, but with a shortened title so the badge column has
        // guaranteed room to render past the sidebar's fixed width) —
        // don't duplicate that assertion here.
    }

