        // scrolls the viewport there.
        let n = 40;
        let app = make_app_with_audit_json(BoardData::default(), &audit_page_json_n_entries(n));
        let mut driver = driver_with_shell(app, CoordApp::shell_config(), 140, 40);
        click_activity_icon(&mut driver, "§");
