    // ── #1326: Project/Workspace model (A-1) ──────────────────────────────────

    /// Black-box boot check for the new Project/Workspace model: given a
    /// multi-repo `BoardData`, the app must boot with every known repo open
    /// and a sane, deterministic `active_project` — asserted via the model
    /// (`CoordApp::active_project`/`open_projects`), not screen-scraping, per
    /// the issue's own acceptance note ("no behavior visibly changes yet").
    /// Driven through the full `TuiDriver` (`driver_with_shell` +
    /// `ShellApp`) so a real boot pass (event → handle → render) is what's
    /// under test, not just a bare constructor call.
    #[test]
    fn boots_with_sane_default_active_project_for_multi_repo_board() {
        use quadraui::tui::testing::driver_with_shell;

        let data = BoardData {
            machines: vec![Machine {
                name: "m1".to_string(),
                host: String::new(),
                reachable: true,
                active_count: 0,
                repos: vec!["zeta".to_string(), "alpha".to_string()],
                version: None,
                worktree_bytes: 0,
            }],
            assignments: vec![make_assignment_typed("done", 1, "mid", Some("work"))],
            ..BoardData::default()
        };
        let app = make_test_app(data);

        // Model-level assertions on the plain `CoordApp` — `driver.app()`
        // isn't `CoordApp` (`driver_with_shell` wraps it in an opaque
        // `ShellAdapter`, see the other `TuiDriver` tests' comment above),
        // so the workspace model itself is checked here, before handing
        // `app` to the driver.

        // Every repo referenced anywhere in BoardData starts open.
        let mut open = app.open_projects().to_vec();
        open.sort();
        assert_eq!(
            open,
            vec!["alpha".to_string(), "mid".to_string(), "zeta".to_string()],
            "all repos known to BoardData must start open",
        );

        // Active project defaults deterministically to the alphabetically
        // first repo, independent of the order repos appear in BoardData.
        assert_eq!(
            app.active_project(),
            Some("alpha"),
            "active_project must default to the first repo in sorted order",
        );

        // Drive a real boot pass (event -> handle -> render) through the
        // full `TuiDriver` + `ShellApp` machinery to prove this doesn't
        // panic / blank-screen with the workspace model wired in — the
        // black-box half of this test, per the issue's acceptance note
        // ("no behavior visibly changes yet").
        let driver = driver_with_shell(app, CoordApp::shell_config(), 120, 40);
        assert!(
            !driver.screen().trim().is_empty(),
            "app must render a non-empty screen on boot",
        );
    }

    // ── #1563: paused-machine set stays daemon-aware on a thin client ───────
    //
    // Before this, `read_paused_machines()` always read the LOCAL
    // `~/.coord/paused_machines.json` directly, unconditionally, on every
    // periodic refresh — including on a thin client, where `coord pause`
    // now writes straight to the daemon instead of that file. The TUI's own
    // rescan would silently revert the optimistic `p`-keybind update a few
    // seconds later, so a machine the operator just paused kept being
    // selected by `best_machine_for()`. `poll_paused_machines` (the
    // `pending_paused_machines` receiver, armed by `spawn_paused_machines_fetch`)
    // replaces that direct read; these tests cover the merge logic and the
    // real network round trip separately from the local-file fallback,
    // which is unchanged from before this issue.

    #[test]
    fn poll_paused_machines_replaces_snapshot_when_ready() {
        let mut app = make_app_default();
        assert!(app.paused_machines.is_empty());
        let (tx, rx) = std::sync::mpsc::channel();
        tx.send(data::PausedFetch {
            paused: ["dellserver".to_string(), "elitebook".to_string()]
                .into_iter()
                .collect(),
            quiet: std::collections::HashSet::new(),
            cordoned: std::collections::HashSet::new(),
            quiet_hours: std::collections::HashMap::new(),
        })
        .unwrap();
        app.pending_paused_machines = Some(rx);

        assert!(app.poll_paused_machines(), "should report an update");
        assert_eq!(app.paused_machines.len(), 2);
        assert!(app.paused_machines.contains("dellserver"));
        assert!(app.paused_machines.contains("elitebook"));
        // The receiver is consumed — no repeat updates.
        assert!(app.pending_paused_machines.is_none());
        assert!(!app.poll_paused_machines());
    }

    #[test]
    fn poll_paused_machines_reverts_an_operator_pause_the_stale_local_file_would_have_undone() {
        // #1563's actual failure mode: the operator paused "dellserver"
        // (optimistic local update, mirroring the `p` keybind handler in
        // `events.rs`), then the daemon-aware sweep lands and must NOT wipe
        // it back out just because it agrees — this asserts the daemon's
        // response is what the badge/dispatch filter ends up reflecting,
        // not a stale local snapshot.
        let mut app = make_app_default();
        app.paused_machines.insert("dellserver".to_string());
        let (tx, rx) = std::sync::mpsc::channel();
        tx.send(data::PausedFetch {
            paused: ["dellserver".to_string()].into_iter().collect(),
            quiet: std::collections::HashSet::new(),
            cordoned: std::collections::HashSet::new(),
            quiet_hours: std::collections::HashMap::new(),
        })
        .unwrap();
        app.pending_paused_machines = Some(rx);

        // Same set both sides agree on → no redundant update reported, but
        // the pause must still be in force afterward.
        assert!(!app.poll_paused_machines());
        assert!(app.paused_machines.contains("dellserver"));
    }

    #[test]
    fn poll_paused_machines_noop_while_empty() {
        let mut app = make_app_default();
        let (_tx, rx) = std::sync::mpsc::channel::<data::PausedFetch>();
        app.pending_paused_machines = Some(rx);
        // Nothing sent yet → no update, receiver retained for a later poll.
        assert!(!app.poll_paused_machines());
        assert!(app.pending_paused_machines.is_some());
    }

    #[test]
    fn poll_paused_machines_disconnected_clears_pending() {
        let mut app = make_app_default();
        let (tx, rx) = std::sync::mpsc::channel::<data::PausedFetch>();
        drop(tx);
        app.pending_paused_machines = Some(rx);
        assert!(!app.poll_paused_machines());
        assert!(
            app.pending_paused_machines.is_none(),
            "a disconnected sender must not wedge the sweep forever"
        );
    }

    /// End-to-end: with the board service pointed at a live
    /// [`MockBoardService`], `spawn_paused_machines_fetch` must perform a
    /// real HTTP `GET /pause` and deliver the daemon's parsed set back over
    /// its channel — the network branch `coord.machine_pause.paused_set()`
    /// exercises on the Python side, now mirrored on the TUI side (#1563).
    #[test]
    fn spawn_paused_machines_fetch_hits_real_mock_server() {
        let mock = MockBoardService::start(r#"{"paused": ["dellserver", "precision"]}"#);
        let _guard = set_test_board_service(mock.url(), None);

        let rx = spawn_paused_machines_fetch();
        let got = rx
            .recv_timeout(std::time::Duration::from_secs(5))
            .expect("spawn_paused_machines_fetch must deliver a result before the timeout");

        assert_eq!(got.paused.len(), 2);
        assert!(got.paused.contains("dellserver"));
        assert!(got.paused.contains("precision"));
        // Fixture response has no "quiet" key — must degrade to empty
        // rather than erroring on the missing optional field.
        assert!(got.quiet.is_empty());

        let requests = mock.requests();
        assert_eq!(
            requests.len(),
            1,
            "expected exactly one request to reach the mock server; got {:?}",
            requests
        );
        assert!(
            requests[0].starts_with("GET /pause"),
            "spawn_paused_machines_fetch must GET /pause; got {:?}",
            requests[0]
        );
    }

    /// A malformed/unreachable daemon response must fail soft to an empty
    /// set — matching `coord.machine_pause.paused_set()`'s documented
    /// fail-open read contract — rather than propagating an error that
    /// could wedge the periodic refresh sweep.
    #[test]
    fn fetch_paused_machines_fails_soft_on_malformed_response() {
        let mock = MockBoardService::start("not json");
        let _guard = set_test_board_service(mock.url(), None);

        let got = fetch_paused_machines();
        assert!(
            got.paused.is_empty() && got.quiet.is_empty(),
            "a malformed daemon response must degrade to an empty result, got {:?}",
            got
        );
    }

    /// #1862: the daemon's `/pause` response distinguishes a quiet-hours
    /// pause from a hand pause via an optional `quiet` array (always a
    /// subset of `paused`) — the wire format `coord.serve_app.get_pause`
    /// emits. Assert the TUI's fetch parses it into `PausedFetch.quiet`
    /// rather than only ever reading `paused`.
    #[test]
    fn spawn_paused_machines_fetch_parses_quiet_field() {
        let mock = MockBoardService::start(
            r#"{"paused": ["dellserver", "elitebook"], "quiet": ["elitebook"]}"#,
        );
        let _guard = set_test_board_service(mock.url(), None);

        let rx = spawn_paused_machines_fetch();
        let got = rx
            .recv_timeout(std::time::Duration::from_secs(5))
            .expect("spawn_paused_machines_fetch must deliver a result before the timeout");

        assert_eq!(
            got.paused,
            ["dellserver".to_string(), "elitebook".to_string()]
                .into_iter()
                .collect()
        );
        assert_eq!(got.quiet, ["elitebook".to_string()].into_iter().collect());
    }

    /// #1862 review finding: an operator debugging a stalled queue at 1AM
    /// needs to tell a quiet-hours-covered machine apart from a
    /// hand-paused one in the TUI sidebar, not just in `coord status`.
    /// "elitebook" is quiet-paused (badge `[QUIET]`), "dellserver" is
    /// hand-paused only (badge `[PAUSED]`), "precision" is neither.
    #[test]
    fn machines_list_badges_quiet_paused_machine_differently_from_hand_paused() {
        fn machine(name: &str) -> Machine {
            Machine {
                name: name.to_string(),
                host: String::new(),
                reachable: true,
                active_count: 0,
                repos: vec![],
                version: None,
                worktree_bytes: 0,
            }
        }
        let data = BoardData {
            machines: vec![machine("dellserver"), machine("elitebook"), machine("precision")],
            ..BoardData::default()
        };
        let mut app = make_test_app(data);
        app.paused_machines = ["dellserver".to_string(), "elitebook".to_string()]
            .into_iter()
            .collect();
        app.quiet_paused_machines = ["elitebook".to_string()].into_iter().collect();

        let list = app.machines_list(true);
        let row_text = |name: &str| -> String {
            list.items
                .iter()
                .zip(app.data.machines.iter())
                .find(|(_, m)| m.name == name)
                .map(|(item, _)| {
                    item.text.spans.iter().map(|s| s.text.as_str()).collect::<String>()
                })
                .unwrap_or_default()
        };

        assert!(row_text("dellserver").contains("[PAUSED]"), "{}", row_text("dellserver"));
        assert!(!row_text("dellserver").contains("[QUIET]"));
        assert!(row_text("elitebook").contains("[QUIET]"), "{}", row_text("elitebook"));
        assert!(!row_text("elitebook").contains("[PAUSED]"));
        assert!(!row_text("precision").contains("[PAUSED]"));
        assert!(!row_text("precision").contains("[QUIET]"));
    }

    /// #2101 trap E: "work stopping with no stated reason is the thing this
    /// fleet keeps doing to itself". A machine draining so the fleet can roll
    /// onto a released version IS in `paused` (that is how routing honours a
    /// cordon), so without its own badge it reads as `[PAUSED]` — telling the
    /// operator a human stopped it and that `coord unpause` is the fix. Both
    /// are wrong: nobody paused it, `coord unpause` does not clear it, and it
    /// lifts itself the moment the roll lands.
    #[test]
    fn machines_list_badges_a_release_cordon_differently_from_a_pause() {
        fn machine(name: &str) -> Machine {
            Machine {
                name: name.to_string(),
                host: String::new(),
                reachable: true,
                active_count: 0,
                repos: vec![],
                version: None,
                worktree_bytes: 0,
            }
        }
        let data = BoardData {
            machines: vec![machine("dellserver"), machine("elitebook")],
            ..BoardData::default()
        };
        let mut app = make_test_app(data);
        // Both are in `paused` — the cordon is a routing pause. Only
        // dellserver's is a release cordon.
        app.paused_machines = ["dellserver".to_string(), "elitebook".to_string()]
            .into_iter()
            .collect();
        app.cordoned_machines = ["dellserver".to_string()].into_iter().collect();

        let list = app.machines_list(true);
        let row_text = |name: &str| -> String {
            list.items
                .iter()
                .zip(app.data.machines.iter())
                .find(|(_, m)| m.name == name)
                .map(|(item, _)| {
                    item.text.spans.iter().map(|s| s.text.as_str()).collect::<String>()
                })
                .unwrap_or_default()
        };

        assert!(row_text("dellserver").contains("[DRAINING]"), "{}", row_text("dellserver"));
        assert!(!row_text("dellserver").contains("[PAUSED]"));
        assert!(row_text("elitebook").contains("[PAUSED]"), "{}", row_text("elitebook"));
        assert!(!row_text("elitebook").contains("[DRAINING]"));
    }

    /// A cordon arriving with unchanged `paused` membership must still
    /// redraw — otherwise a machine flips from hand-paused to cordoned and
    /// the sidebar goes on claiming an operator did it.
    #[test]
    fn poll_paused_machines_reports_an_update_when_only_the_cordon_set_changed() {
        let mut app = make_app_default();
        app.paused_machines = ["dellserver".to_string()].into_iter().collect();
        let (tx, rx) = std::sync::mpsc::channel();
        tx.send(data::PausedFetch {
            paused: ["dellserver".to_string()].into_iter().collect(),
            quiet: std::collections::HashSet::new(),
            cordoned: ["dellserver".to_string()].into_iter().collect(),
            quiet_hours: std::collections::HashMap::new(),
        })
        .unwrap();
        app.pending_paused_machines = Some(rx);

        assert!(app.poll_paused_machines(), "a new cordon must trigger a redraw");
        assert!(app.cordoned_machines.contains("dellserver"));
    }

    // ── #2147: TUI half of "set a machine's quiet hours from the Machines
    // panel" — right-click → "Set quiet hours…" opens a single-text-input
    // dialog (`pending_quiet_hours`), pre-filled from `quiet_hours_windows`
