    #[test]
    fn tuidriver_quiet_hours_submit_closes_dialog_and_toasts() {
        use quadraui::tui::testing::driver_with_shell;

        let app = CoordApp {
            data: BoardData {
                machines: vec![quiet_hours_machine("dellserver")],
                ..BoardData::default()
            },
            active_view: SidebarView::Machines,
            ..make_test_app(BoardData::default())
        };
        let mut driver = driver_with_shell(app, CoordApp::shell_config(), 140, 40);

        let (x, y) = driver.find("● dellserver").unwrap();
        driver.dispatch(UiEvent::MouseDown {
            widget: None,
            button: MouseButton::Right,
            position: Point::new(x, y),
            modifiers: Modifiers::default(),
        });
        // Menu order: "Pause routing" (idx 0, initial selection), "Set
        // quiet hours…" (idx 1). Keyboard nav, not a raw coordinate click —
        // see `tuidriver_copy_issue_number_writes_clipboard_and_toasts_copied`
        // for why: a click on a context-menu item's text doesn't reliably
        // land on the popup's hit-test in these tests, only Dialog buttons do.
        driver.press_named(quadraui::NamedKey::Down);
        driver.press_named(quadraui::NamedKey::Enter);

        // The dialog opens pre-filled with "22:00-08:00" — clear it first
        // (Backspace × len) so the submitted window is exactly what this
        // test types, not a leftover default.
        for _ in 0.."22:00-08:00".len() {
            driver.press_named(quadraui::NamedKey::Backspace);
        }
        for ch in "21:00-06:00".chars() {
            driver.press(Key::Char(ch));
        }
        let (sx, sy) = driver.find("Submit").unwrap_or_else(|| {
            panic!("#2147: dialog Submit button not found:\n{}", driver.screen())
        });
        driver.click(sx, sy);

        let screen = driver.screen();
        // The toast wraps/truncates at panel width ("...quiet hours set
        // 21:00-06" in a 140-col terminal) — match the stable prefix rather
        // than the full window text.
        assert!(
            screen.contains("quiet hours set 21:00-06"),
            "#2147: a well-formed submit must toast confirmation:\n{screen}",
        );
        assert!(
            !screen.contains("Set quiet hours: dellserver"),
            "#2147: the dialog must close after a successful submit:\n{screen}",
        );
    }

    /// Black-box (#2147 acceptance): malformed input must keep the dialog
    /// open (buffer intact, so the operator can fix the typo) and must NOT
    /// close it or report success — the "no confirmation, nothing spawned"
    /// contract.
    #[test]
    fn tuidriver_quiet_hours_malformed_input_keeps_dialog_open() {
        use quadraui::tui::testing::driver_with_shell;

        let app = CoordApp {
            data: BoardData {
                machines: vec![quiet_hours_machine("dellserver")],
                ..BoardData::default()
            },
            active_view: SidebarView::Machines,
            ..make_test_app(BoardData::default())
        };
        let mut driver = driver_with_shell(app, CoordApp::shell_config(), 140, 40);

        let (x, y) = driver.find("● dellserver").unwrap();
        driver.dispatch(UiEvent::MouseDown {
            widget: None,
            button: MouseButton::Right,
            position: Point::new(x, y),
            modifiers: Modifiers::default(),
        });
        // Menu order: "Pause routing" (idx 0, initial selection), "Set
        // quiet hours…" (idx 1). Keyboard nav, not a raw coordinate click —
        // see `tuidriver_copy_issue_number_writes_clipboard_and_toasts_copied`
        // for why: a click on a context-menu item's text doesn't reliably
        // land on the popup's hit-test in these tests, only Dialog buttons do.
        driver.press_named(quadraui::NamedKey::Down);
        driver.press_named(quadraui::NamedKey::Enter);

        for _ in 0.."22:00-08:00".len() {
            driver.press_named(quadraui::NamedKey::Backspace);
        }
        for ch in "not-a-window".chars() {
            driver.press(Key::Char(ch));
        }
        let (sx, sy) = driver.find("Submit").unwrap();
        driver.click(sx, sy);

        let screen = driver.screen();
        assert!(
            screen.contains("Set quiet hours: dellserver"),
            "#2147: a malformed submit must NOT close the dialog:\n{screen}",
        );
        assert!(
            screen.contains("not-a-window"),
            "#2147: the buffer must survive a failed submit unchanged:\n{screen}",
        );
        assert!(
            !screen.contains("quiet hours set"),
            "#2147: a malformed submit must never report success:\n{screen}",
        );
    }

    /// Direct-app: the exact argv `submit_quiet_hours` hands to
    /// `command_runner.spawn_queued` — no tz typed ⇒ no `--tz` flag (the CLI
    /// defaults to the operator's own machine zone, see
    /// `coord.commands.agent_ops._local_tz_name`); a tz typed ⇒ `--tz`
    /// appended.
    #[test]
    fn submit_quiet_hours_spawns_expected_argv() {
        let mut app = make_test_app(BoardData {
            machines: vec![quiet_hours_machine("dellserver")],
            ..BoardData::default()
        });
        app.open_quiet_hours_dialog("dellserver".to_string());
        app.pending_quiet_hours.as_mut().unwrap().buf = "22:00-08:00".to_string();
        app.submit_quiet_hours();

        assert_eq!(
            app.command_runner.spawned_calls,
            vec![vec![
                "quiet-hours".to_string(),
                "dellserver".to_string(),
                "22:00-08:00".to_string(),
            ]],
        );
        assert!(app.pending_quiet_hours.is_none(), "a clean submit must close the dialog");

        let mut app = make_test_app(BoardData {
            machines: vec![quiet_hours_machine("dellserver")],
            ..BoardData::default()
        });
        app.open_quiet_hours_dialog("dellserver".to_string());
        app.pending_quiet_hours.as_mut().unwrap().buf =
            "22:00-08:00 America/Chicago".to_string();
        app.submit_quiet_hours();

        assert_eq!(
            app.command_runner.spawned_calls,
            vec![vec![
                "quiet-hours".to_string(),
                "dellserver".to_string(),
                "22:00-08:00".to_string(),
                "--tz".to_string(),
                "America/Chicago".to_string(),
            ]],
        );
    }

    /// Direct-app (#2147 acceptance): malformed input must never reach
    /// `spawn_queued` at all, and must re-arm `pending_quiet_hours` with the
    /// buffer intact rather than clearing it.
    #[test]
    fn submit_quiet_hours_malformed_input_spawns_nothing() {
        let mut app = make_test_app(BoardData {
            machines: vec![quiet_hours_machine("dellserver")],
            ..BoardData::default()
        });
        app.open_quiet_hours_dialog("dellserver".to_string());
        app.pending_quiet_hours.as_mut().unwrap().buf = "garbage".to_string();
        app.submit_quiet_hours();

        assert!(
            app.command_runner.spawned_calls.is_empty(),
            "a malformed window must never spawn: {:?}",
            app.command_runner.spawned_calls,
        );
        let pending = app
            .pending_quiet_hours
            .as_ref()
            .expect("a parse error must keep the dialog open");
        assert_eq!(pending.buf, "garbage", "the buffer must survive intact for a retry");
    }

    /// Direct-app (#2147 acceptance): Cancel — `dismiss_prompt_dialog`, the
    /// same outside-click/Esc path every other single-buffer prompt in this
    /// file uses (see `dismiss_prompt_dialog_clears_quit_confirm` etc.) —
    /// must discard the pending dialog and spawn nothing.
    #[test]
    fn dismiss_prompt_dialog_clears_quiet_hours_and_spawns_nothing() {
        let mut app = make_test_app(BoardData {
            machines: vec![quiet_hours_machine("dellserver")],
            ..BoardData::default()
        });
        app.open_quiet_hours_dialog("dellserver".to_string());
        assert!(app.pending_quiet_hours.is_some());

        app.dismiss_prompt_dialog();

        assert!(app.pending_quiet_hours.is_none());
        assert!(app.command_runner.spawned_calls.is_empty());
    }

    /// Direct-app: "Clear quiet hours" (the direct context-menu action, no
    /// dialog) spawns `coord quiet-hours <name> --clear` and removes the
    /// entry from `quiet_hours_windows` so the menu immediately reads "Set
    /// quiet hours…" again rather than a stale schedule.
    #[test]
    fn dispatch_quiet_hours_clear_spawns_expected_argv_and_clears_map() {
        let mut app = make_test_app(BoardData {
            machines: vec![quiet_hours_machine("dellserver")],
            ..BoardData::default()
        });
        app.quiet_hours_windows.insert(
            "dellserver".to_string(),
            data::QuietHoursWindow {
                start: "21:00".to_string(),
                end: "07:30".to_string(),
                tz: "America/Chicago".to_string(),
                source: "store".to_string(),
            },
        );

        let handled = app.dispatch_quiet_hours_clear("dellserver");

        assert!(handled);
        assert_eq!(
            app.command_runner.spawned_calls,
            vec![vec![
                "quiet-hours".to_string(),
                "dellserver".to_string(),
                "--clear".to_string(),
            ]],
        );
        assert!(
            !app.quiet_hours_windows.contains_key("dellserver"),
            "clearing must drop the local schedule entry",
        );
    }

    /// #2147 correctness trap: setting a window for LATER TONIGHT must not
    /// badge the machine `[QUIET]` right now — `quiet_hours_windows` (the
    /// schedule) and `quiet_paused_machines` (who is covered THIS INSTANT)
    /// are independent fields, and only the latter drives the badge. A
    /// machine that's merely scheduled must keep reading as available.
    #[test]
    fn machines_list_does_not_badge_quiet_for_a_window_that_has_not_started_yet() {
        let mut app = make_test_app(BoardData {
            machines: vec![quiet_hours_machine("dellserver")],
            ..BoardData::default()
        });
        // A window IS set (source: store) but does not cover *now* — the
        // daemon would not have included this machine in `quiet`, so
        // `quiet_paused_machines` stays empty even though the schedule map
        // has an entry.
        app.quiet_hours_windows.insert(
            "dellserver".to_string(),
            data::QuietHoursWindow {
                start: "22:00".to_string(),
                end: "08:00".to_string(),
                tz: "UTC".to_string(),
                source: "store".to_string(),
            },
        );
        assert!(app.quiet_paused_machines.is_empty());
        assert!(app.paused_machines.is_empty());

        let list = app.machines_list(true);
        let row_text = list.items[0]
            .text
            .spans
            .iter()
            .map(|s| s.text.as_str())
            .collect::<String>();

        assert!(
            !row_text.contains("[QUIET"),
            "#2147: a window scheduled for later must not badge the machine \
             quiet right now:\n{row_text}",
        );
        assert!(!row_text.contains("[PAUSED]"));
    }

    /// The sidebar badge itself, once a window DOES cover *now*, must show
    /// the schedule text (`[QUIET HH:MM-HH:MM]`), not the bare `[QUIET]` —
    /// the whole point of #2147 wiring `quiet_hours_windows` through to
    /// `machines_list`.
    #[test]
    fn machines_list_badges_quiet_with_schedule_when_currently_covered() {
        let mut app = make_test_app(BoardData {
            machines: vec![quiet_hours_machine("dellserver")],
            ..BoardData::default()
        });
        app.paused_machines = ["dellserver".to_string()].into_iter().collect();
        app.quiet_paused_machines = ["dellserver".to_string()].into_iter().collect();
        app.quiet_hours_windows.insert(
            "dellserver".to_string(),
            data::QuietHoursWindow {
                start: "22:00".to_string(),
                end: "08:00".to_string(),
                tz: "UTC".to_string(),
                source: "config".to_string(),
            },
        );

        let list = app.machines_list(true);
        let row_text = list.items[0]
            .text
            .spans
            .iter()
            .map(|s| s.text.as_str())
            .collect::<String>();

        assert!(
            row_text.contains("[QUIET 22:00-08:00]"),
            "#2147: a currently-covered window must badge with its schedule:\n{row_text}",
        );
    }

    // ── #1553: oracle-loop slice work is attributed to the CHILD issue ──────
    //
    // `coord acceptance author <repo> <tracking> --issue N` books its
    // assignment (and every review/fix/smoke derived from it) with
    // `issue_number = <tracking>` — the whole milestone's JIT slices share one
    // branch and one PR, so `issue_number` cannot be the child. The child
    // lives in `for_issue_number`, and that is what "is this issue being
    // worked?" / "what did this issue cost?" must read.
    //
    // Observed live: 26 assignments booked to epic #1120, 0 to child #1124,
    // while three authoring rounds, a smoke and three reviews were in flight
    // for #1124. The operator's report was "I don't think 1124 is running,
    // the TUI shows no activity."

    /// Pipeline app with a tracking/epic issue (#1120) and one of its work-
    /// order children (#1124), both under coord repo "api".
    fn make_slice_attribution_app() -> CoordApp {
        let data = BoardData {
            pipeline_default_gates: vec!["review".to_string(), "merge".to_string()],
            pipeline_tracked_labels: vec!["coord".to_string()],
            pipeline_repos: vec![("api".to_string(), "acme/api".to_string())],
            ..BoardData::default()
        };
        let mut app = make_test_app(data);
        app.pipeline_issues = vec![
            PipelineIssue {
                number: 1120,
                title: "ms-38 tracking".to_string(),
                body: String::new(),
                repo_slug: "acme/api".to_string(),
                coord_repo: Some("api".to_string()),
                matched_labels: vec!["coord".to_string()],
                all_labels: vec!["coord".to_string(), "status:ready".to_string()],
                is_closed: false,
                body_truncated: false,
                body_len: None,
            },
            PipelineIssue {
                number: 1124,
                title: "ms-38 child".to_string(),
                body: String::new(),
                repo_slug: "acme/api".to_string(),
                coord_repo: Some("api".to_string()),
                matched_labels: vec!["coord".to_string()],
                all_labels: vec!["coord".to_string(), "status:ready".to_string()],
                is_closed: false,
                body_truncated: false,
                body_len: None,
            },
        ];
        app.rebuild_pipeline_sidebar(None);
        app
    }

    /// A `test-author` slice row exactly as `coord acceptance author
    /// <repo> 1120 --issue 1124` records it.
    fn slice_assignment(status: &str, id: &str) -> Assignment {
        let mut a = make_assignment_typed(status, 1120, "api", Some("test-author"));
        a.id = id.to_string();
        a.issue_title = "[test-author] ms-38 slice #1124".to_string();
        a.branch = Some("ms-38-acceptance".to_string());
        a.for_issue_number = Some(1124);
        a
    }

    fn pipeline_issue_numbered(app: &CoordApp, number: u64) -> &PipelineIssue {
        app.pipeline_issues
            .iter()
            .find(|i| i.number == number)
            .expect("fixture issue must exist")
    }

    #[test]
    fn effective_issue_number_prefers_the_slice_child() {
        let a = slice_assignment("running", "author-1");
        assert_eq!(a.effective_issue_number(), 1124);
        // The parent link must survive — the epic still rolls up through it.
        assert_eq!(a.issue_number, 1120);
    }

    #[test]
    fn effective_issue_number_falls_back_for_ordinary_work() {
        let a = make_assignment_typed("running", 42, "api", Some("work"));
        assert_eq!(a.effective_issue_number(), 42);
    }

    #[test]
    fn slice_work_makes_the_child_row_in_progress_not_idle() {
        // The headline #1553 assertion: the child's Pipeline row must show
        // activity while its acceptance slice runs, instead of sitting in
        // Pending as though nothing had been dispatched for it.
        let mut app = make_slice_attribution_app();
        app.data.assignments.push(slice_assignment("running", "author-1"));
        let child = pipeline_issue_numbered(&app, 1124);
        assert_eq!(
            app.pipeline_lifecycle_section(child),
            "in-progress",
            "a child with a live acceptance slice must not read as idle/pending"
        );
    }

    #[test]
    fn slice_work_does_not_make_the_tracking_row_in_progress() {
        // "The epic row should aggregate, not absorb." With no work of its
        // own, the tracking issue must not be promoted to In-progress purely
        // because a child's slice is booked under its number.
        let mut app = make_slice_attribution_app();
        app.data.assignments.push(slice_assignment("running", "author-1"));
        let tracking = pipeline_issue_numbered(&app, 1120);
        assert_ne!(
            app.pipeline_lifecycle_section(tracking),
            "in-progress",
            "the epic must not absorb its child's slice as its own work"
        );
    }

    #[test]
    fn tracking_issue_own_work_still_makes_it_in_progress() {
        // Guardrail: re-attribution must not stop the epic's OWN work (Gate A
        // mock-author, dispatched against the tracking issue with no
        // `for_issue_number`) from registering on the epic's row.
        let mut app = make_slice_attribution_app();
        app.data
            .assignments
            .push(make_assignment_typed("running", 1120, "api", Some("mock-author")));
        let tracking = pipeline_issue_numbered(&app, 1120);
        assert_eq!(app.pipeline_lifecycle_section(tracking), "in-progress");
    }

    #[test]
    fn ordinary_work_lifecycle_is_unchanged() {
        let mut app = make_slice_attribution_app();
        app.data
            .assignments
            .push(make_assignment_typed("running", 1124, "api", Some("work")));
        let child = pipeline_issue_numbered(&app, 1124);
        assert_eq!(app.pipeline_lifecycle_section(child), "in-progress");
        let tracking = pipeline_issue_numbered(&app, 1120);
        assert_ne!(app.pipeline_lifecycle_section(tracking), "in-progress");
    }

    #[test]
    fn slice_cost_rolls_up_to_the_child_not_the_epic() {
        // #1117 / milestone #37 reads per-issue cost from exactly this path.
        // $7.90 of #1124's slice authoring was being booked to epic #1120.
        let mut app = make_slice_attribution_app();
        let mut author = slice_assignment("done", "author-1");
        author.cost_usd = Some(7.90);
        author.input_tokens = 1_000;
        author.output_tokens = 500;
        let mut epic_own = make_assignment_typed("done", 1120, "api", Some("mock-author"));
        epic_own.cost_usd = Some(1.10);
        epic_own.input_tokens = 100;
        epic_own.output_tokens = 50;
        app.data.assignments.push(author);
        app.data.assignments.push(epic_own);

        let child = pipeline_issue_numbered(&app, 1124);
        let child_cost = app.issue_total_cost(child).expect("child must carry cost");
        assert!(
            (child_cost - 7.90).abs() < 1e-9,
            "expected the slice's $7.90 on the child, got {child_cost}"
        );
        assert_eq!(app.issue_total_tokens(child), 1_500);

        let tracking = pipeline_issue_numbered(&app, 1120);
        let epic_cost = app.issue_total_cost(tracking).expect("epic keeps its own cost");
        assert!(
            (epic_cost - 1.10).abs() < 1e-9,
            "the epic must keep only its own $1.10, got {epic_cost}"
        );
        assert_eq!(app.issue_total_tokens(tracking), 150);
    }

    #[test]
    fn acceptance_authoring_prereq_still_resolves_for_the_child() {
        // Regression guard: #1553 must not disturb the #1084 mini-pipeline,
        // which resolves the slice by (issue_number == tracking) AND
        // (type == "test-author") AND (for_issue_number == child).
        let mut app = make_slice_attribution_app();
        app.data.assignments.push(slice_assignment("running", "author-1"));
        let child = pipeline_issue_numbered(&app, 1124);
        let status = app.acceptance_authoring_prereq_status(child, 1120);
        assert!(
            status.author_id.is_some(),
            "the child's Acceptance-Authoring box must still find its slice"
        );
    }

    // ── #1631 (H-4): fleet-health status-bar indicator + detail overlay ────

    /// One machine, CRIT disk check — the seed the acceptance bar itself
    /// specifies ("seed BoardData with a CRIT disk value").
    fn crit_fleet_health() -> FleetHealthBlock {
        FleetHealthBlock {
            machine_health: vec![FleetMachineHealth {
                machine: "laptop".to_string(),
                state: "online".to_string(),
                severity: "crit".to_string(),
                stale: false,
                checked_at: Some(1_700_000_000.0),
                results: vec![FleetHealthCheckResult {
                    title: "disk".to_string(),
                    label: "disk /".to_string(),
                    severity: "crit".to_string(),
                    headroom: "2% free (1G free)".to_string(),
                    threshold: "crit at 7%".to_string(),
                    ..FleetHealthCheckResult::default()
                }],
                ..FleetMachineHealth::default()
            }],
            fleet_checks: vec![],
        }
    }

    /// The acceptance bar's black-box scenario, end to end: seed a CRIT
    /// disk value, assert the status-bar indicator renders CRIT, open the
    /// detail overlay (right-click the status bar -> "Fleet health…" menu
    /// entry, its accelerator shown inside the menu -> click it), assert the
    /// offending machine and its headroom string appear.
    #[test]
    fn tuidriver_fleet_health_status_bar_crit_and_overlay_show_machine_and_headroom() {
        use quadraui::tui::testing::driver_with_shell;

        let data = BoardData {
            fleet_health: crit_fleet_health(),
            ..BoardData::default()
        };
        let app = make_test_app(data);
        let mut driver = driver_with_shell(app, CoordApp::shell_config(), 140, 40);

        // The aggregate indicator is always present (not just on trouble) and
        // reflects the seeded CRIT machine — one unit, one CRIT.
        let screen = driver.screen();
        assert!(
            screen.contains("FLEET: CRIT 1"),
            "#1631: status bar must render the CRIT aggregate:\n{}",
            screen
        );

        // Reached by right-click — not a status-bar letter row the operator
        // has to already know about.
        let (x, y) = driver.find("FLEET").unwrap_or_else(|| {
            panic!(
                "#1631: fleet-health status-bar segment not found:\n{}",
                driver.screen()
            )
        });
        driver.dispatch(UiEvent::MouseDown {
            widget: None,
            button: MouseButton::Right,
            position: Point::new(x, y),
            modifiers: Modifiers::default(),
        });
        let menu_screen = driver.screen();
        assert!(
            menu_screen.contains("Fleet health"),
            "#1631: right-click on the status bar must open the 'Fleet health…' \
             menu entry:\n{}",
            menu_screen
        );

        // Activate the pre-selected (only) item via Enter, not a second
        // mouse click on the menu row — a mouse click on context-menu item
        // rows hits a pre-existing quadraui hit-test/paint offset (see
        // `tuidriver_send_to_pipeline_posts_directly_to_daemon_no_subprocess`'s
        // comment on the same caveat); Enter drives `selected_idx` directly.
        driver.press_named(NamedKey::Enter);

        let overlay_screen = driver.screen();
        assert!(
            overlay_screen.contains("laptop"),
            "#1631: detail overlay must name the offending machine:\n{}",
            overlay_screen
        );
        assert!(
            overlay_screen.contains("2% free (1G free)"),
            "#1631: detail overlay must show the check's headroom string:\n{}",
            overlay_screen
        );
    }

    /// A machine reporting no health at all (never polled — the shape
    /// `coord.health.fleet_snapshot._machine_health_rows` produces for an
    /// absent DB row) must render as `unknown`/`?`, visually distinct from
    /// an `OK` machine — never silently green (#1485's failure mode).
    #[test]
    fn tuidriver_fleet_health_unknown_machine_distinct_from_ok() {
        use quadraui::tui::testing::driver_with_shell;

        let data = BoardData {
            fleet_health: FleetHealthBlock {
                machine_health: vec![
                    FleetMachineHealth {
                        machine: "server".to_string(),
                        state: "online".to_string(),
                        severity: "ok".to_string(),
                        stale: false,
                        checked_at: Some(1_700_000_000.0),
                        results: vec![],
                    },
                    FleetMachineHealth {
                        machine: "ghost".to_string(),
                        state: "unknown".to_string(),
                        severity: "unknown".to_string(),
                        stale: false,
                        checked_at: None,
                        results: vec![],
                    },
                ],
                fleet_checks: vec![],
            },
            ..BoardData::default()
        };
        let app = make_test_app(data);
        let mut driver = driver_with_shell(app, CoordApp::shell_config(), 140, 40);

        let screen = driver.screen();
        assert!(
            !screen.contains("FLEET: OK"),
            "#1631: a machine with no health data must not render the fleet \
             as OK:\n{}",
            screen
        );
        assert!(
            screen.contains("FLEET: ? 1"),
            "#1631: the unknown machine must be counted and surfaced, \
             distinct from OK:\n{}",
            screen
        );

        // Open the overlay and confirm the unknown machine renders visibly
        // differently from the healthy one (its header carries "unknown").
        let (x, y) = driver.find("FLEET").expect("status bar must render");
        driver.dispatch(UiEvent::MouseDown {
            widget: None,
            button: MouseButton::Right,
            position: Point::new(x, y),
            modifiers: Modifiers::default(),
        });
        driver
            .find("Fleet health")
            .expect("'Fleet health…' menu entry must render");
        // Enter, not a second click — see the sibling CRIT test's comment
        // for why a mouse click on the menu row itself is unreliable here.
        driver.press_named(NamedKey::Enter);

        let overlay_screen = driver.screen();
        assert!(
            overlay_screen.contains("ghost"),
            "#1631: overlay must list the unknown machine:\n{}",
            overlay_screen
        );
        assert!(
            overlay_screen.contains("stale/unknown"),
            "#1631: the unknown machine's row must be visibly marked distinct \
             from a healthy one:\n{}",
            overlay_screen
        );
    }

    // ── #1741: Reports panel (MultiSectionView) ─────────────────────────────
    //
    // There is no sealed acceptance slice for #1741 (`tests/acceptance/**`
    // has no ms- directory for it), so these in-crate `TuiDriver` tests are
    // the gate. Every one of them locates its target with `driver.find(...)`
    // — never a hardcoded coordinate — so a layout change fails loudly at
    // the assertion rather than silently clicking empty space.
    //
    // The catalogue JSON below is deliberately a *fixture*, not a copy of
    // `coord/reports.py`'s real catalogue: the panel's whole contract is
    // that it renders whatever the daemon sends, so the tests exercise
    // shapes the real catalogue doesn't have (a second report, a second
    // param, > 5 choices) to prove no report is baked into Rust.

    /// One report, two params: a 5-choice `choice` (→ SegmentedControl) and
    /// a free-text one (→ TextInput). Mirrors #1742's `issue-activity`
    /// wire shape (`ReportParam.to_dict`).
    fn reports_catalogue_json() -> &'static str {
        r#"{
                "reports": [
                    {
                        "id": "issue-activity",
                        "title": "Issue Activity",
                        "description": "What happened to each issue in a window",
                        "params": [
                            {
                                "id": "since", "label": "Time range", "kind": "choice",
                                "choices": ["1h", "6h", "24h", "3d", "7d"],
                                "default": "24h", "help": "Window length",
                                "free_form": true
                            },
                            {
                                "id": "repo", "label": "Repo", "kind": "text",
                                "choices": [], "default": "", "help": "Empty means all repos",
                                "free_form": false
                            }
                        ]
                    }
                ]
            }"#
    }

    /// A *different* catalogue with a second report and differently-named
    /// params — the "adding report #2 needs zero tui/** changes" proof.
    fn reports_catalogue_json_two_reports() -> &'static str {
        r#"{
                "reports": [
                    {
                        "id": "issue-activity",
                        "title": "Issue Activity",
                        "description": "d1",
                        "params": [
                            {
                                "id": "since", "label": "Time range", "kind": "choice",
                                "choices": ["1h", "6h", "24h"], "default": "24h",
                                "help": "", "free_form": true
                            }
                        ]
                    },
                    {
                        "id": "worker-throughput",
                        "title": "Worker Throughput",
                        "description": "d2",
                        "params": [
                            {
                                "id": "machine", "label": "Machine", "kind": "text",
                                "choices": [], "default": "dellserver", "help": "", "free_form": false
                            },
                            {
                                "id": "bucket", "label": "Bucket", "kind": "choice",
                                "choices": ["hour", "day"], "default": "day",
                                "help": "", "free_form": false
                            }
                        ]
                    }
                ]
            }"#
    }

    /// A completed `GET /report/{id}` body: two rows + one note.
    fn reports_result_json() -> String {
        let now = std::time::SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap_or_default()
            .as_secs_f64();
        format!(
            r#"{{
                    "report_id": "issue-activity",
                    "generated_at": {now},
                    "window": [{start}, {now}],
                    "columns": ["issue", "outcome", "iterations"],
                    "rows": [
                        {{"issue": "claude-coordinator#1629", "outcome": "merged",
                          "iterations": 1, "extra_key": "ignored"}},
                        {{"issue": "claude-coordinator#1631", "outcome": "merged",
                          "iterations": 0}}
                    ],
                    "notes": ["ANOMALY_MARKER: #1631 exit_code=1 but merged"]
                }}"#,
            now = now,
            start = now - 3600.0,
        )
    }

    /// An empty-window result — zero rows, no notes.
    fn reports_result_json_empty() -> String {
        let now = std::time::SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap_or_default()
            .as_secs_f64();
        format!(
            r#"{{
                    "report_id": "issue-activity",
                    "generated_at": {now},
                    "window": [{start}, {now}],
                    "columns": ["issue", "outcome"],
                    "rows": [],
                    "notes": []
                }}"#,
            now = now,
            start = now - 3600.0,
        )
    }

    /// The current value of `report_id`'s `param_id` param, read straight
    /// off app state.
    ///
    /// #1911: a `choice` param rendered as a `SegmentedControl` marks its
    /// selected option with colour alone (`accent_fg` vs `dim_fg` in
    /// `quadraui`'s TUI rasteriser) — `TuiDriver::screen()` is plain text
    /// with no style information, so it cannot tell which option is
    /// selected. Pre-#1911 the sidebar carried a redundant `"{label}:
    /// {value}"` text line specifically so screen-text assertions (and a
    /// human squinting at a dim palette) had a way to read the selection;
    /// #1911 dropped that line as part of "sidebar is only the form now".
    /// Reading the value straight off app state is the direct replacement —
    /// same pattern the Settings-panel tests already use for their own
    /// `SegmentedControl` fields.
    fn reports_param_value_now(app: &CoordApp, report_id: &str, param_id: &str) -> String {
        let def = app
            .reports_catalogue()
            .iter()
            .find(|d| d.id == report_id)
            .unwrap_or_else(|| panic!("report {report_id:?} not in catalogue"));
        let param = def
            .params
            .iter()
            .find(|p| p.id == param_id)
            .unwrap_or_else(|| panic!("param {param_id:?} not on report {report_id:?}"));
        app.reports_param_value(report_id, param)
    }

