    // ── #1762: result-table formatting, sizing, and column sort ──────────
    //
    // Every test below renders through `driver_with_shell` and asserts on
    // the *rendered grid*, because the whole issue is "the table is
    // illegible" — a model-level assertion that `column_meta` was parsed
    // would prove nothing about what the operator sees. Coordinates come
    // from `driver.find()`, never hardcoded.

    /// A completed run carrying #1760 `column_meta`: one column of each
    /// kind that changes rendering (`int`, `text`, `timestamp`, `list`),
    /// one deliberately over-weighted column, and two rows whose numeric
    /// order is the *opposite* of their lexical order in every numeric
    /// column — so a lexical sort can never accidentally pass.
    ///
    /// `ZEBRA-ROW` is first in the daemon's own order and carries the old
    /// timestamp, the two-machine list, and `fixes: 10`; `ALPHA-ROW` is
    /// second, recent, with an empty list and `fixes: 2`.
    fn reports_result_json_meta() -> String {
        let now = std::time::SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap_or_default()
            .as_secs_f64();
        format!(
            r#"{{
                    "report_id": "issue-activity",
                    "generated_at": {now},
                    "window": [{start}, {now}],
                    "columns": ["issue", "title", "started_at", "machines", "fixes"],
                    "column_meta": [
                        {{"id": "issue", "label": "Issue", "kind": "int",
                          "align": "right", "weight": 1.0}},
                        {{"id": "title", "label": "Title", "kind": "text",
                          "align": "left", "weight": 3.0}},
                        {{"id": "started_at", "label": "Started", "kind": "timestamp",
                          "align": "left", "weight": 1.0}},
                        {{"id": "machines", "label": "Machines", "kind": "list",
                          "align": "left", "weight": 2.5}},
                        {{"id": "fixes", "label": "Fixes", "kind": "int",
                          "align": "right", "weight": 1.0}}
                    ],
                    "rows": [
                        {{"issue": 2, "title": "ZEBRA-ROW", "started_at": {old},
                          "machines": ["dellserver", "precision"], "fixes": 10}},
                        {{"issue": 10, "title": "ALPHA-ROW", "started_at": {recent},
                          "machines": [], "fixes": 2}}
                    ],
                    "notes": []
                }}"#,
            now = now,
            start = now - 30.0 * 86_400.0,
            old = now - 30.0 * 86_400.0,
            recent = now - 13.0 * 3600.0,
        )
    }

    /// #2369: a `decisions`-shaped result whose `options` column — unlike
    /// every other `kind: "list"` column in this file's fixtures — holds
    /// `{label, command_or_action, what_happens, recommended}` dicts, not
    /// scalar strings. Single-option row, deliberately short, so the
    /// combined "★ label: command" text fits the column regardless of
    /// exact width math.
    fn reports_result_json_options() -> String {
        let now = std::time::SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap_or_default()
            .as_secs_f64();
        format!(
            r#"{{
                    "report_id": "decisions",
                    "generated_at": {now},
                    "window": [{start}, {now}],
                    "columns": ["issue", "options"],
                    "column_meta": [
                        {{"id": "issue", "label": "Issue", "kind": "int",
                          "align": "right", "weight": 1.0}},
                        {{"id": "options", "label": "Options", "kind": "list",
                          "align": "left", "weight": 3.0}}
                    ],
                    "rows": [
                        {{"issue": 2360, "options": [
                            {{"label": "Recommended",
                              "command_or_action": "coord diagnose --reset",
                              "what_happens": "Runs the fix.",
                              "recommended": true}}
                        ]}}
                    ],
                    "notes": []
                }}"#,
            now = now,
            start = now - 3600.0,
        )
    }

    /// Open the Reports panel on a seeded result and render one frame.
    fn reports_driver(
        result_json: &str,
        w: u16,
        h: u16,
    ) -> quadraui::tui::testing::TuiDriver<impl quadraui::AppLogic> {
        use quadraui::tui::testing::driver_with_shell;
        let app = make_app_with_reports(
            BoardData::default(),
            reports_catalogue_json(),
            Some(result_json),
        );
        let mut driver = driver_with_shell(app, CoordApp::shell_config(), w, h);
        click_activity_icon(&mut driver, "▤");
        driver.render();
        driver
    }

    /// Longest run of consecutive ASCII digits anywhere in `screen` — the
    /// epoch detector. `1785780878.1551082` shows up as a 10-digit run;
    /// nothing a human-readable time renders (`13h ago`, `2026-07-05
    /// 12:00`, an issue number, a row count) comes close.
    fn longest_digit_run(screen: &str) -> usize {
        let mut best = 0;
        let mut run = 0;
        for ch in screen.chars() {
            if ch.is_ascii_digit() {
                run += 1;
                best = best.max(run);
            } else {
                run = 0;
            }
        }
        best
    }

    /// The screen row `y` (as returned by `find`) as a `Vec<char>`, for
    /// column-geometry assertions that need cell positions.
    fn screen_row(screen: &str, y: f32) -> Vec<char> {
        screen
            .lines()
            .nth(y as usize)
            .map(|l| l.chars().collect())
            .unwrap_or_default()
    }

    /// `true` when `row` carries a `YYYY-MM`-shaped run — the shape a
    /// calendar date renders as, and nothing a relative time or an epoch
    /// float ever produces. Only the prefix is matched, because a narrow
    /// column ellipsises the tail.
    fn looks_like_a_date(row: &str) -> bool {
        let cells: Vec<char> = row.chars().collect();
        cells.windows(8).any(|w| {
            w[0..4].iter().all(char::is_ascii_digit)
                && w[4] == '-'
                && w[5..7].iter().all(char::is_ascii_digit)
                && (w[7] == '-' || w[7] == '…')
        })
    }

    /// Rendered width of the column whose header starts at `(x, y)`:
    /// the distance to the `│` the TUI rasteriser paints at that column's
    /// right edge. `None` for the last column (which has no separator) or
    /// one scrolled off the viewport.
    fn reports_rendered_column_width(screen: &str, x: f32, y: f32) -> Option<usize> {
        let row = screen_row(screen, y);
        let start = x as usize;
        row.iter()
            .skip(start)
            .position(|c| *c == '│')
            .map(|offset| offset + 1)
    }

    #[test]
    fn reports_timestamp_column_renders_a_readable_time_not_an_epoch() {
        let driver = reports_driver(&reports_result_json_meta(), 140, 40);
        let screen = driver.screen();

        // `13h0m ago`, not `13h ago`: the relative string comes from the
        // existing `format_unix_time`/`fmt_dur` pair the Audit panel and the
        // window line already use. Reusing it — rather than hand-rolling a
        // prettier one here — is the point (#1762 forbids a third
        // time-formatting implementation in this binary).
        assert!(
            screen.contains("13h0m ago"),
            "#1762: a recent `timestamp` cell must render relatively:\n{screen}"
        );
        // The 30-day-old row is past the relative window, so it renders as
        // a calendar date. Asserted structurally (a `YYYY-MM`-shaped run)
        // rather than against a literal, since the fixture is clock-relative
        // — and only on the prefix, because a narrow column may ellipsise
        // the tail.
        let (_, zebra_y) = driver.find("ZEBRA-ROW").expect("old row must render");
        let zebra: String = screen_row(&screen, zebra_y).into_iter().collect();
        assert!(
            looks_like_a_date(&zebra),
            "#1762: an old `timestamp` cell must render as a date, not a \
                 relative string nor an epoch:\n{zebra}"
        );
        assert!(
            longest_digit_run(&screen) < 9,
            "#1762: no cell may render a raw epoch — longest digit run was \
                 {}:\n{screen}",
            longest_digit_run(&screen)
        );
    }

    #[test]
    fn reports_list_column_renders_joined_text_with_no_json_punctuation() {
        let driver = reports_driver(&reports_result_json_meta(), 140, 40);
        let screen = driver.screen();

        assert!(
            screen.contains("dellserver, precision"),
            "#1762: a `list` cell must render as joined text:\n{screen}"
        );
        // Assert on the row itself, not the whole screen — the shell
        // chrome legitimately draws brackets elsewhere.
        let (_, y) = driver
            .find("dellserver, precision")
            .expect("list cell must render");
        let row: String = screen_row(&screen, y).into_iter().collect();
        for junk in ['[', ']', '"'] {
            assert!(
                !row.contains(junk),
                "#1762: a rendered row must carry no JSON punctuation, found \
                     {junk:?} in:\n{row}"
            );
        }
    }

    #[test]
    fn reports_empty_list_renders_an_em_dash_not_empty_brackets() {
        let driver = reports_driver(&reports_result_json_meta(), 140, 40);
        let screen = driver.screen();
        assert!(
            !screen.contains("[]"),
            "#1762: an empty `list` cell must not render as `[]`:\n{screen}"
        );
        let (_, y) = driver.find("ALPHA-ROW").expect("empty-list row must render");
        let row: String = screen_row(&screen, y).into_iter().collect();
        assert!(
            row.contains('—'),
            "#1762: an empty `list` cell must render as an em dash — a blank \
                 reads as missing data:\n{row}"
        );
    }

    #[test]
    fn reports_list_column_of_option_dicts_renders_label_colon_command_not_json() {
        // #2369 review: `options` is a `kind: "list"` column whose items are
        // `{label, command_or_action, ...}` dicts, not the scalar strings
        // every other `list` column in this file holds. Before the fix,
        // `reports_plain_text`'s fallback (`other => other.to_string()`)
        // rendered each item as a compact JSON blob.
        let driver = reports_driver(&reports_result_json_options(), 140, 40);
        let screen = driver.screen();
        assert!(
            screen.contains("Recommended: coord diagnose --reset"),
            "#2369: an `options` cell must render as \"label: command\", not \
                 a JSON blob:\n{screen}"
        );
        let (_, y) = driver
            .find("Recommended: coord diagnose --reset")
            .expect("options cell must render");
        let row: String = screen_row(&screen, y).into_iter().collect();
        for junk in ['{', '}', '\'', '"'] {
            assert!(
                !row.contains(junk),
                "#2369: a rendered options row must carry no JSON/dict \
                     punctuation, found {junk:?} in:\n{row}"
            );
        }
        assert!(
            row.contains('★'),
            "#2369: the recommended option must be marked:\n{row}"
        );
    }

    #[test]
    fn reports_column_weight_sizes_the_heavier_column_wider() {
        let driver = reports_driver(&reports_result_json_meta(), 140, 40);
        let screen = driver.screen();

        // Left-aligned header text starts exactly at its column's left
        // edge, so consecutive header x-offsets *are* the resolved column
        // widths. Only left-aligned headers are used, and every coordinate
        // comes from `find`.
        let (title_x, header_y) = driver.find("Title").expect("Title header must render");
        let (started_x, _) = driver.find("Started").expect("Started header must render");
        let (machines_x, _) = driver.find("Machines").expect("Machines header must render");
        let title_w = started_x - title_x;
        let started_w = machines_x - started_x;

        assert!(
            title_w > started_w * 2.0,
            "#1762: `title` (weight 3.0) must be rendered far wider than \
                 `started_at` (weight 1.0) — got {title_w} vs {started_w} \
                 (header row {header_y}):\n{screen}"
        );
    }

    #[test]
    fn reports_result_without_column_meta_renders_exactly_as_before() {
        // The older-daemon guard: #1741's own fixture carries no
        // `column_meta` at all, and must render byte-for-byte as it did —
        // raw column ids as headers, raw values as cells, no em dashes, no
        // relative times invented out of an `int`.
        let driver = reports_driver(&reports_result_json(), 140, 40);
        let screen = driver.screen();
        for needle in [
            "issue",
            "outcome",
            "iterations",
            "claude-coordinator#1629",
            "claude-coordinator#1631",
        ] {
            assert!(
                screen.contains(needle),
                "#1762: a result with no `column_meta` must render {needle:?} \
                     exactly as before:\n{screen}"
            );
        }
        let (_, y) = driver.find("claude-coordinator#1629").expect("row must render");
        let row: String = screen_row(&screen, y).into_iter().collect();
        assert!(
            row.contains(" 1") && !row.contains('—'),
            "#1762: with no metadata the `iterations` cell stays a plain \
                 number and nothing becomes an em dash:\n{row}"
        );
    }

    #[test]
    fn reports_unknown_column_kind_falls_back_to_stringification() {
        // A daemon newer than this binary declaring a kind it has never
        // heard of must still render its data.
        let now = std::time::SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap_or_default()
            .as_secs_f64();
        let result = format!(
            r#"{{
                    "report_id": "issue-activity",
                    "generated_at": {now},
                    "window": [{start}, {now}],
                    "columns": ["thing"],
                    "column_meta": [
                        {{"id": "thing", "label": "Thing", "kind": "sparkline",
                          "align": "diagonal", "weight": 0.0}}
                    ],
                    "rows": [{{"thing": "PLAIN-VALUE"}}],
                    "notes": []
                }}"#,
            now = now,
            start = now - 3600.0,
        );
        let driver = reports_driver(&result, 140, 40);
        let screen = driver.screen();
        assert!(
            screen.contains("PLAIN-VALUE"),
            "#1762: an unrecognised `kind` must fall back to today's \
                 stringification, not blank the column:\n{screen}"
        );
        assert!(
            screen.contains("Thing"),
            "#1762: …and the column must still be titled from its label:\n{screen}"
        );
    }

    #[test]
    fn reports_header_click_cycles_sort_ascending_descending_off() {
        let mut driver = reports_driver(&reports_result_json_meta(), 140, 40);
        assert!(
            !driver.screen().contains('▲') && !driver.screen().contains('▼'),
            "#1762: an unsorted table must show no indicator:\n{}",
            driver.screen()
        );

        // Click a few cells INTO the header text, never at its first cell:
        // `DataTableLayout::hit_test` gives a ±3-cell divider grab zone
        // priority over the header, and a column's left edge *is* the
        // previous column's right edge. Successive clicks are 5 cells apart
        // so the backend's double-click detector (1.5-cell radius) never
        // folds two of them into a `DoubleClick` that never reaches the
        // click handler.
        //
        // `Machines` is the target because it is left-aligned and wide: a
        // right-aligned header shifts left by two cells the moment the
        // ▲ suffix is appended, which would move the target out from under
        // a fixed offset.
        let (x, y) = driver.find("Machines").expect("Machines header must render");
        driver.click(x + 5.0, y);
        driver.render();
        assert!(
            driver.screen().contains('▲'),
            "#1762: the first header click must sort ascending and render \
                 ▲:\n{}",
            driver.screen()
        );

        driver.click(x + 10.0, y);
        driver.render();
        assert!(
            driver.screen().contains('▼') && !driver.screen().contains('▲'),
            "#1762: the second click must flip to descending:\n{}",
            driver.screen()
        );

        driver.click(x + 15.0, y);
        driver.render();
        assert!(
            !driver.screen().contains('▲') && !driver.screen().contains('▼'),
            "#1762: the third click must clear the sort, so the daemon's own \
                 row order is reachable again:\n{}",
            driver.screen()
        );
    }

    #[test]
    fn reports_int_column_sorts_numerically_not_lexically() {
        let mut driver = reports_driver(&reports_result_json_meta(), 140, 40);
        // Daemon order: ZEBRA (fixes 10) then ALPHA (fixes 2). A *lexical*
        // ascending sort would leave that order untouched ("10" < "2"), so
        // "ALPHA moved above ZEBRA" can only mean numeric ordering.
        let (zebra_y, alpha_y) = reports_row_ys(&driver);
        assert!(zebra_y < alpha_y, "fixture must start in daemon order");

        let (x, y) = driver.find("Fixes").expect("Fixes header must render");
        driver.click(x + 4.0, y);
        driver.render();

        let (zebra_y, alpha_y) = reports_row_ys(&driver);
        assert!(
            alpha_y < zebra_y,
            "#1762: ascending an `int` column must order 2 before 10 \
                 (numeric, not lexical) — got ALPHA at {alpha_y}, ZEBRA at \
                 {zebra_y}:\n{}",
            driver.screen()
        );
    }

    #[test]
    fn reports_timestamp_column_sorts_by_instant_not_rendered_string() {
        let mut driver = reports_driver(&reports_result_json_meta(), 140, 40);
        // ZEBRA is 30 days old, ALPHA is 13h old. Ascending *by instant*
        // puts ZEBRA first. Ascending by the rendered string would put
        // ALPHA first ("13h ago" sorts before "20xx-…"), so the two answers
        // are distinguishable.
        let (x, y) = driver.find("Started").expect("Started header must render");
        driver.click(x + 4.0, y);
        driver.render();

        let (zebra_y, alpha_y) = reports_row_ys(&driver);
        assert!(
            zebra_y < alpha_y,
            "#1762: ascending a `timestamp` column must order by instant, \
                 not by the formatted string — got ZEBRA at {zebra_y}, ALPHA \
                 at {alpha_y}:\n{}",
            driver.screen()
        );

        // …and descending flips it, proving the direction is real and not
        // an artefact of the daemon's own ordering. `Started` is
        // left-aligned so its header x does not move when ▲ is appended;
        // the second click is 3 cells clear of the first (double-click
        // radius is 1.5) and still inside the column.
        driver.click(x + 7.0, y);
        driver.render();
        let (zebra_y, alpha_y) = reports_row_ys(&driver);
        assert!(
            alpha_y < zebra_y,
            "#1762: descending must put the most recent row first:\n{}",
            driver.screen()
        );
    }

    /// y-offsets of the two fixture rows, by their unique title cells.
    fn reports_row_ys<A: quadraui::AppLogic>(
        driver: &quadraui::tui::testing::TuiDriver<A>,
    ) -> (f32, f32) {
        let (_, zebra) = driver
            .find("ZEBRA-ROW")
            .unwrap_or_else(|| panic!("ZEBRA row must render:\n{}", driver.screen()));
        let (_, alpha) = driver
            .find("ALPHA-ROW")
            .unwrap_or_else(|| panic!("ALPHA row must render:\n{}", driver.screen()));
        (zebra, alpha)
    }

    #[test]
    fn reports_rerun_clears_the_active_sort() {
        // Model-level, deliberately: a run in flight clears the result, so
        // there is no table left on screen whose ▲/▼ a driver test could
        // assert the absence of. What matters is that the *next* result
        // cannot inherit a sort pinned to a column index that may mean
        // something else — and that is state, not pixels.
        let mut app = make_app_with_reports(
            BoardData::default(),
            reports_catalogue_json(),
            Some(&reports_result_json_meta()),
        );
        assert!(app.reports_sort_by_column(4), "sorting column 4 must apply");
        assert_eq!(app.reports_sort, Some((4, SortDirection::Ascending)));

        // No board service resolves under `cfg(test)`, so this arms a run
        // that never completes — exactly what the `r` key does.
        app.reports_rerun_selected();
        assert!(
            app.reports_sort.is_none(),
            "#1762: a re-run must clear the active sort — sort is view state \
                 over one result set, and the next set may not even have \
                 that column"
        );
    }

    #[test]
    fn reports_sort_ignores_a_column_index_the_result_does_not_have() {
        let mut app = make_app_with_reports(
            BoardData::default(),
            reports_catalogue_json(),
            Some(&reports_result_json_meta()),
        );
        assert!(
            !app.reports_sort_by_column(99),
            "#1762: a header click past the last column must be a no-op, not \
                 a panic or a phantom sort"
        );
        assert!(app.reports_sort.is_none());
    }

    // ── #1853: result-table column resize ────────────────────────────────
    //
    // One table serves every report, so these land resize for the whole
    // catalogue at once. The two things that are *not* a copy of Audit's
    // #1094 resize get a test each: overrides must not survive onto a
    // different column set (`..._must_not_leak_across_reports`), and a
    // resize must not disturb #1762's sort routing, which is what the
    // pinned `h_scroll: 0.0` exists to protect
    // (`..._still_sorts_the_column_under_the_cursor`).
    //
    // Every coordinate comes from `find`. Left-aligned header text starts
    // exactly at its column's left edge (the same property #1762's
    // weight test relies on), so a left-aligned header's x *is* its
    // column's left edge — and therefore also the divider between it and
    // the column before it, which is what these drags grab.

    /// A second five-column result from a *different* report, with column
    /// ids and labels that share nothing with `reports_result_json_meta`'s.
    ///
    /// Five columns on purpose: the leak test has to be one a length check
    /// could not pass. Shaped after the real `drive-queue-status`, which is
    /// the report that motivated #1853 (a wide TITLE and a wide LAST REASON
    /// competing for the same row).
    fn reports_result_json_other_five() -> String {
        let now = std::time::SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap_or_default()
            .as_secs_f64();
        format!(
            r#"{{
                    "report_id": "drive-queue-status",
                    "generated_at": {now},
                    "window": [{start}, {now}],
                    "columns": ["item", "doc", "state", "tries", "reason"],
                    "column_meta": [
                        {{"id": "item", "label": "Item", "kind": "int",
                          "align": "right", "weight": 1.0}},
                        {{"id": "doc", "label": "Doc", "kind": "text",
                          "align": "left", "weight": 3.0}},
                        {{"id": "state", "label": "State", "kind": "text",
                          "align": "left", "weight": 1.0}},
                        {{"id": "tries", "label": "Tries", "kind": "int",
                          "align": "left", "weight": 2.5}},
                        {{"id": "reason", "label": "Reason", "kind": "text",
                          "align": "left", "weight": 1.0}}
                    ],
                    "rows": [
                        {{"item": 1, "doc": "QUEUE-DOC-ONE", "state": "queued",
                          "tries": 0, "reason": "waiting"}}
                    ],
                    "notes": []
                }}"#,
            now = now,
            start = now - 3600.0,
        )
    }

    /// A *four*-column result — the "works for every report, not one"
    /// half of the acceptance: nothing about resize may be sized to
    /// `reports_result_json_meta`'s five.
    fn reports_result_json_four() -> String {
        let now = std::time::SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap_or_default()
            .as_secs_f64();
        format!(
            r#"{{
                    "report_id": "usage",
                    "generated_at": {now},
                    "window": [{start}, {now}],
                    "columns": ["model", "calls", "tokens", "spend"],
                    "column_meta": [
                        {{"id": "model", "label": "Model", "kind": "text",
                          "align": "left", "weight": 2.0}},
                        {{"id": "calls", "label": "Calls", "kind": "text",
                          "align": "left", "weight": 2.0}},
                        {{"id": "tokens", "label": "Tokens", "kind": "text",
                          "align": "left", "weight": 2.0}},
                        {{"id": "spend", "label": "Spend", "kind": "money",
                          "align": "right", "weight": 1.0}}
                    ],
                    "rows": [
                        {{"model": "opus", "calls": "12", "tokens": "900",
                          "spend": 1.5}}
                    ],
                    "notes": []
                }}"#,
            now = now,
            start = now - 3600.0,
        )
    }

    /// Terminal size for the resize tests. Wider than the 140 the #1762
    /// tests use because these ones assert on header *positions* after
    /// narrowing a column: at 140 the main panel gives an eleven-weight
    /// table about ten cells per unit weight, so a six-cell drag squeezes
    /// `Started` down to `Star` and `find` — correctly — stops seeing it.
    /// The extra width buys margin for the drag, and changes nothing about
    /// what is under test.
    const REPORTS_RESIZE_COLS: u16 = 200;
    const REPORTS_RESIZE_ROWS: u16 = 40;

    /// The x-offset of each label's rendered header cell, in the order
    /// given. Panics (with the screen) if any is missing, so a truncated
    /// header shows up as a named failure rather than a silent `None`.
    fn reports_header_xs<A: quadraui::AppLogic>(
        driver: &quadraui::tui::testing::TuiDriver<A>,
        labels: &[&str],
    ) -> Vec<f32> {
        labels
            .iter()
            .map(|l| {
                driver
                    .find(l)
                    .unwrap_or_else(|| {
                        panic!("#1853: header {l:?} must render:\n{}", driver.screen())
                    })
                    .0
            })
            .collect()
    }

    /// Drag the divider on the LEFT edge of `right_label`'s column by `dx`
    /// cells, then repaint. `right_label` must be a left-aligned header, so
    /// its x is that column's left edge — which is exactly the boundary
    /// `DataTableLayout::hit_test` reports as `HeaderDivider`.
    fn reports_drag_divider<A: quadraui::AppLogic>(
        driver: &mut quadraui::tui::testing::TuiDriver<A>,
        right_label: &str,
        dx: f32,
    ) -> f32 {
        let (x, y) = driver.find(right_label).unwrap_or_else(|| {
            panic!(
                "#1853: header {right_label:?} must render before dragging \
                     its divider:\n{}",
                driver.screen()
            )
        });
        driver.mouse_down(x, y);
        driver.mouse_move(x + dx, y);
        driver.mouse_up(x + dx, y);
        driver.render();
        x
    }

    /// Dispatch an event that does nothing but let the app do its periodic
    /// work — the tick that drains a completed report run. A *button-less*
    /// move, deliberately: `mouse_move` holds the left button down, which
    /// would look like the continuation of a resize drag.
    fn reports_idle_tick<A: quadraui::AppLogic>(
        driver: &mut quadraui::tui::testing::TuiDriver<A>,
    ) {
        driver.dispatch(quadraui::UiEvent::MouseMoved {
            position: quadraui::Point::new(0.0, 0.0),
            buttons: quadraui::ButtonMask::default(),
        });
        driver.render();
    }

    #[test]
    fn reports_divider_drag_resizes_only_its_own_pair() {
        let mut driver = reports_driver(
            &reports_result_json_meta(),
            REPORTS_RESIZE_COLS,
            REPORTS_RESIZE_ROWS,
        );
        let before = reports_header_xs(&driver, &["Title", "Started", "Machines"]);

        // The divider between `Title` and `Started`, dragged 8 cells right.
        reports_drag_divider(&mut driver, "Started", 8.0);
        let after = reports_header_xs(&driver, &["Title", "Started", "Machines"]);

        assert_eq!(
            before[0], after[0],
            "#1853: dragging a divider must not move the left column's own \
                 left edge — that edge is fixed by the columns before it:\n{}",
            driver.screen()
        );
        assert!(
            (after[1] - (before[1] + 8.0)).abs() <= 1.0,
            "#1853: dragging the Title|Started divider 8 cells right must \
                 widen Title by ~8 — `Started` moved from {} to {}:\n{}",
            before[1],
            after[1],
            driver.screen()
        );
        // The pair-only invariant, and the reason this feature does not
        // reopen the pinned `h_scroll`: `drag_divider` holds the dragged
        // pair's combined width constant, so every column after the pair —
        // and therefore the table's total content width — is untouched. A
        // resize can never newly force horizontal scrolling.
        assert_eq!(
            before[2], after[2],
            "#1853: a divider drag must move width between its own two \
                 columns only — `Machines` (two columns right of the drag) \
                 moved from {} to {}:\n{}",
            before[2],
            after[2],
            driver.screen()
        );
    }

    #[test]
    fn reports_divider_drag_survives_until_the_panel_changes_report() {
        // "the change persists while the panel stays open": the width must
        // still be there after unrelated repaints and an unrelated click.
        let mut driver = reports_driver(
            &reports_result_json_meta(),
            REPORTS_RESIZE_COLS,
            REPORTS_RESIZE_ROWS,
        );
        let before = reports_header_xs(&driver, &["Started"])[0];
        reports_drag_divider(&mut driver, "Started", 6.0);
        let dragged = reports_header_xs(&driver, &["Started"])[0];
        assert!(dragged > before, "the drag must have widened Title");

        for _ in 0..3 {
            reports_idle_tick(&mut driver);
        }
        assert_eq!(
            dragged,
            reports_header_xs(&driver, &["Started"])[0],
            "#1853: a dragged width must survive repaints for as long as the \
                 panel stays on the same result:\n{}",
            driver.screen()
        );
    }

    #[test]
    fn reports_divider_drag_works_on_a_report_with_a_different_column_count() {
        // The catalogue-wide half of the acceptance: the four-column report
        // resizes with the same code, no per-report anything.
        let mut driver = reports_driver(
            &reports_result_json_four(),
            REPORTS_RESIZE_COLS,
            REPORTS_RESIZE_ROWS,
        );
        let before = reports_header_xs(&driver, &["Model", "Calls", "Tokens"]);
        reports_drag_divider(&mut driver, "Calls", 7.0);
        let after = reports_header_xs(&driver, &["Model", "Calls", "Tokens"]);

        assert!(
            (after[1] - (before[1] + 7.0)).abs() <= 1.0,
            "#1853: resize must work on a four-column report too — `Calls` \
                 moved from {} to {}:\n{}",
            before[1],
            after[1],
            driver.screen()
        );
        assert_eq!(
            before[2], after[2],
            "#1853: …and still only move its own pair:\n{}",
            driver.screen()
        );
    }

    #[test]
    fn reports_column_widths_must_not_leak_across_reports() {
        // The dynamic-column-set hazard, asserted with two reports that have
        // the **same** column count — so a length check alone cannot pass
        // this. Widths dragged against `issue-activity`'s five columns must
        // not re-apply to `drive-queue-status`'s five, where index 1 is a
        // different column entirely.
        let other = reports_result_json_other_five();

        // Control: the same second report, in a session where nothing was
        // ever dragged. Its header offsets are the `column_meta` widths.
        let control = reports_driver(&other, REPORTS_RESIZE_COLS, REPORTS_RESIZE_ROWS);
        let expected = reports_header_xs(&control, &["Doc", "State", "Tries", "Reason"]);

        let (app, pending) = make_app_with_reports_awaiting_run(
            BoardData::default(),
            reports_catalogue_json(),
            &reports_result_json_meta(),
        );
        let mut driver = quadraui::tui::testing::driver_with_shell(
            app,
            CoordApp::shell_config(),
            REPORTS_RESIZE_COLS,
            REPORTS_RESIZE_ROWS,
        );
        click_activity_icon(&mut driver, "▤");
        driver.render();

        // Drag hard enough that inheriting the override would be obvious —
        // column 1 of `issue-activity` ends up far from where column 1 of
        // `drive-queue-status` declares itself.
        let started_before = reports_header_xs(&driver, &["Started"])[0];
        reports_drag_divider(&mut driver, "Started", 8.0);
        assert!(
            reports_header_xs(&driver, &["Started"])[0] > started_before,
            "the drag must have visibly moved something first:\n{}",
            driver.screen()
        );

        // The report on screen is replaced by a completed run of a
        // *different* report — the real path, drained by the app's own
        // periodic work on the next event.
        assert!(
            pending.deliver(&other),
            "#1853 fixture: the queued result must parse and send"
        );
        reports_idle_tick(&mut driver);

        let actual = reports_header_xs(&driver, &["Doc", "State", "Tries", "Reason"]);
        assert_eq!(
            expected,
            actual,
            "#1853: switching to a different report with the SAME column \
                 count must discard the stale overrides and render at the new \
                 report's declared `column_meta` widths — expected {expected:?}, \
                 got {actual:?}:\n{}",
            driver.screen()
        );
    }

    #[test]
    fn reports_header_click_after_a_resize_still_sorts_the_column_under_it() {
        // The regression the pinned `h_scroll: 0.0` exists to prevent, now
        // that resize is the thing that moves headers around: a sort click
        // must land on the column the operator actually clicked, not on
        // whatever used to be there.
        let mut driver = reports_driver(
            &reports_result_json_meta(),
            REPORTS_RESIZE_COLS,
            REPORTS_RESIZE_ROWS,
        );
        reports_drag_divider(&mut driver, "Started", 12.0);

        let (machines_x, header_y) = driver
            .find("Machines")
            .unwrap_or_else(|| panic!("Machines header must render:\n{}", driver.screen()));
        // Well clear of the ±3-cell divider grab zone at either edge, and
        // far from the drag's release point so the backend's double-click
        // detector can't fold the two together.
        driver.click(machines_x + 5.0, header_y);
        driver.render();

        let screen = driver.screen();
        let row: String = screen_row(&screen, header_y).into_iter().collect();
        let cells: Vec<char> = row.chars().collect();
        let at_machines: String = cells
            .iter()
            .skip(machines_x as usize)
            .take("Machines ▲".chars().count())
            .collect();
        assert_eq!(
            at_machines, "Machines ▲",
            "#1853/#1762: after a resize, a header click must sort the column \
                 under the cursor — the ▲ must be on `Machines`, whose column \
                 starts at x={machines_x}. Header row was:\n{row}\n{screen}"
        );
        assert_eq!(
            row.matches('▲').count(),
            1,
            "#1853: exactly one column may carry the ascending indicator:\n{row}"
        );
    }

    #[test]
    fn reports_column_overrides_are_session_only() {
        // Session-only, matching Audit (#1094) and the panel's own sort:
        // persisting widths is a separate decision and explicitly not part
        // of #1853.
        //
        // Asserted as "a freshly-built app has no overrides". That is the
        // whole observable consequence of not persisting: `Settings` has no
        // width field to write, so the only load path a restored width could
        // arrive through is the one that doesn't exist. The drag's single
        // store is `CoordApp::reports_column_overrides` — an in-memory field
        // — and nothing in `settings.rs` reads or writes it.
        let mut app = make_app_with_reports(
            BoardData::default(),
            reports_catalogue_json(),
            Some(&reports_result_json_meta()),
        );
        assert!(
            app.reports_column_overrides.is_none(),
            "#1853: a freshly-built app must have no column overrides — there \
                 is no settings field for them to be loaded from"
        );
        // …and with no table painted yet there is nothing a stray drag could
        // resize, so a spurious `MouseMoved` cannot invent one.
        app.reports_resize_col = Some(0);
        assert!(
            !app.reports_update_resize_drag(Point::new(40.0, 3.0)),
            "#1853: a resize drag against a table that was never painted must \
                 be a no-op"
        );
        assert!(app.reports_column_overrides.is_none());
    }

    // ── #1763: the `usage` report + `ReportResult.totals` ────────────────────
    //
    // The Usage ActivityBar panel was a Rust port of `coord/usage_rollup.py`
    // carrying a compiled-in pricing snapshot, so an operator's `pricing:`
    // override moved `coord usage` and left the panel showing different
    // numbers. #1763 deleted it and made the rollup a server-side report.
    // What is left to test client-side is exactly what stayed client-side:
    // that a *generic* renderer shows the new report without any
    // report-specific Rust, that the retired panel id still lands somewhere
    // real, and that `totals` is additive.

    /// The real `usage` catalogue entry, as `GET /report` serves it.
    fn usage_catalogue_json() -> &'static str {
        r#"{
            "reports": [
                {
                    "id": "usage",
                    "title": "Usage",
                    "description": "Cost and token spend for a time window.",
                    "params": [
                        {"id": "window", "label": "Time window", "kind": "choice",
                         "choices": ["today", "week", "month", "7d", "30d"],
                         "default": "today", "help": "", "free_form": false},
                        {"id": "group_by", "label": "Group by", "kind": "choice",
                         "choices": ["issue", "repo"], "default": "issue",
                         "help": "", "free_form": false},
                        {"id": "repo", "label": "Repo", "kind": "text",
                         "choices": [], "default": "", "help": "", "free_form": false}
                    ]
                }
            ]
        }"#
    }

    /// A `usage` run: two rows, `money` columns, and a `totals` footer.
    fn usage_result_json() -> String {
        let now = std::time::SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap_or_default()
            .as_secs_f64();
        format!(
            r#"{{
                "report_id": "usage",
                "generated_at": {now},
                "window": [{start}, {now}],
                "columns": ["issue", "repo", "title", "legs", "cost_captured",
                            "cost_est", "cost_total"],
                "column_meta": [
                    {{"id": "issue", "label": "Issue", "kind": "int",
                      "align": "right", "weight": 0.8}},
                    {{"id": "repo", "label": "Repo", "kind": "text",
                      "align": "left", "weight": 1.5}},
                    {{"id": "title", "label": "Title", "kind": "text",
                      "align": "left", "weight": 4.0}},
                    {{"id": "legs", "label": "Legs", "kind": "int",
                      "align": "right", "weight": 0.6}},
                    {{"id": "cost_captured", "label": "Cost $", "kind": "money",
                      "align": "right", "weight": 1.0}},
                    {{"id": "cost_est", "label": "Est ~$", "kind": "money",
                      "align": "right", "weight": 1.0}},
                    {{"id": "cost_total", "label": "Total $", "kind": "money",
                      "align": "right", "weight": 1.0}}
                ],
                "rows": [
                    {{"issue": 7, "repo": "api", "title": "BIGGER-SPEND", "legs": 2,
                      "cost_captured": 1.5, "cost_est": 30.0,
                      "cost_total": 31.500000000000004}},
                    {{"issue": 9, "repo": "web", "title": "SMALLER-SPEND", "legs": 1,
                      "cost_captured": 0.0, "cost_est": 2.25, "cost_total": 2.25}}
                ],
                "notes": [],
                "totals": {{"legs": 3, "cost_captured": 1.5, "cost_est": 32.25,
                            "cost_total": 33.75}}
            }}"#,
            now = now,
            start = now - 86_400.0,
        )
    }

    /// Open Reports on a seeded `usage` catalogue + result, one frame drawn.
    fn usage_report_driver(
        result_json: Option<&str>,
        w: u16,
        h: u16,
    ) -> quadraui::tui::testing::TuiDriver<impl quadraui::AppLogic> {
        use quadraui::tui::testing::driver_with_shell;
        let app = make_app_with_reports(
            BoardData::default(),
            usage_catalogue_json(),
            result_json,
        );
        let mut driver = driver_with_shell(app, CoordApp::shell_config(), w, h);
        click_activity_icon(&mut driver, "▤");
        driver.render();
        driver
    }

