    #[test]
    fn money_column_sorts_numerically_not_lexically() {
        // "$2.25" sorts before "$31.50" as text and after it as a number.
        // Sorting reads the raw JSON, so the numeric answer is the one the
        // header click must produce.
        let mut driver = usage_report_driver(Some(&usage_result_json()), 140, 40);
        let (x, y) = driver
            .find("Total $")
            .expect("the money column header must render");
        driver.click(x, y);
        driver.render();
        let screen = driver.screen();
        let big = screen.find("BIGGER-SPEND").expect("row 7 must render");
        let small = screen.find("SMALLER-SPEND").expect("row 9 must render");
        assert!(
            big > small,
            "#1763: the first header click sorts ascending, so the $2.25 row \
             must precede the $31.50 one:\n{screen}"
        );
    }

    #[test]
    fn reports_narrow_terminal_honours_the_min_width_floor() {
        // At 140 columns everything fits and every header renders in full.
        let wide = reports_driver(&reports_result_json_meta(), 140, 40).screen();
        assert!(
            wide.contains("Started") && wide.contains("Machines"),
            "#1762: at a wide terminal every column header must render:\n{wide}"
        );

        // At 80 columns the main panel is far narrower than the table's
        // floor. Without the floor all five columns would still be on
        // screen, each squeezed to a handful of cells; with it, the columns
        // keep the widths their weights earned and `DataTable`'s horizontal
        // scrollbar takes over — the visible ones stay legible and the rest
        // are scrolled to, not mangled.
        let narrow_driver = reports_driver(&reports_result_json_meta(), 80, 40);
        let narrow = narrow_driver.screen();
        let (tx, ty) = narrow_driver
            .find("Title")
            .expect("Title header must still render at 80 columns");
        let narrow_title_w = reports_rendered_column_width(&narrow, tx, ty)
            .expect("Title column must still be delimited by a separator");
        // Squeezed into the ~42-cell main panel, `title`'s 3-of-8.5 weight
        // share would be ~15 cells. The floor gives it ~27.
        assert!(
            narrow_title_w >= 20,
            "#1762: at 80 columns the table must honour its \
                 `min_total_width` floor rather than squeezing every column \
                 below legibility — `title` rendered {narrow_title_w} cells \
                 wide:\n{narrow}"
        );
    }

    /// #1911 "Second constraint: width" — the issue asked to verify
    /// parameter forms stay usable at the sidebar's default width before
    /// committing to this layout, and to say so rather than silently
    /// truncate a field into ambiguity if it doesn't fit.
    ///
    /// At the shell's default sidebar width (35 cols, `shell_config()`),
    /// every field here renders. `usage`'s three params (`window`: 5
    /// choices, `group_by`: 2 choices, `repo`: text) are the widest
    /// parameter set in the production catalogue — wider than
    /// `issue-activity`'s `since`/`until`/`repo`, which fit with room to
    /// spare.
    ///
    /// One known imperfection, deliberately NOT worked around here:
    /// `window`'s `SegmentedControl` (`Time window[today|week|month|7d|
    /// 30d]`, ~36 cells including its label) is ~1 cell wider than the
    /// 35-col default, and quadraui's TUI `SegmentedControl` painter
    /// (`tui/form.rs`) hard-truncates at the viewport edge with no
    /// ellipsis/wrap — so the LAST option's closing bracket gets clipped
    /// (`...7d|30` — the `d]` is lost). Every option's own text still
    /// starts inside the visible width (this test's assertions below all
    /// pass), so the effect is "one option's tail is cut", not
    /// label-ambiguity across the whole control, and widening the sidebar
    /// (up to quadraui's configured max of 55) removes it entirely. Fixing
    /// the painter to ellipsis/wrap instead of hard-truncating is a
    /// quadraui change — out of this issue's scope (see CLAUDE.md's
    /// path-dep rules for `~/src/quadraui`); noted here rather than
    /// silently accepted.
    #[test]
    fn reports_widest_catalogue_params_stay_usable_at_default_sidebar_width() {
        use quadraui::tui::testing::driver_with_shell;
        let catalogue = r#"{"reports":[{"id":"usage","title":"Usage","description":"d","params":[
            {"id":"window","label":"Time window","kind":"choice","choices":["today","week","month","7d","30d"],"default":"today","help":""},
            {"id":"group_by","label":"Group by","kind":"choice","choices":["issue","repo"],"default":"issue","help":""},
            {"id":"repo","label":"Repo","kind":"text","choices":[],"default":"","help":"Empty means all repos"}
        ]}]}"#;
        let app = make_app_with_reports(BoardData::default(), catalogue, None);
        let mut driver = driver_with_shell(app, CoordApp::shell_config(), 140, 40);
        click_activity_icon(&mut driver, "▤");
        driver.render();

        let screen = driver.screen();
        for needle in [
            "Time window",
            "today",
            "week",
            "month",
            "Group by",
            "issue",
            "Repo",
            "Run",
        ] {
            assert!(
                screen.contains(needle),
                "#1911: {needle:?} must stay readable at the sidebar's \
                     default width:\n{screen}"
            );
        }
    }

    // ── #1765: Export a report to CSV ────────────────────────────────────
    //
    // The Export affordance is the section header's `HeaderAction`
    // (quadraui `SectionHeader.actions`), which renders dimmed and
    // hit-test-inert when disabled. Every assertion below reaches the button
    // through `find()` on the rendered grid — never a hardcoded coordinate —
    // and distinguishes enabled from disabled *behaviourally*, since a
    // dimmed glyph and a lit one are the same character on a text screen:
    // a disabled action falls through to the title area (collapsing the
    // section), an enabled one does not.

    /// The Export glyph as the TUI header draws it (`Icon::fallback`).
    const EXPORT_GLYPH: &str = "⤓";

    #[test]
    fn reports_export_action_renders_in_every_section_header() {
        let driver = reports_driver(&reports_result_json(), 140, 40);
        let screen = driver.screen();
        let (x, y) = driver.find(EXPORT_GLYPH).unwrap_or_else(|| {
            panic!("#1765: the Export action must render in the section header:\n{screen}")
        });
        let (_, header_y) = driver
            .find("▾ Issue Activity")
            .expect("section header must render");
        assert_eq!(
            y, header_y,
            "#1765: Export belongs in the section header row, not the body:\n{screen}"
        );
        let (title_x, _) = driver.find("▾ Issue Activity").unwrap();
        assert!(
            x > title_x,
            "#1765: the action is right-aligned, so it must sit right of the \
             title:\n{screen}"
        );
    }

    #[test]
    fn reports_export_is_inert_before_the_first_run() {
        use quadraui::tui::testing::driver_with_shell;

        // No result: the action is disabled, quadraui reserves no hit region
        // for it, and the click falls through to the title area — which
        // toggles the section. That fall-through IS the observable proof
        // that the button is inert.
        let app = make_app_with_reports(BoardData::default(), reports_catalogue_json(), None);
        let mut driver = driver_with_shell(app, CoordApp::shell_config(), 140, 40);
        click_activity_icon(&mut driver, "▤");
        driver.render();

        let before = driver.screen();
        assert!(
            before.contains("▾ Issue Activity"),
            "section must start expanded:\n{before}"
        );
        let (x, y) = driver
            .find(EXPORT_GLYPH)
            .unwrap_or_else(|| panic!("#1765: a disabled Export still renders:\n{before}"));
        driver.click(x, y);
        driver.render();

        let after = driver.screen();
        assert!(
            after.contains("▸ Issue Activity"),
            "#1765: clicking a *disabled* Export must fall through to the \
             title area (collapsing the section), not export:\n{after}"
        );
        assert!(
            !after.contains("Exporting") && !after.contains("Export failed"),
            "#1765: an unrun report must not report an export outcome:\n{after}"
        );
    }

    #[test]
    fn reports_export_is_live_after_a_run_and_does_not_collapse_the_section() {
        let mut driver = reports_driver(&reports_result_json(), 140, 40);
        let (x, y) = driver
            .find(EXPORT_GLYPH)
            .unwrap_or_else(|| panic!("Export must render:\n{}", driver.screen()));
        driver.click(x, y);
        driver.render();

        let after = driver.screen();
        assert!(
            after.contains("▾ Issue Activity"),
            "#1765: an *enabled* Export owns its hit region — the click must \
             not fall through and collapse the section:\n{after}"
        );
        // The click ran the whole request path in one turn: pending → save
        // dialog → destination → export. Whichever terminal state it
        // reached, it must have said so in the notes area — a silent write
        // is indistinguishable from a silent failure.
        assert!(
            after.contains("Export"),
            "#1765: an Export click must leave a visible outcome in the notes \
             area:\n{after}"
        );
    }

