    #[test]
    fn reports_export_destination_is_cancelled_when_a_real_dialog_says_no() {
        // A backend that can actually ask (GTK/macOS) returning `None` means
        // the operator cancelled: nothing written, and — per the acceptance
        // criteria — nothing reported as an error.
        assert_eq!(
            CoordApp::reports_export_destination(None, "gtk", "suggested.csv"),
            crate::app::reports::ReportExportDest::Cancelled,
        );
    }

    #[test]
    fn reports_export_destination_falls_back_to_home_on_the_tui_backend() {
        // quadraui's TUI `show_file_save_dialog` is a documented no-op that
        // always returns `None`. Treating that as "cancelled" would make
        // Export permanently dead in the one binary this panel ships in, so
        // the TUI writes the suggested name into $HOME instead — and the
        // caller reports the full path.
        let dest = CoordApp::reports_export_destination(None, "tui", "issue-activity-1.csv");
        match dest {
            crate::app::reports::ReportExportDest::Path(p) => {
                assert_eq!(p.file_name().unwrap(), "issue-activity-1.csv");
                assert!(p.is_absolute(), "the reported path must be unambiguous");
            }
            crate::app::reports::ReportExportDest::Cancelled => {
                panic!("#1765: the TUI backend cannot ask, so it must not report a cancel")
            }
        }
    }

    #[test]
    fn reports_suggested_export_name_is_stamped_from_the_result_not_the_clock() {
        let result: crate::app::types::ReportResult = serde_json::from_str(
            r#"{"report_id": "issue-activity", "generated_at": 0,
                 "window": [1785694800.0, 1785780900.0],
                 "columns": [], "rows": [], "notes": []}"#,
        )
        .expect("fixture must parse");
        let name = CoordApp::reports_suggested_export_name(&result);
        // 1785780900 = 2026-08-03 18:15:00Z (cross-checked against Python's
        // `datetime.fromtimestamp(..., utc).strftime("%Y%m%d-%H%M")`, which
        // is what `coord.reports.csv_filename` uses). The stamp is the
        // *window end*,
        // so the same result always suggests the same filename — and it
        // matches the `Content-Disposition` name the daemon offers.
        assert_eq!(name, "issue-activity-20260803-1815.csv");
    }

    /// End-to-end: the export goes back to the **daemon** for its CSV
    /// (`?format=csv`) and writes those bytes verbatim.
    ///
    /// That round trip is the entire point of #1765 — the panel already
    /// holds the `ReportResult`, but its cells are display strings rendered
    /// through `column_meta` (`13h ago`, `dellserver, precision`), so a
    /// client-side CSV would export the formatting instead of the data.
    #[test]
    fn reports_export_writes_the_daemons_csv_verbatim() {
        const CSV: &str = "# report: issue-activity\n# rows: 1\nRepo,Issue\napi,1631\n";

        let mock = MockBoardService::start(CSV);
        let _guard = set_test_board_service(mock.url(), None);

        let dir = std::env::temp_dir().join(format!(
            "coord-tui-export-{}-{:?}",
            std::process::id(),
            std::thread::current().id()
        ));
        std::fs::create_dir_all(&dir).expect("temp dir");
        let dest = dir.join("out.csv");

        let mut app = make_app_with_reports(
            BoardData::default(),
            reports_catalogue_json(),
            Some(&reports_result_json()),
        );
        app.reports_start_export("issue-activity", dest.clone());

        let rx = app
            .reports_export_rx
            .take()
            .expect("an export must be in flight");
        match rx
            .recv_timeout(std::time::Duration::from_secs(10))
            .expect("the export must deliver an outcome before the timeout")
        {
            ReportExportOutcome::Written { path, bytes } => {
                assert_eq!(path, dest);
                assert_eq!(bytes, CSV.len());
            }
            ReportExportOutcome::NoBoardService => {
                panic!("#1765: the mock board service must be reached")
            }
            ReportExportOutcome::Failed(reason) => panic!("#1765: export failed: {reason}"),
        }

        let written = std::fs::read_to_string(&dest).expect("the CSV must land on disk");
        assert_eq!(
            written, CSV,
            "#1765: the daemon's bytes are written verbatim — no client-side \
             re-formatting"
        );

        let requests = mock.requests();
        assert!(
            requests.iter().any(|r| r.contains("format=csv")),
            "#1765: the export must ask the daemon for CSV rather than \
             serialising the panel's display strings: {requests:?}"
        );
        assert!(
            requests.iter().any(|r| r.contains("/report/issue-activity")),
            "#1765: ...from that report's own route: {requests:?}"
        );
        // The form's parameters ride along, so the exported window is the
        // one the panel is showing.
        assert!(
            requests.iter().any(|r| r.contains("since=24h")),
            "#1765: the catalogue's parameters must be sent with the export: \
             {requests:?}"
        );

        let _ = std::fs::remove_file(&dest);
        let _ = std::fs::remove_dir(&dir);
    }

    #[test]
    fn reports_export_with_no_board_service_reports_a_visible_failure() {
        // A failed write/fetch must surface, never fail silently. In the
        // test binary `resolve_board_service` is absent by construction, so
        // this is the "the daemon isn't there" path.
        let mut app = make_app_with_reports(
            BoardData::default(),
            reports_catalogue_json(),
            Some(&reports_result_json()),
        );
        app.reports_start_export("issue-activity", std::env::temp_dir().join("never.csv"));
        let rx = app.reports_export_rx.take().expect("rx must be armed");
        assert!(matches!(
            rx.recv_timeout(std::time::Duration::from_secs(5)),
            Ok(ReportExportOutcome::NoBoardService)
        ));
        assert!(
            !std::env::temp_dir().join("never.csv").exists(),
            "#1765: a failed export must not leave a file behind"
        );
    }

    #[test]
    fn reports_export_request_is_ignored_for_a_report_with_no_result() {
        // Defence in depth behind the disabled action: even if a click did
        // reach the handler, a report with no result arms nothing.
        let mut app = make_app_with_reports(BoardData::default(), reports_catalogue_json(), None);
        assert!(!app.reports_request_export(0));
        assert!(app.reports_pending_export.is_none());
    }

    #[test]
    fn reports_export_surfaces_a_failed_write_rather_than_failing_silently() {
        // The fetch succeeds and the write does not (the destination
        // directory does not exist). That must come back as an explicit
        // failure naming the path — "no file where you asked for one" is
        // exactly the case a silent export would hide.
        let mock = MockBoardService::start("Repo,Issue\napi,1631\n");
        let _guard = set_test_board_service(mock.url(), None);

        let dest = std::env::temp_dir()
            .join("coord-tui-export-no-such-dir-1765")
            .join("out.csv");
        assert!(!dest.exists());

        let mut app = make_app_with_reports(
            BoardData::default(),
            reports_catalogue_json(),
            Some(&reports_result_json()),
        );
        app.reports_start_export("issue-activity", dest.clone());
        let rx = app.reports_export_rx.take().expect("rx must be armed");
        match rx
            .recv_timeout(std::time::Duration::from_secs(10))
            .expect("the export must deliver an outcome before the timeout")
        {
            ReportExportOutcome::Failed(reason) => assert!(
                reason.contains("out.csv"),
                "#1765: a failed write must name the path it failed on: {reason}"
            ),
            ReportExportOutcome::Written { .. } => {
                panic!("#1765: the write cannot have succeeded into a missing directory")
            }
            ReportExportOutcome::NoBoardService => {
                panic!("#1765: the mock board service must be reached")
            }
        }
        assert!(!dest.exists());
    }

    // ── #1910: result-table vertical scroll (wheel + scrollbar drag) ──────
    //
    // The wheel arm for `SidebarView::Reports` (events.rs) and the drag
    // wiring below both existed before #1910 in *shape* only: the wheel
    // clamped scroll against `content_visible_rows(main_b, lh)` — the whole
    // main panel's row count, which overcounts what the result table's own
    // viewport shows (the section stack sits above it) — so the computed
    // `max` was too low and wheel-down looked dead well before the last
    // row. The scrollbar thumb was paint-only: `DataTableLayout::hit_test`
    // has no concept of the strip it reserves for it, so a click/drag there
    // fell through to a row hit, same gap #1094 found (and fixed) for
    // Audit. Both are fixed in `reports.rs`
    // (`reports_table_visible_rows` / `reports_scrollbar_hit` /
    // `reports_apply_vscroll`) and wired in `events.rs`.

    /// A same-shape `ReportResult` with `n` rows, each uniquely labelled
    /// `ROW-000`..`ROW-{n-1:03}` so a specific row's presence on screen
    /// proves exactly how far the table has scrolled.
    fn reports_result_json_many_rows(n: usize) -> String {
        let now = std::time::SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap_or_default()
            .as_secs_f64();
        let rows: Vec<String> = (0..n)
            .map(|i| format!(r#"{{"issue": "ROW-{i:03}", "outcome": "merged"}}"#))
            .collect();
        format!(
            r#"{{
                    "report_id": "issue-activity",
                    "generated_at": {now},
                    "window": [{start}, {now}],
                    "columns": ["issue", "outcome"],
                    "rows": [{rows}],
                    "notes": []
                }}"#,
            now = now,
            start = now - 3600.0,
            rows = rows.join(","),
        )
    }

    /// Terminal size for the #1910 scroll tests: wide enough for both
    /// columns, short enough (30 rows) that the 60-row fixture below needs
    /// real scrolling — the table's own viewport works out to 28 visible
    /// rows (`ROW-000`..`ROW-027` on the first frame), well short of 60.
    ///
    /// #1911: 28, not the pre-#1911 24 — the result table is now the whole
    /// main panel (no section stack sharing it above), so the same terminal
    /// height yields a taller viewport.
    const REPORTS_SCROLL_COLS: u16 = 140;
    const REPORTS_SCROLL_ROWS: u16 = 30;

    /// Dispatch a mouse-wheel event at `pos` — the shape `driver.click` /
    /// `driver.mouse_down` use, but for `UiEvent::Scroll`. `dy` follows the
    /// same sign convention as `mouse_main_scroll`'s `delta.y`: positive
    /// scrolls up (toward the first row), negative scrolls down.
    fn reports_wheel<A: quadraui::AppLogic>(
        driver: &mut quadraui::tui::testing::TuiDriver<A>,
        pos: (f32, f32),
        dy: f32,
    ) {
        driver.dispatch(quadraui::UiEvent::Scroll {
            widget: None,
            delta: ScrollDelta::new(0.0, dy),
            position: Point::new(pos.0, pos.1),
        });
        driver.render();
    }

    /// The result table's painted region of `screen`: every line from `x0`
    /// — the table's left edge — rightward, with the bottom status-bar row
    /// dropped.
    ///
    /// #1996: the whole-screen comparison this exists to replace was flaky.
    /// The Reports screen paints two live wall-clock readouts OUTSIDE the
    /// result table — the params pane's `Window: … → Ns ago` and the shell
    /// status bar's `↻ Ns` — so a wall-second ticking between two renders
    /// made two otherwise byte-identical screens differ by one character,
    /// and `main` went red at `aa9dff0`. Everything at or right of the
    /// table's left edge, status bar excluded, is deterministic, so the
    /// assertion stays exact over precisely the cells the test is about.
    fn reports_table_region(screen: &str, x0: usize) -> String {
        let lines: Vec<&str> = screen.lines().collect();
        let body = lines.split_last().map(|(_, rest)| rest).unwrap_or(&[]);
        body.iter()
            .map(|line| line.chars().skip(x0).collect::<String>())
            .collect::<Vec<_>>()
            .join("\n")
    }

    #[test]
    fn reports_wheel_scrolls_the_result_table_both_directions_and_clamps() {
        let mut driver = reports_driver(
            &reports_result_json_many_rows(60),
            REPORTS_SCROLL_COLS,
            REPORTS_SCROLL_ROWS,
        );
        // Sanity on the unscrolled first frame: the fold is between
        // ROW-027 (last visible) and ROW-028 (first hidden).
        let anchor = driver
            .find("ROW-000")
            .expect("first row must render before any scroll");
        assert!(
            driver.find("ROW-028").is_none(),
            "#1910: ROW-028 must start below the fold on the first frame:\n{}",
            driver.screen()
        );

        // 11 wheel-down notches (3 rows each = 33) overshoots this
        // fixture's max scroll (60 rows - 28 visible = 32) by one row, so
        // the clamp lands exactly at 32 and the table ends showing
        // ROW-032..ROW-059.
        for _ in 0..11 {
            reports_wheel(&mut driver, anchor, -1.0);
        }
        assert!(
            driver.find("ROW-059").is_some(),
            "#1910: 11 wheel-down notches must reach the last row:\n{}",
            driver.screen()
        );
        assert!(
            driver.screen().contains("ROW-032"),
            "#1910: the table must have scrolled to show ROW-032 at the top:\n{}",
            driver.screen()
        );
        assert!(
            !driver.screen().contains("ROW-000"),
            "#1910: ROW-000 must have scrolled off the top:\n{}",
            driver.screen()
        );

        // Over-scrolling must clamp at the last row, not go past it (no
        // blank rows, no panic on an out-of-range offset).
        for _ in 0..5 {
            reports_wheel(&mut driver, anchor, -1.0);
        }
        assert!(
            driver.find("ROW-059").is_some(),
            "#1910: extra wheel-down notches past the end must stay clamped \
                 on the last row:\n{}",
            driver.screen()
        );

        // Wheel back up to the top.
        for _ in 0..11 {
            reports_wheel(&mut driver, anchor, 1.0);
        }
        assert!(
            driver.find("ROW-000").is_some(),
            "#1910: wheeling back up the same number of notches must return \
                 to the first row:\n{}",
            driver.screen()
        );

        // And clamp at the top too — no negative offset.
        for _ in 0..5 {
            reports_wheel(&mut driver, anchor, 1.0);
        }
        assert!(
            driver.find("ROW-000").is_some(),
            "#1910: extra wheel-up notches past the top must stay clamped \
                 on the first row:\n{}",
            driver.screen()
        );
    }

    /// Column of the result table's vertical scrollbar (the rightmost `█`/
    /// `░` glyphs `quadraui`'s rasteriser paints once `show_scrollbar` is
    /// true and the content overflows), and the row range its track spans.
    /// `None` if no scrollbar is on screen (nothing to scroll, or no result
    /// yet).
    fn reports_scrollbar_track(screen: &str) -> Option<(f32, f32, f32)> {
        let mut x = None;
        let mut y_min = f32::MAX;
        let mut y_max = f32::MIN;
        for (y, line) in screen.lines().enumerate() {
            if let Some(col) = line.chars().position(|c| c == '█' || c == '░') {
                x = Some(col as f32 + 0.5);
                y_min = y_min.min(y as f32 + 0.5);
                y_max = y_max.max(y as f32 + 0.5);
            }
        }
        x.map(|x| (x, y_min, y_max))
    }

    #[test]
    fn reports_scrollbar_thumb_drag_scrolls_the_table() {
        let mut driver = reports_driver(
            &reports_result_json_many_rows(60),
            REPORTS_SCROLL_COLS,
            REPORTS_SCROLL_ROWS,
        );
        let (sb_x, track_y0, track_y1) = reports_scrollbar_track(&driver.screen())
            .unwrap_or_else(|| panic!("scrollbar must render for a 60-row result over a \
                24-row viewport:\n{}", driver.screen()));

        // Drag the thumb (currently at the top) to the bottom of the track.
        // The nudge past `track_y1` (rather than landing exactly on it) is
        // deliberate: `track_y1` is the *centre* of the last track cell
        // `reports_scrollbar_track` found, and `reports_apply_vscroll`
        // computes its fraction against the cell's far edge — so a target
        // at the exact centre resolves to one row short of `max_scroll`
        // after rounding. `+ 0.49` reaches that edge while staying inside
        // the same terminal row (and so inside `ctx.in_main`'s bounds,
        // which a real drag can never leave either) — a target that lands
        // in the status-bar row below would fall outside `ctx.in_main`
        // entirely and the drag would silently stop applying, exactly the
        // failure this fixture's height was chosen to surface.
        driver.mouse_down(sb_x, track_y0);
        driver.mouse_move(sb_x, track_y1 + 0.49);
        driver.mouse_up(sb_x, track_y1 + 0.49);
        driver.render();
        assert!(
            driver.find("ROW-059").is_some(),
            "#1910: dragging the scrollbar thumb to the bottom of the track \
                 must scroll to the last row:\n{}",
            driver.screen()
        );
        assert!(
            !driver.screen().contains("ROW-000"),
            "#1910: dragging to the bottom must scroll ROW-000 off screen:\n{}",
            driver.screen()
        );

        // Drag back to the top the same way — nudged above `track_y0`'s
        // centre but still inside the track's top row, for the same reason
        // as the `+ 0.49` above.
        driver.mouse_down(sb_x, track_y1);
        driver.mouse_move(sb_x, track_y0 - 0.49);
        driver.mouse_up(sb_x, track_y0 - 0.49);
        driver.render();
        assert!(
            driver.find("ROW-000").is_some(),
            "#1910: dragging the scrollbar thumb back to the top of the \
                 track must scroll back to the first row:\n{}",
            driver.screen()
        );
    }

    #[test]
    fn reports_scroll_offset_survives_panel_refresh() {
        // #1910 acceptance: the offset must not snap back to the top while
        // a report is being read — i.e. across ordinary repaints, not just
        // across the click that produced them. `reports_idle_tick` (already
        // used by the #1853 column-resize-persistence tests) is exactly
        // that: a button-less mouse move that lets `run_periodic_work` run
        // and forces a repaint, without itself touching scroll or selection.
        let mut driver = reports_driver(
            &reports_result_json_many_rows(60),
            REPORTS_SCROLL_COLS,
            REPORTS_SCROLL_ROWS,
        );
        let anchor = driver
            .find("ROW-000")
            .expect("first row must render before any scroll");
        // #1996: the first row's x IS the result table's left edge (the
        // `issue` column), and a vertical scroll never moves a column
        // horizontally — so this anchor, captured before any scrolling,
        // stays the right slice point for every later render.
        let table_x = anchor.0 as usize;
        for _ in 0..5 {
            reports_wheel(&mut driver, anchor, -1.0);
        }
        let scrolled = driver.screen();
        assert!(
            !scrolled.contains("ROW-000"),
            "#1910: five wheel-down notches (15 rows) must have moved \
                 ROW-000 off screen before the refresh check even starts:\n{scrolled}"
        );

        for _ in 0..3 {
            reports_idle_tick(&mut driver);
        }

        let after_refresh = driver.screen();
        assert!(
            !after_refresh.contains("ROW-000"),
            "#1910: an ordinary repaint (no click, no new run) must not \
                 reset the scroll offset back to the top:\n{after_refresh}"
        );
        assert_eq!(
            reports_table_region(&scrolled, table_x),
            reports_table_region(&after_refresh, table_x),
            "#1910: the result table's painted rows must be pixel-identical \
                 before and after an idle repaint — same scroll offset, same \
                 rows on screen (#1996: compared over the table region only, \
                 because the params pane and the status bar outside it paint \
                 a live clock)\nbefore:\n{scrolled}\nafter:\n{after_refresh}"
        );
    }


    // ── #2271: a report that also declares a chart ──────────────────────
    //
    // Black-box `TuiDriver` tests, in-crate per CLAUDE.md, over the existing
    // `make_app_with_reports` fixture. Targets are located with `find(...)`,
    // never a hardcoded coordinate.
    //
    // The compatibility rule is the point of most of these: a report must
    // never become unreadable on a coord-tui that predates the field, the
    // declared kind, or quadraui#584 — coord-tui is a per-host binary
    // outside propagation's reach, so mixed versions are normal.

    /// A long-form result — one row per (period, bucket) — carrying a chart
    /// declaration. `chart_json` is spliced in verbatim so a test can send a
    /// kind this build has never met, an absent block, or a null one.
    fn reports_chart_result_json(chart_json: &str) -> String {
        let chart_field = if chart_json.is_empty() {
            String::new()
        } else {
            format!(r#","chart": {chart_json}"#)
        };
        format!(
            r#"{{
                "report_id": "queue-outcomes",
                "generated_at": 1000.0,
                "window": [0.0, 1000.0],
                "columns": ["period", "bucket", "count"],
                "column_meta": [
                    {{"id": "period", "label": "Period", "kind": "text",
                      "align": "left", "weight": 1.0}},
                    {{"id": "bucket", "label": "Bucket", "kind": "enum",
                      "align": "left", "weight": 1.0}},
                    {{"id": "count", "label": "Count", "kind": "int",
                      "align": "right", "weight": 1.0}}
                ],
                "rows": [
                    {{"period": "P1", "bucket": "BUCKALPHA", "count": 3}},
                    {{"period": "P1", "bucket": "BUCKBETA", "count": 1}},
                    {{"period": "P2", "bucket": "BUCKALPHA", "count": 5}},
                    {{"period": "P2", "bucket": "BUCKALPHA", "count": 2}},
                    {{"period": "P2", "bucket": "BUCKBETA", "count": 4}}
                ],
                "notes": []
                {chart_field}
            }}"#
        )
    }

    /// The line declaration the 7d/4w `queue-outcomes` view emits: one
    /// trendline per bucket over the period column.
    const REPORTS_LINE_CHART_JSON: &str = r#"{
        "kind": "line",
        "series": [{"label": "Entries", "column": "count", "color": null}],
        "x": "period", "group_by": "bucket", "stacked": false,
        "title": "CHART-CAPTION", "y_label": "Entries"
    }"#;

    /// Deserialise a chart-bearing body straight into the wire type — the
    /// seam `reports_chart_plan` is a pure function over.
    fn reports_chart_result(chart_json: &str) -> crate::app::types::ReportResult {
        serde_json::from_str(&reports_chart_result_json(chart_json))
            .expect("#2271: a chart-bearing ReportResult must deserialise")
    }

    #[test]
    fn reports_line_chart_declaration_renders_a_chart_and_its_legend() {
        let mut driver = reports_driver(
            &reports_chart_result_json(REPORTS_LINE_CHART_JSON),
            140,
            40,
        );
        driver.render();
        let screen = driver.screen();

        assert!(
            driver.find("CHART-CAPTION").is_some(),
            "#2271: the declaration's title must render above the chart:\n{screen}"
        );
        // The legend is the only place a series name appears in a terminal
        // chart, and under `group_by` the series ARE the groups — so seeing
        // both bucket names proves the pivot produced two series and that
        // `paint_line` drew them both.
        for needle in ["BUCKALPHA", "BUCKBETA"] {
            assert!(
                driver.find(needle).is_some(),
                "#2271: {needle:?} must appear as a chart legend entry:\n{screen}"
            );
        }
        // Both halves stay visible: the numbers are what get quoted.
        assert!(
            driver.find("Count").is_some(),
            "#2271: the table must still render under the chart:\n{screen}"
        );
    }

    #[test]
    fn reports_chart_does_not_displace_the_table_or_the_notes() {
        let charted = reports_driver(
            &reports_chart_result_json(REPORTS_LINE_CHART_JSON),
            140,
            40,
        )
        .screen();
        // The table header still renders, below where the chart was drawn.
        let plain = reports_driver(&reports_chart_result_json(""), 140, 40).screen();
        assert!(
            plain.contains("Bucket") && charted.contains("Bucket"),
            "#2271: the table header must render with and without a chart\
                 \nplain:\n{plain}\ncharted:\n{charted}"
        );
        let plain_row = plain.lines().position(|l| l.contains("Bucket"));
        let charted_row = charted.lines().position(|l| l.contains("Bucket"));
        assert!(
            charted_row > plain_row,
            "#2271: the chart takes rows from the top of the result area, so \
                 the table must start LOWER when one is drawn (plain \
                 {plain_row:?}, charted {charted_row:?})"
        );
    }

    #[test]
    fn reports_result_with_no_chart_key_renders_exactly_as_before() {
        // The older-daemon case, which is the acceptance criterion that
        // matters most: a payload that predates the field must render the
        // table with no error AND no blank space. Compared against an
        // explicit `"chart": null` because that is the same wire fact said
        // two ways, and the two must be pixel-identical.
        let absent = reports_driver(&reports_chart_result_json(""), 140, 40).screen();
        let explicit_null =
            reports_driver(&reports_chart_result_json("null"), 140, 40).screen();
        assert_eq!(
            absent, explicit_null,
            "#2271: an absent `chart` key and an explicit null must render \
                 identically — no chart, no reason line, no reserved \
                 space\nabsent:\n{absent}\nnull:\n{explicit_null}"
        );
        assert!(
            !absent.contains("Chart not shown"),
            "#2271: a report that declares no chart must say nothing about \
                 charts:\n{absent}"
        );
    }

    #[test]
    fn reports_unknown_chart_kind_falls_back_to_the_table() {
        let json = r#"{
            "kind": "sunburst",
            "series": [{"label": "Entries", "column": "count", "color": null}],
            "x": "period", "group_by": "bucket", "stacked": false,
            "title": "CHART-CAPTION", "y_label": ""
        }"#;
        let mut driver = reports_driver(&reports_chart_result_json(json), 140, 40);
        driver.render();
        let screen = driver.screen();

        assert!(
            driver.find("Bucket").is_some() && driver.find("BUCKALPHA").is_some(),
            "#2271: a chart kind this build predates must still render the \
                 table:\n{screen}"
        );
        assert!(
            screen.contains("sunburst"),
            "#2271: the fallback must NAME the kind it did not understand — \
                 a silently missing chart is undiagnosable:\n{screen}"
        );
        assert!(
            driver.find("CHART-CAPTION").is_none(),
            "#2271: no chart means no chart caption either:\n{screen}"
        );
    }

    /// #2271 acceptance: bar rendering is gated on the pin actually carrying
    /// quadraui#584, and the degraded branch is pinned here so it cannot rot
    /// on a build whose pin *does* carry it. `reports_chart_plan` takes the
    /// capability as an argument precisely so both branches stay testable.
    #[test]
    fn reports_multi_series_bar_degrades_when_the_pin_predates_quadraui_584() {
        let json = r#"{
            "kind": "bar",
            "series": [{"label": "Entries", "column": "count", "color": null}],
            "x": "bucket", "group_by": "bucket", "stacked": true,
            "title": "CHART-CAPTION", "y_label": "Entries"
        }"#;
        let result = reports_chart_result(json);

        match CoordApp::reports_chart_plan(&result, false) {
            crate::app::reports::ChartPlan::Degrade(reason) => {
                assert!(
                    reason.contains("quadraui#584"),
                    "#2271: the degraded section must state the reason and \
                         name the blocker, got {reason:?}"
                );
            }
            other => panic!(
                "#2271: a 2-series bar on a pin without quadraui#584 must \
                     degrade to the table, not draw a chart missing most of \
                     its data — got {other:?}"
            ),
        }

        match CoordApp::reports_chart_plan(&result, true) {
            crate::app::reports::ChartPlan::Render { chart, .. } => {
                assert_eq!(
                    chart.series.len(),
                    2,
                    "#2271: with #584 in the pin, both buckets are plotted"
                );
            }
            other => panic!(
                "#2271: with #584 in the pin the same declaration must \
                     render — got {other:?}"
            ),
        }
    }

    #[test]
    fn reports_single_series_bar_renders_on_any_pin() {
        // One series is exactly what pre-#584 `paint_bar` drew correctly,
        // so the gate must not refuse it.
        let json = r#"{
            "kind": "bar",
            "series": [{"label": "Entries", "column": "count", "color": null}],
            "x": "period", "stacked": true, "title": "", "y_label": ""
        }"#;
        let result = reports_chart_result(json);
        assert!(
            matches!(
                CoordApp::reports_chart_plan(&result, false),
                crate::app::reports::ChartPlan::Render { .. }
            ),
            "#2271: a single-series bar predates #584's problem entirely"
        );
    }

    #[test]
    fn reports_chart_pivot_sums_cells_and_keeps_row_order() {
        let result = reports_chart_result(REPORTS_LINE_CHART_JSON);
        let plan = CoordApp::reports_chart_plan(&result, true);
        let crate::app::reports::ChartPlan::Render { chart, title } = plan else {
            panic!("#2271: the line declaration must render");
        };
        assert_eq!(title, "CHART-CAPTION");
        let labels: Vec<&str> = chart.series.iter().map(|s| s.label.as_str()).collect();
        assert_eq!(
            labels,
            vec!["BUCKALPHA", "BUCKBETA"],
            "#2271: one series per distinct group, in first-appearance order"
        );
        // P1/P2 are the distinct x values; BUCKALPHA has two P2 rows (5 + 2)
        // that must SUM into one point, not overwrite each other.
        assert_eq!(chart.series[0].data, vec![3.0, 7.0]);
        assert_eq!(chart.series[1].data, vec![1.0, 4.0]);
    }

    #[test]
    fn reports_chart_naming_a_column_this_result_lacks_degrades_not_flatlines() {
        // A mistyped/renamed column must look like a missing series, never
        // like a real run of zeros — the most flattering possible bug.
        let json = r#"{
            "kind": "line",
            "series": [{"label": "Entries", "column": "no_such_column", "color": null}],
            "x": "period", "group_by": "bucket", "stacked": false,
            "title": "", "y_label": ""
        }"#;
        let result = reports_chart_result(json);
        assert!(
            matches!(
                CoordApp::reports_chart_plan(&result, true),
                crate::app::reports::ChartPlan::Degrade(_)
            ),
            "#2271: a series naming no numeric column must degrade"
        );
    }

    #[test]
    fn reports_empty_result_declaring_a_chart_draws_neither() {
        // Zero rows already render an explicit "no activity in this window"
        // body; an axis with no marks over it would read as a measured zero.
        let json = format!(
            r#"{{
                "report_id": "queue-outcomes", "generated_at": 1000.0,
                "window": [0.0, 1000.0],
                "columns": ["period", "count"], "rows": [], "notes": [],
                "chart": {REPORTS_LINE_CHART_JSON}
            }}"#
        );
        let result: crate::app::types::ReportResult =
            serde_json::from_str(&json).expect("must deserialise");
        assert!(matches!(
            CoordApp::reports_chart_plan(&result, true),
            crate::app::reports::ChartPlan::None
        ));

        let mut driver = reports_driver(&json, 140, 40);
        driver.render();
        let screen = driver.screen();
        assert!(
            screen.contains("No activity in this window"),
            "#2271: the empty-window body still owns the panel:\n{screen}"
        );
        assert!(
            !screen.contains("CHART-CAPTION"),
            "#2271: no rows means no chart and no caption:\n{screen}"
        );
    }

    #[test]
    fn reports_partial_chart_block_does_not_take_the_table_down_with_it() {
        // Every field is `#[serde(default)]` on purpose: a daemon shipping a
        // half-built block must degrade the chart, never fail the whole
        // `ReportResult` deserialise and blank the report.
        let mut driver =
            reports_driver(&reports_chart_result_json(r#"{"kind": "line"}"#), 140, 40);
        driver.render();
        let screen = driver.screen();
        assert!(
            driver.find("BUCKALPHA").is_some(),
            "#2271: a chart block with no series must still render the \
                 table:\n{screen}"
        );
    }

    #[test]
    fn reports_chart_is_dropped_rather_than_gutting_a_short_panel() {
        // A chart is a scan aid; stealing a short panel's last rows for a
        // two-row chart helps nobody. The table wins, silently.
        let mut driver = reports_driver(
            &reports_chart_result_json(REPORTS_LINE_CHART_JSON),
            140,
            14,
        );
        driver.render();
        let screen = driver.screen();
        assert!(
            driver.find("CHART-CAPTION").is_none(),
            "#2271: too short for a useful chart — it must be dropped:\n{screen}"
        );
        assert!(
            driver.find("Bucket").is_some(),
            "#2271: ...and the table must still be there:\n{screen}"
        );
    }

    // ── #2827: the Trend report — two stacked charts, one range selector ─
    //
    // `trend` (#2826) can't use the #2271 `ReportResult.chart` mechanism
    // above (see `CoordApp::render_trend_charts`'s doc comment for why —
    // one `y_range` can't honestly hold both a merge count and a dollar
    // figure), so it is rendered by a dedicated, report-specific path.
    // These tests exercise that path both at the pure-function level (the
    // null-bucket rendering rule, which is exact and not worth screen-
    // scraping for) and end-to-end through `TuiDriver` (rendering, and the
    // range selector's rerun/rerender).

    /// A catalogue carrying only `trend`, mirroring #2826's
    /// `coord/reports.py` `TREND` `ReportDef` wire shape trimmed to what
    /// the client reads (`range`'s four choices, plus `repo` so the form
    /// isn't a single-field degenerate case).
    fn trend_catalogue_json() -> &'static str {
        r#"{
                "reports": [
                    {
                        "id": "trend",
                        "title": "Trend",
                        "description": "Time-bucketed merge throughput + cost efficiency",
                        "params": [
                            {
                                "id": "range", "label": "Range", "kind": "choice",
                                "choices": ["1d", "3d", "7d", "1m"], "default": "7d",
                                "help": "1d=hourly, 3d=3-hourly, 7d=6-hourly, 1m=daily",
                                "free_form": false
                            },
                            {
                                "id": "repo", "label": "Repo", "kind": "text",
                                "choices": [], "default": "", "help": "", "free_form": false
                            }
                        ]
                    }
                ]
            }"#
    }

    /// A `GET /report/trend` body. `rows_json` is the `rows` array
    /// verbatim (#2826's `bucket_start`/`merged`/`cost_per_issue`/
    /// `legs_per_issue` shape) and `note` lands in `notes`, so a driver
    /// test can tell two delivered results apart on screen without trying
    /// to read chart pixels.
    fn trend_result_json(rows_json: &str, note: &str) -> String {
        format!(
            r#"{{
                    "report_id": "trend",
                    "generated_at": 1785000000.0,
                    "window": [1784900000.0, 1785000000.0],
                    "columns": ["bucket_start", "merged", "cost_per_issue", "legs_per_issue"],
                    "rows": {rows_json},
                    "notes": ["{note}"]
                }}"#
        )
    }

    /// Open the Reports panel on a seeded `trend` result and render one
    /// frame — the `trend`-only counterpart of `reports_driver`.
    fn trend_driver(
        result_json: &str,
        w: u16,
        h: u16,
    ) -> quadraui::tui::testing::TuiDriver<impl quadraui::AppLogic> {
        use quadraui::tui::testing::driver_with_shell;
        let app = make_app_with_reports(
            BoardData::default(),
            trend_catalogue_json(),
            Some(result_json),
        );
        let mut driver = driver_with_shell(app, CoordApp::shell_config(), w, h);
        click_activity_icon(&mut driver, "▤");
        driver.render();
        driver
    }

    /// The null-bucket rendering rule, exactly: a leading run of `null`
    /// buckets (no prior reading exists) is backward-filled from the first
    /// reading; a `null` bucket after that is forward-filled from the most
    /// recent one. Never `0.0` — the one wrong answer the issue calls out.
    #[test]
    fn trend_cost_series_holds_the_value_across_null_buckets() {
        let rows = r#"[
                {"bucket_start": 1.0, "merged": 0, "cost_per_issue": null, "legs_per_issue": null},
                {"bucket_start": 2.0, "merged": 1, "cost_per_issue": 10.0, "legs_per_issue": 1.0},
                {"bucket_start": 3.0, "merged": 0, "cost_per_issue": null, "legs_per_issue": null},
                {"bucket_start": 4.0, "merged": 2, "cost_per_issue": 20.0, "legs_per_issue": 1.5}
            ]"#;
        let result: crate::app::types::ReportResult =
            serde_json::from_str(&trend_result_json(rows, "n")).expect("#2827: fixture parses");

        let series =
            CoordApp::trend_cost_series(&result).expect("#2827: at least one reading exists");
        assert_eq!(
            series.data,
            vec![10.0, 10.0, 10.0, 20.0],
            "#2827: bucket 0 (leading null) must hold bucket 1's reading \
                 backward, and bucket 2 (a null after data has begun) must \
                 hold bucket 1's reading forward — never 0.0"
        );
        assert!(
            series.fill,
            "#2827: chart B is a filled line — that's what makes a falling \
                 trend read as a trend rather than a bare line"
        );
    }

    /// No merge anywhere in the window or its trailing lookback means no
    /// reading exists to hold — the chart must be dropped, not drawn from
    /// a fabricated `0.0`.
    #[test]
    fn trend_cost_series_is_none_when_every_bucket_is_null() {
        let rows = r#"[
                {"bucket_start": 1.0, "merged": 0, "cost_per_issue": null, "legs_per_issue": null},
                {"bucket_start": 2.0, "merged": 0, "cost_per_issue": null, "legs_per_issue": null}
            ]"#;
        let result: crate::app::types::ReportResult =
            serde_json::from_str(&trend_result_json(rows, "n")).expect("#2827: fixture parses");
        assert!(
            CoordApp::trend_cost_series(&result).is_none(),
            "#2827: no reading anywhere must mean no chart, not a \
                 fabricated zero-cost one"
        );
    }

    /// `merged` is always present (#2826's `fold_trend` never emits `null`
    /// for it) — a genuinely empty bucket is a real `0`, not a gap.
    #[test]
    fn trend_merged_series_is_the_row_order_never_null() {
        let rows = r#"[
                {"bucket_start": 1.0, "merged": 3, "cost_per_issue": null, "legs_per_issue": null},
                {"bucket_start": 2.0, "merged": 0, "cost_per_issue": 5.0, "legs_per_issue": 1.0}
            ]"#;
        let result: crate::app::types::ReportResult =
            serde_json::from_str(&trend_result_json(rows, "n")).expect("#2827: fixture parses");
        assert_eq!(
            CoordApp::trend_merged_series(&result).data,
            vec![3.0, 0.0],
            "#2827: merged is a real per-bucket count, bar-chart-honest \
                 zero included"
        );
    }

    /// The full render path: two captioned charts, never the generic
    /// `DataTable` (whose `Bucket` column header this report's rows would
    /// otherwise trigger).
    #[test]
    fn trend_report_renders_two_stacked_charts_not_a_table() {
        let rows = r#"[
                {"bucket_start": 1.0, "merged": 2, "cost_per_issue": 12.5, "legs_per_issue": 1.0},
                {"bucket_start": 2.0, "merged": 1, "cost_per_issue": 9.0, "legs_per_issue": 1.0},
                {"bucket_start": 3.0, "merged": 4, "cost_per_issue": 7.25, "legs_per_issue": 1.2}
            ]"#;
        let driver = trend_driver(&trend_result_json(rows, "TESTNOTE-A"), 140, 40);
        let screen = driver.screen();

        // Not asserting on the `y_label`s ("Merged"/"$/Issue") here: the
        // TUI rasteriser sizes that gutter off the *tick value* labels
        // (`format_tick_value`), not off `y_label`'s own length
        // (`primitives/chart.rs::layout`'s `y_label_width` /
        // `tui/chart.rs::paint_axes`), so a short axis range clips a
        // longer `y_label` mid-word — this is quadraui's own behaviour,
        // not a bug this panel should paper over, but it does make
        // `y_label` text unreliable to substring-match in a test. The
        // captions (drawn as a plain, unclipped `ListView` row) are the
        // reliable per-chart identifier instead.
        for needle in ["Throughput", "Efficiency", "TESTNOTE-A"] {
            assert!(
                screen.contains(needle),
                "#2827: {needle:?} must render:\n{screen}"
            );
        }
        assert!(
            driver.find("Bucket").is_none(),
            "#2827: the trend report must never fall back to the generic \
                 DataTable (its `Bucket` column header must not render):\n{screen}"
        );

        let (_, throughput_y) = driver.find("Throughput").expect("caption renders");
        let (_, efficiency_y) = driver.find("Efficiency").expect("caption renders");
        assert!(
            efficiency_y > throughput_y,
            "#2827: chart A (throughput) must sit above chart B \
                 (efficiency):\n{screen}"
        );
    }

    /// A `cost_per_issue` column that is `null` in every bucket must
    /// degrade to a stated message, not a chart drawn from nothing — the
    /// end-to-end counterpart of `trend_cost_series_is_none_when_every_bucket_is_null`.
    #[test]
    fn trend_all_null_cost_column_renders_a_fallback_message_not_a_chart() {
        let rows = r#"[
                {"bucket_start": 1.0, "merged": 0, "cost_per_issue": null, "legs_per_issue": null},
                {"bucket_start": 2.0, "merged": 0, "cost_per_issue": null, "legs_per_issue": null}
            ]"#;
        let driver = trend_driver(&trend_result_json(rows, "TESTNOTE-B"), 140, 40);
        let screen = driver.screen();
        assert!(
            screen.contains("No cost data"),
            "#2827: an all-null cost column must say so, never render a \
                 fabricated zero-cost chart:\n{screen}"
        );
        assert!(
            screen.contains("Throughput"),
            "#2827: chart A must still render even when chart B \
                 degrades:\n{screen}"
        );
    }

    /// Switching the shared range selector, then clicking Run, re-requests
    /// (`Running trend…` in flight) — the same generic Run flow
    /// `reports_run_click_marks_the_report_in_flight` pins for
    /// `issue-activity`, exercised here for `trend`. There is deliberately
    /// only ONE selector driving both charts: it is the catalogue's
    /// ordinary `range` `SegmentedControl` (rendered by the fully generic
    /// `reports_param_form`), nothing new added for this panel.
    #[test]
    fn trend_switching_the_range_selector_then_run_reruns() {
        let app = make_app_with_reports(BoardData::default(), trend_catalogue_json(), None);
        let mut driver =
            quadraui::tui::testing::driver_with_shell(app, CoordApp::shell_config(), 140, 40);
        click_activity_icon(&mut driver, "▤");
        driver.render();

        // Real geometry-based click routing (not a hand-built field id) —
        // the black-box path a user actually drives.
        let (sx, sy) = driver
            .find("1d")
            .unwrap_or_else(|| panic!("range option not rendered:\n{}", driver.screen()));
        driver.click(sx, sy);
        driver.render();

        let (rx, ry) = driver
            .find("Run")
            .unwrap_or_else(|| panic!("Run button not rendered:\n{}", driver.screen()));
        driver.click(rx, ry);
        driver.render();
        assert!(
            driver.screen().contains("Running trend"),
            "#2827: clicking Run after switching the range selector must \
                 re-request:\n{}",
            driver.screen()
        );
    }

    /// Once a re-run's result lands, it replaces the previous one on
    /// screen — both charts included, via the same `reports_run_rx`
    /// delivery path `reports_completed_run_populates_the_main_panel_grid`
    /// pins for `issue-activity`'s table. (Delivered through the fixture's
    /// pre-armed channel rather than a real Run click — a real click here
    /// would spawn a second, never-completing background fetch under
    /// `cfg(test)`'s "no board service" and swap out the channel `pending`
    /// is bound to, same as every other Reports test that uses this
    /// fixture instead of clicking Run live.)
    #[test]
    fn trend_delivered_rerun_replaces_the_previous_charts() {
        let rows_a = r#"[{"bucket_start": 1.0, "merged": 1, "cost_per_issue": 5.0, "legs_per_issue": 1.0}]"#;
        let rows_b = r#"[{"bucket_start": 1.0, "merged": 9, "cost_per_issue": 50.0, "legs_per_issue": 2.0}]"#;

        let (app, pending) = make_app_with_reports_awaiting_run(
            BoardData::default(),
            trend_catalogue_json(),
            &trend_result_json(rows_a, "TESTNOTE-A"),
        );
        let mut driver =
            quadraui::tui::testing::driver_with_shell(app, CoordApp::shell_config(), 140, 40);
        click_activity_icon(&mut driver, "▤");
        driver.render();
        assert!(
            driver.screen().contains("TESTNOTE-A"),
            "sanity: the seeded result must render first:\n{}",
            driver.screen()
        );

        assert!(
            pending.deliver(&trend_result_json(rows_b, "TESTNOTE-B")),
            "#2827: fixture must parse and send"
        );
        reports_idle_tick(&mut driver);

        let screen = driver.screen();
        assert!(
            screen.contains("TESTNOTE-B") && !screen.contains("TESTNOTE-A"),
            "#2827: the re-run's result must replace the old one on \
                 screen, both charts included:\n{screen}"
        );
    }

    // ── #1866 (Q-1): the Queue panel ────────────────────────────────────
    //
    // Black-box `TuiDriver` tests, in-crate because the fixtures are
    // private. Every target is located with `driver.find(...)`, never a
    // hardcoded coordinate.

    /// The activity-bar glyph for the Queue panel (`CoordApp::shell_config`).
    const QUEUE_ICON: &str = "⇅";

    /// A drive queue in the wire shape `/board` ships (note `after_json`,
    /// not `after`), covering every state the panel has an opinion about:
    /// one `running`, two `waiting` (one of them gated behind the other),
    /// one `blocked`, one `failed` — a state THIS build has never heard of,
    /// standing in for a newer daemon — and one `done`, which is the only
    /// entry that must not appear.
    fn queue_fixture_json() -> &'static str {
        r#"[
            {"repo_name": "myrepo", "issue_number": 700, "position": 0,
             "state": "done", "attempts": 1, "last_reason": "REASON-DONE"},
            {"repo_name": "myrepo", "issue_number": 701, "position": 1,
             "state": "running", "machine": "alpha", "attempts": 1,
             "last_reason": "REASON-RUNNING"},
            {"repo_name": "myrepo", "issue_number": 702, "position": 2,
             "state": "waiting", "attempts": 0, "after_json": ["myrepo#701"],
             "last_reason": "REASON-WAITING"},
            {"repo_name": "myrepo", "issue_number": 703, "position": 3,
             "state": "blocked", "attempts": 9, "last_reason": "REASON-BLOCKED"},
            {"repo_name": "myrepo", "issue_number": 704, "position": 4,
             "state": "failed", "attempts": 3, "last_reason": "REASON-FAILED"},
            {"repo_name": "myrepo", "issue_number": 705, "position": 5,
             "state": "waiting", "machine": "beta", "attempts": 0,
             "hold_after": 1, "hold_state": "fired", "hold_reason": "deploy it",
             "last_reason": "REASON-HELD"}
        ]"#
    }

    /// Open the Queue panel on a seeded queue and render one frame.
    fn queue_driver(
        drive_queue_json: &str,
        w: u16,
        h: u16,
    ) -> quadraui::tui::testing::TuiDriver<impl quadraui::AppLogic> {
        use quadraui::tui::testing::driver_with_shell;
        let app = make_app_with_drive_queue(BoardData::default(), drive_queue_json);
        let mut driver = driver_with_shell(app, CoordApp::shell_config(), w, h);
        click_activity_icon(&mut driver, QUEUE_ICON);
        driver.render();
        driver
    }

    /// A `CoordApp` (no driver) sitting on the fixture queue, for the write
    /// path — `TuiDriver::app_mut` yields the opaque shell adapter, so
    /// `command_runner.spawned_calls` is only reachable this way.
    fn queue_app(drive_queue_json: &str) -> CoordApp {
        make_app_with_drive_queue(BoardData::default(), drive_queue_json)
    }

    #[test]
    fn tuidriver_queue_panel_is_reachable_from_the_activity_bar() {
        let driver = queue_driver(queue_fixture_json(), 160, 30);
        let screen = driver.screen();
        assert!(
            screen.contains("QUEUE"),
            "#1866: clicking the {QUEUE_ICON} activity-bar icon must land on \
             the Queue panel (its sidebar header):\n{screen}"
        );
    }

    #[test]
    fn tuidriver_queue_panel_shows_every_unfinished_state_and_hides_done() {
        let driver = queue_driver(queue_fixture_json(), 160, 30);
        let screen = driver.screen();
        for (issue, reason) in [
            ("701", "REASON-RUNNING"),
            ("702", "REASON-WAITING"),
            ("703", "REASON-BLOCKED"),
            ("704", "REASON-FAILED"),
            ("705", "REASON-HELD"),
        ] {
            assert!(
                screen.contains(&format!("M#{issue}")),
                "#1866/#2042: myrepo#{issue} has not finished, so a LIVE view \
                 must not hide it (rendered as the M# alias) — blocked/failed \
                 entries are precisely the ones needing a human:\n{screen}"
            );
            assert!(
                screen.contains(reason),
                "#1866: `last_reason` carries the whole story on a stalled \
                 entry, so {reason} must be legible, not truncated away:\n{screen}"
            );
        }
        assert!(
            !screen.contains("M#700"),
            "#1866: `done` is the ONE state this panel excludes — it is \
             history, not pending work:\n{screen}"
        );
        assert!(
            !screen.contains("REASON-DONE"),
            "#1866: …and nothing of the done entry may leak through:\n{screen}"
        );
    }

    #[test]
    fn tuidriver_queue_panel_renders_the_declared_columns() {
        let driver = queue_driver(queue_fixture_json(), 200, 30);
        let screen = driver.screen();
        for title in [
            "Issue", "Title", "State", "Machine", "#Work", "#Smoke", "#Review", "After", "Hold",
            "Reason",
        ] {
            assert!(
                screen.contains(title),
                "#1866: the grid must carry a `{title}` column:\n{screen}"
            );
        }
        assert!(
            screen.contains("FIRED"),
            "#1866: a fired deploy gate stops the whole queue — the `Hold` \
             cell must say so:\n{screen}"
        );
        assert!(
            screen.contains("alpha") && screen.contains("beta"),
            "#1866: the machine pin is an operator intent and must be \
             visible:\n{screen}"
        );
    }

    /// #2133: `last_reason` is a snapshot taken the instant it was written,
    /// never re-validated — the #2104 incident it names is a `checks_failed`
    /// reason that outlived the CI failure it described by ~3 hours while
    /// the real, later blocker went unmentioned. The Queue panel must show
    /// the reason's age so it can never read as a live diagnosis.
    #[test]
    fn tuidriver_queue_panel_age_stamps_a_stale_reason() {
        let now = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap_or_default()
            .as_secs_f64();
        // 3h + 60s ago: comfortably inside the "3h ago" bucket
        // (`format_age` truncates to whole hours) with slack on both sides
        // so a few milliseconds of test execution can never flip the digit.
        let reason_at = now - (3.0 * 3600.0 + 60.0);
        let fixture = format!(
            r#"[
                {{"repo_name": "myrepo", "issue_number": 703, "position": 0,
                 "state": "blocked", "attempts": 9,
                 "last_reason": "checks_failed: test (3.12)",
                 "reason_at": {reason_at}}}
            ]"#
        );
        let driver = queue_driver(&fixture, 200, 30);
        let screen = driver.screen();
        assert!(
            screen.contains("checks_failed: test (3.12)"),
            "the reason text itself must still be legible:\n{screen}"
        );
        assert!(
            screen.contains("(3h ago)"),
            "#2133: a stale `last_reason` must carry its age so it is never \
             mistaken for a current diagnosis:\n{screen}"
        );
    }

    /// A `reason_at`-less row (predates #2133's migration, or a fixture that
    /// never set it) renders the bare reason — no fabricated age, and no
    /// crash on the missing field.
    #[test]
    fn tuidriver_queue_panel_omits_age_when_reason_at_is_unknown() {
        let driver = queue_driver(queue_fixture_json(), 160, 30);
        let screen = driver.screen();
        assert!(
            screen.contains("REASON-BLOCKED"),
            "the reason still renders on its own:\n{screen}"
        );
        assert!(
            !screen.contains("REASON-BLOCKED ("),
            "#2133: no `reason_at` means no age can be computed — the cell \
             must not invent one:\n{screen}"
        );
    }

    #[test]
    fn tuidriver_queue_panel_states_are_visually_distinguishable() {
        // Colour is asserted at the model layer (the screen dump is plain
        // text) — but the model is exactly what the renderer consumes, so a
        // regression that flattened the palette would fail here.
        assert_ne!(
            dq_state_colors("running").0,
            dq_state_colors("blocked").0,
            "#1866: running and blocked must not paint the same colour"
        );
        assert_ne!(
            dq_state_colors("waiting").0,
            dq_state_colors("blocked").0,
            "#1866: waiting and blocked must not paint the same colour"
        );
        // …and the state word itself is always on screen, which is what
        // makes an unrecognised state (`failed`) distinguishable even though
        // `dq_state_colors` deliberately renders it neutral rather than
        // guessing at a colour for it.
        let driver = queue_driver(queue_fixture_json(), 160, 30);
        let screen = driver.screen();
        for state in ["running", "waiting", "blocked", "failed"] {
            assert!(
                screen.contains(state),
                "#1866: the wire state `{state}` must be rendered verbatim:\n{screen}"
            );
        }
    }

    #[test]
    fn tuidriver_queue_panel_empty_queue_says_so() {
        let driver = queue_driver("[]", 160, 30);
        let screen = driver.screen();
        assert!(
            screen.contains("Drive queue is empty"),
            "#1866: an empty grid renders as a bare header row, which reads \
             like a broken fetch — say what actually happened:\n{screen}"
        );
    }

    #[test]
    fn tuidriver_queue_panel_all_done_is_not_the_same_as_empty() {
        let driver = queue_driver(
            r#"[{"repo_name": "myrepo", "issue_number": 700, "position": 0,
                 "state": "done"}]"#,
            160,
            30,
        );
        let screen = driver.screen();
        assert!(
            screen.contains("Nothing pending") && screen.contains("done entries"),
            "#1866: 'the queue is empty' and 'everything in it has finished' \
             are different facts and must not render identically:\n{screen}"
        );
    }

    #[test]
    fn tuidriver_queue_header_click_cycles_sort_ascending_descending_off() {
        let mut driver = queue_driver(queue_fixture_json(), 200, 30);
        assert!(
            !driver.screen().contains('▲') && !driver.screen().contains('▼'),
            "#1866: an unsorted grid must show no indicator:\n{}",
            driver.screen()
        );

        // Click a few cells INTO the header text, never at its first cell:
        // `DataTableLayout::hit_test` gives a ±3-cell divider grab zone
        // priority over the header, and a column's left edge IS the previous
        // column's right edge. Successive clicks are 5 cells apart so the
        // backend's double-click detector can't fold two into one.
        // `Reason` is the target because it is by far the widest column
        // here: three clicks 7 cells apart all stay clear of the ±3-cell
        // divider grab zones at either edge, and far enough apart that the
        // backend's double-click detector (1.5-cell radius) can never fold
        // two of them into a `DoubleClick` that the click handler never sees.
        let (x, y) = driver
            .find("Reason")
            .unwrap_or_else(|| panic!("Reason header must render:\n{}", driver.screen()));
        driver.click(x + 3.0, y);
        driver.render();
        assert!(
            driver.screen().contains('▲'),
            "#1866: the first header click must sort ascending:\n{}",
            driver.screen()
        );

        driver.click(x + 10.0, y);
        driver.render();
        assert!(
            driver.screen().contains('▼') && !driver.screen().contains('▲'),
            "#1866: the second click must flip to descending:\n{}",
            driver.screen()
        );

        driver.click(x + 17.0, y);
        driver.render();
        assert!(
            !driver.screen().contains('▲') && !driver.screen().contains('▼'),
            "#1866: the third click must clear the sort, so the queue's own \
             RUN ORDER is reachable again — which is a different answer from \
             any column sort:\n{}",
            driver.screen()
        );
    }

    #[test]
    fn tuidriver_queue_sort_click_lands_on_the_column_under_the_cursor() {
        // The regression the pinned `h_scroll: 0.0` exists to prevent: a
        // non-zero h_scroll would shift the painted headers out from under
        // `DataTableLayout::hit_test`, which has no concept of it, and route
        // the sort to a neighbouring column.
        let mut driver = queue_driver(queue_fixture_json(), 200, 30);
        let (x, y) = driver
            .find("Reason")
            .unwrap_or_else(|| panic!("Reason header must render:\n{}", driver.screen()));
        driver.click(x + 3.0, y);
        driver.render();

        let screen = driver.screen();
        let row: String = screen_row(&screen, y).into_iter().collect();
        let cells: Vec<char> = row.chars().collect();
        let at_reason: String = cells
            .iter()
            .skip(x as usize)
            .take("Reason ▲".chars().count())
            .collect();
        assert_eq!(
            at_reason, "Reason ▲",
            "#1866: the ▲ must land on `Reason`, the column actually under \
             the cursor at x={x}. Header row was:\n{row}\n{screen}"
        );
        assert_eq!(
            row.matches('▲').count(),
            1,
            "#1866: exactly one column may carry the ascending indicator:\n{row}"
        );
    }

    #[test]
    fn queue_sort_orders_numeric_columns_numerically() {
        // `#Work` runs 10 for issue 1 and 9 for issue 2. A lexical sort of
        // the RENDERED strings would be indistinguishable at these values,
        // so the test uses the raw comparator against a two-digit count
        // that sorts the other way as text ("10" < "9").
        let work_assignments = |issue: u64, n: usize| -> Vec<Assignment> {
            (0..n)
                .map(|i| Assignment {
                    id: format!("r-{issue}-work-{i}"),
                    ..make_assignment_typed("done", issue, "r", Some("work"))
                })
                .collect()
        };
        let mut assignments = work_assignments(1, 10);
        assignments.extend(work_assignments(2, 9));
        let mut app = make_app_with_drive_queue(
            BoardData {
                assignments,
                ..BoardData::default()
            },
            r#"[{"repo_name": "r", "issue_number": 1, "position": 0,
                 "state": "waiting"},
                {"repo_name": "r", "issue_number": 2, "position": 1,
                 "state": "waiting"}]"#,
        );
        assert!(
            app.queue_sort_by_column(CoordApp::QUEUE_COL_WORK),
            "sorting the #Work column must apply"
        );
        let order: Vec<i64> = app.queue_rows().iter().map(|r| r.work_count).collect();
        assert_eq!(
            order,
            vec![9, 10],
            "#2524: `#Work` must sort numerically — a lexical sort would put \
             10 before 9 (the #1762 defect)"
        );
    }

