    /// #2016: "View on Board" switches to the Board view with the row's
    /// issue selected. The sidebar's "No milestone" group defaults to
    /// collapsed, so neither issue's title renders in the tree — the
    /// distinguishing title text can only come from the Board detail pane,
    /// which only populates for the actually-selected issue. A second,
    /// differently-titled issue (never queued) proves the jump landed on
    /// #7 specifically, not just "whichever issue Board defaults to."
    #[test]
    fn tuidriver_queue_view_on_board_switches_to_board_with_issue_selected() {
        use quadraui::tui::testing::driver_with_shell;
        let mut app = make_app_with_drive_queue(
            BoardData {
                open_issues: vec![
                    OpenIssue {
                        repo_name: "myrepo".to_string(),
                        number: 7,
                        title: "Board target issue".to_string(),
                        body: String::new(),
                        labels: vec![],
                        state: "open".to_string(),
                        milestone_number: None,
                        milestone_title: None,
                        body_truncated: false,
                        body_len: None,
                        // #1941: fields added to the generated wire DTO; not exercised by this test.
                        synced_at: None,
                    },
                    OpenIssue {
                        repo_name: "myrepo".to_string(),
                        number: 9,
                        title: "Decoy issue never queued".to_string(),
                        body: String::new(),
                        labels: vec![],
                        state: "open".to_string(),
                        milestone_number: None,
                        milestone_title: None,
                        body_truncated: false,
                        body_len: None,
                        // #1941: fields added to the generated wire DTO; not exercised by this test.
                        synced_at: None,
                    },
                ],
                pipeline_repos: vec![("myrepo".to_string(), "acme/myrepo".to_string())],
                ..BoardData::default()
            },
            queue_fixture_json_middle_row_7(),
        );
        // Untracked (no `pipeline_issues`) ⇒ "View in Pipeline" renders
        // disabled and is skipped by keyboard nav, same as the disabled-item
        // test above — so only two Down presses are needed to reach "View
        // on Board" too.
        app.rebuild_board_sidebar();
        app.active_view = SidebarView::Queue;

        let mut driver = driver_with_shell(app, CoordApp::shell_config(), 140, 40);
        let (x, y) = driver
            .find("M#7")
            .unwrap_or_else(|| panic!("queue row M#7 must render:\n{}", driver.screen()));
        driver.dispatch(UiEvent::MouseDown {
            widget: None,
            button: MouseButton::Right,
            position: Point::new(x, y),
            modifiers: Modifiers::default(),
        });
        driver.press_named(quadraui::NamedKey::Down);
        driver.press_named(quadraui::NamedKey::Down);
        driver.press_named(quadraui::NamedKey::Enter);

        let board_screen = driver.screen();
        assert!(
            board_screen.contains("BOARD"),
            "#2016: 'View on Board' must switch to the Board view:\n{board_screen}"
        );
        assert!(
            board_screen.contains("Board target issue"),
            "#2016: the Board detail pane must show THIS issue's title — proof \
             `select_issue` actually landed on #7, not just that the Board \
             view opened:\n{board_screen}"
        );
        assert!(
            !board_screen.contains("Decoy issue never queued"),
            "#2016: the OTHER issue's title must not appear — it would if the \
             jump had landed on whatever Board defaults to instead of #7:\n{board_screen}"
        );
    }

    /// #2016: jumping away from the Queue panel must not disturb queue
    /// state — no reorder, no optimistic mutation. Compares the row order
    /// before the jump against the order after jumping to the Pipeline and
    /// switching back to the Queue panel.
    #[test]
    fn tuidriver_queue_jump_to_pipeline_leaves_queue_order_unchanged() {
        use quadraui::tui::testing::driver_with_shell;
        let mut app = make_app_with_drive_queue(
            BoardData {
                open_issues: vec![OpenIssue {
                    repo_name: "myrepo".to_string(),
                    number: 7,
                    title: "Jump test issue".to_string(),
                    body: String::new(),
                    labels: vec!["coord".to_string()],
                    state: "open".to_string(),
                    milestone_number: None,
                    milestone_title: None,
                    body_truncated: false,
                    body_len: None,
                    // #1941: fields added to the generated wire DTO; not exercised by this test.
                    synced_at: None,
                }],
                pipeline_repos: vec![("myrepo".to_string(), "acme/myrepo".to_string())],
                ..BoardData::default()
            },
            queue_fixture_json_middle_row_7(),
        );
        app.pipeline_issues = vec![PipelineIssue {
            number: 7,
            title: "Jump test issue".to_string(),
            body: String::new(),
            repo_slug: "acme/myrepo".to_string(),
            coord_repo: Some("myrepo".to_string()),
            matched_labels: vec!["coord".to_string()],
            all_labels: vec!["coord".to_string()],
            is_closed: false,
            body_truncated: false,
            body_len: None,
        }];
        app.rebuild_board_sidebar();
        app.rebuild_pipeline_sidebar(None);
        app.active_view = SidebarView::Queue;

        let mut driver = driver_with_shell(app, CoordApp::shell_config(), 140, 40);
        let before = driver.screen();
        let before_order: Vec<usize> = ["M#6", "M#7", "M#8"]
            .iter()
            .map(|needle| {
                before
                    .find(needle)
                    .unwrap_or_else(|| panic!("{needle} must render before the jump:\n{before}"))
            })
            .collect();
        assert!(
            before_order.windows(2).all(|w| w[0] < w[1]),
            "sanity: rows must render in position order before the jump:\n{before}"
        );

        let (x, y) = driver
            .find("M#7")
            .unwrap_or_else(|| panic!("queue row M#7 must render:\n{}", driver.screen()));
        driver.dispatch(UiEvent::MouseDown {
            widget: None,
            button: MouseButton::Right,
            position: Point::new(x, y),
            modifiers: Modifiers::default(),
        });
        driver.press_named(quadraui::NamedKey::Down);
        driver.press_named(quadraui::NamedKey::Down);
        driver.press_named(quadraui::NamedKey::Enter);
        assert!(
            driver.screen().contains("PIPELINE"),
            "sanity: the jump must have landed on the Pipeline view:\n{}",
            driver.screen()
        );

        // Back to the Queue panel.
        click_activity_icon(&mut driver, QUEUE_ICON);
        let after = driver.screen();
        let after_order: Vec<usize> = ["M#6", "M#7", "M#8"]
            .iter()
            .map(|needle| {
                after
                    .find(needle)
                    .unwrap_or_else(|| panic!("{needle} must still render after the jump:\n{after}"))
            })
            .collect();
        assert!(
            after_order.windows(2).all(|w| w[0] < w[1]),
            "#2016: the Queue panel's row order must be unchanged after \
             jumping away and back — no reorder, no optimistic mutation:\n{after}"
        );
    }

    #[test]
    fn tuidriver_queue_j_moves_the_cursor_and_shift_j_moves_the_entry() {
        // Two different verbs on the same letter — the distinction the
        // overlay already draws, carried across so muscle memory survives.
        let mut driver = queue_driver(queue_fixture_json(), 200, 30);
        driver.press(quadraui::Key::Char('j'));
        driver.render();
        driver.press(quadraui::Key::Char('J'));
        driver.render();
        let screen = driver.screen();
        // The write is a queued `coord` invocation whose effect only lands
        // on the next `/board` poll, so the observable-on-screen half is the
        // toast naming the exact move.
        assert!(
            screen.contains("moving myrepo #702"),
            "#1866: `J` over the second row must dispatch a move for THAT \
             row (`j` having moved the cursor to it first):\n{screen}"
        );
    }

    #[test]
    fn tuidriver_queue_shift_k_at_position_zero_reports_nothing() {
        // Note this is `position == 0`, not "first row of the panel": the
        // grid hides `done` entries but the CLI still speaks in whole-queue
        // positions, so the panel's top row is only un-movable when it also
        // happens to sit in slot 0. Getting that wrong would show a toast
        // promising a move that clamps to a no-op.
        let mut driver = queue_driver(
            r#"[{"repo_name": "myrepo", "issue_number": 701, "position": 0,
                 "state": "waiting"},
                {"repo_name": "myrepo", "issue_number": 702, "position": 1,
                 "state": "waiting"}]"#,
            200,
            30,
        );
        driver.press(quadraui::Key::Char('K'));
        driver.render();
        let screen = driver.screen();
        assert!(
            !screen.contains("moving myrepo"),
            "#1866: a row already in slot 0 cannot move up; no command, and \
             therefore no toast claiming one was sent:\n{screen}"
        );
    }

    #[test]
    fn queue_title_column_uses_what_the_client_already_knows() {
        // The wire `drive_queue` row carries no title — it is a raw table
        // dump. Rather than adding a fetch (the one thing this panel must
        // not do), the title comes from data already in memory.
        let mut data = BoardData::default();
        let mut a = make_assignment("running");
        a.repo = "myrepo".to_string();
        a.issue_number = 701;
        a.issue_title = "TITLE-FROM-ASSIGNMENTS".to_string();
        data.assignments = vec![a];

        let app = make_app_with_drive_queue(
            data,
            r#"[{"repo_name": "myrepo", "issue_number": 701, "position": 0,
                 "state": "running"},
                {"repo_name": "myrepo", "issue_number": 999, "position": 1,
                 "state": "waiting"}]"#,
        );
        let rows = app.queue_rows();
        assert_eq!(rows[0].cells[2], "TITLE-FROM-ASSIGNMENTS");
        assert_eq!(
            rows[1].cells[2], QUEUE_EMPTY_CELL,
            "#1866: an unknown title must render as an em dash — a blank \
             cell and a failed paint look identical"
        );
    }

    #[test]
    fn queue_selection_tracks_the_highlight_when_the_queue_shrinks() {
        // The queue shrinks under this panel on every poll (an entry
        // finishes and drops out of the pending set). The row the renderer
        // highlights and the row a verb acts on must not diverge.
        let mut app = queue_app(queue_fixture_json());
        app.queue_sel = app.queue_rows().len() - 1;
        let tail_before = app.queue_selected_row().map(|r| r.issue_number);
        assert_eq!(tail_before, Some(705));

        // Next poll: the queue is down to two pending rows, so `queue_sel`
        // now points past the end.
        app.data.drive_queue = serde_json::from_str(
            r#"[{"repo_name": "myrepo", "issue_number": 701, "position": 0,
                 "state": "running"},
                {"repo_name": "myrepo", "issue_number": 702, "position": 1,
                 "state": "waiting"}]"#,
        )
        .expect("poll fixture must parse");

        assert_eq!(
            app.queue_selected_row().map(|r| r.issue_number),
            Some(702),
            "#1866: a stale `queue_sel` must clamp to the tail — the same \
             row the renderer highlights — not resolve to nothing while the \
             highlight stays visible"
        );
    }

    // ── #1867 (Q-2): Queue panel detail pane ────────────────────────────
    //
    // Black-box `TuiDriver` tests, in-crate, reusing the Q-1 fixtures above
    // (`queue_fixture_json`, `queue_app`, `queue_driver`, `QUEUE_ICON`) plus
    // `reports_wheel` — the wheel-dispatch helper is panel-agnostic, just a
    // `UiEvent::Scroll` at a position.

    /// Q-2 variant of `queue_driver` that also seeds `data.open_issues` —
    /// the detail pane's fast path (`CoordApp::queue_issue_body_list`).
    fn queue_driver_with_issues(
        data: BoardData,
        drive_queue_json: &str,
        w: u16,
        h: u16,
    ) -> quadraui::tui::testing::TuiDriver<impl quadraui::AppLogic> {
        use quadraui::tui::testing::driver_with_shell;
        let app = make_app_with_drive_queue(data, drive_queue_json);
        let mut driver = driver_with_shell(app, CoordApp::shell_config(), w, h);
        click_activity_icon(&mut driver, QUEUE_ICON);
        driver.render();
        driver
    }

    /// One `open_issues` row with the given body — the detail pane's
    /// synced-row fast path.
    fn open_issue(repo: &str, number: u64, title: &str, body: &str) -> OpenIssue {
        OpenIssue {
            repo_name: repo.to_string(),
            number,
            title: title.to_string(),
            body: body.to_string(),
            state: "open".to_string(),
            labels: Vec::new(),
            milestone_number: None,
            milestone_title: None,
            body_truncated: false,
            body_len: None,
            // #1941: fields added to the generated wire DTO; not exercised by this test.
            synced_at: None,
        }
    }

    /// Flatten a `ListView`'s rendered text into one string, for
    /// placeholder-text assertions that don't care about row boundaries.
    fn list_text(list: &ListView) -> String {
        list.items
            .iter()
            .flat_map(|i| i.text.spans.iter().map(|s| s.text.clone()))
            .collect::<Vec<_>>()
            .join("")
    }

